window.__D("text/igrot-rebbe/c063",{"p":[[1200970074,"ח'תשנב\n\n<p>ב\"ה, עשתי עשר חדש באחד לחדש, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו ימים ספורים לפני יום ההילולא של כ\"ק מו\"ח אדמו\"ר, אשר אז הוא יום העלי' מדרגא לדרגא, כמרומז בכ\"מ ומבואר בכתבי האריז\"ל.</p>\n<p>וכיון אשר ע\"פ דברי אדמו\"ר הזקן (באגה\"ק שלו סי' ז\"ך וביאורו) ע\"י התקשרות אל הצדיק, וצדיקא דאתפטר אשתכח בכלהו עלמין יתיר מבחיוהי, רוח אייתי רוח ואמשיך רוח, חיים רוחניים והרהורי תשובה ומעש\"ט, וכן גם במילי דעלמא.</p>\n<p>מובן מזה שעליית הצדיק מביאה גם לעליית כל אלו אשר רוחם אמשיך רוח, עלי' במילי דשמיא ובמילי דעלמא,</p>\n<p>וכל הקרוב קרוב - (ע\"י ההתחזקות והוספה בהליכה בדרך ישרה אשר הורנו מדרכיו והליכה באורחותיו) - קודם לברכה.</p>\n<p>וביחוד בצדיק נשיא ישראל, אשר בהיותו חי על פני האדמה הי' בהנהגה דאב לבנים לכל אחד ואחת מישראל, בדאגה לעניניהם דעוה\"ז ולעניניהם דחיי עוה\"ב, בשייכות והתקשרות דרבי וחסיד ועד להאופן - דמאור ואור, התקשרות פנימי' ועצמי'.</p>\n<p>בברכת חדש טוב ולבשו\"ט מהתועדות-הילולא פעילה בשעתה ובכל השנה הבע\"ל.</p>\n<p><b>מנחם שניאורסאהן</b></p><p>* * *</p>\n<p>בודאי נתקבל מכתבי ולאח\"ז המברק ע\"ד השו\"ב ב... וז\"ע נודעתי שא' מהם נמצא עתה באהקת\"ו. ובטח יבררו ויצרפו כו' ויתוקן הדורש תיקון.</p>\n<p>בכלל אין עניני להתערב בכהנ\"ל, ומה אעשה שהמשיכוני בכ\"ז. וכיון <b>שעי\"ז</b> הגיעתני שמועה לא טובה ע\"ד הסדרים שם וכו' - מחובתי לעורר ובכפילא עד\"ז, והרי כת\"ר הי' הסרסור כו'.</p>\n<h4><i><b>ח'תשנב</b></i></h4>\n<p>כללי פרטי. ונדפס בסה\"מ באתי לגני ח\"א ע' שנג.</p>\n<p><b>קונטרס ג.. לו:</b> אג\"ק אדמו\"ר מוהריי\"צ ח\"ב אגרת תלב. ח\"ד אגרת תתקצ.</p>\n<p><b>בשייכות והתקשרות:</b> ראה גם לעיל ח\"כ אגרת ז'תקה.</p>\n<p><b>בודאי.. הסרסור כו':</b> קטע זה למו\"ה שי' זוין. אגרות נוספות אליו - לעיל ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>ע\"ד השו\"ב:</b> ראה גם לקמן אגרת ח'תשצט.</p>\n<p><b>עשתי.. לחדש: </b>סמוך למיתה - דמשה רעיא מהימנא - ספרי ר\"פ דברים.</p>\n<p>מכתב זה נכתב גם בז' שבט, ובאה עליו ההערה:</p>\n<p><b>ז' שבט: </b>ר' אליעזר אומר.. בז' שבט מת משה (יל\"ש בשלח טז, לה. וראה מג\"א סתק\"פ סק\"ח. ולפלא שבמכילתא (בדפוסים שראיתי) נשמטה דעת ר\"א).</p>\n<p><b>כמרומז.. ומבואר: </b>ראה ג\"כ נ\"כ השו\"ע יו\"ד סו\"ס שע\"ו וסו\"ס ת\"ב. בכתבי האריז\"ל בכוונת קדיש יתום. מכ' כ\"ק מו\"ח אדמו\"ר בהקדמת קונטרס ג ובסוף קונטרס לו.</p>\n<p><b>מדרכיו.. באורחותיו: </b>לשון אגה\"ק שם. ולהעיר מזח\"ב רטו, רע\"א. זח\"ג ס\"פ קדושים.</p>\n<p>לקו\"ת שה\"ש (יב, ב).</p>\n<p><b>דעוה\"ז.. עוה\"ב: </b>ראה ב\"מ לג, א.</p>\n<p><b>בשייכות והתקשרות כו': </b>ראה שיחת שמח\"ת תרצ\"ד אות ב. כ' כסלו תרצ\"ד אות ח (לקו\"ד כרך א).</p>"],[1200970075,"ח'תשנג\n\n<p>ב\"ה, עשתי עשר חדש באחד לחדש, ה'תשכ\"ד</p><p>... המשקה שקיבל - פשוט שאין למכרו לא\"י (ער\"פ) ולכן - לחלקו לפני זה.</p>\n<h4><i><b>ח'תשנג</b></i></h4>\n<p>נדפסה בשערי הלכה ומנהג ח\"ב ע' צו.</p>\n<p><b>המשקה שקיבל:</b> מכ\"ק אדמו\"ר הכ\"מ.</p>\n<p><b>שאין למכרו:</b> ראה גם לקו\"ש חט\"ז ע' 129 ואילך. שערי הלכה ומנהג ח\"ב ע' צז.</p>"],[1200970076,"ח'תשנד\n\n<p><i>[ו' שבט תשכ\"ד]</i></p>\n<p>... שילמד תנ\"ך וכיו\"ב לשומעים שישבו בגילוי ראש וכו' - מובן שאין נ\"ל כלל. ובפרט שכו\"כ מהם ישבו כהנ\"ל לא מתוך אונס וכיו\"ב. וד\"ל.</p>\n<h4><i><b>ח'תשנד</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 493.</p>"],[1200970077,"ח'תשנה\n\n<p><i>[ז' שבט תשכ\"ד]</i></p>\n<p>התחלת הנחת תפילין - יכול להתחיל שבוע מקודם מהרגיל - ויהא בשעטו\"מ.</p>\n<h4><i><b>ח'תשנה</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"א ע' 357.</p>\n<p><b>התחלת הנחת תפילין:</b> במענה לשאלה: כשבתוך ב' החדשים הקודמים לבר-מצוה - אשר נוהגים להתחיל אז בהנחת תפילין - חל חול המועד.</p>"],[1200970078,"ח'תשנו\n\n<p>ב\"ה, ז' שבט ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום י\"ז טבת והקודמו.</p>\n<p>... במענה לשאלותיו: בנוגע לבתו תי' - הרי דתיות פטורות מגיוס (ע\"פ מש\"נ דברים כב, ה. שם כג, י. טו). והאומרות שאעפ\"כ כיון שרוצות הן לעזור לאה\"ק - לכן תתגייסנה, הנה ע\"פ מש\"נ כנ\"ל - הוא בדוגמת הרוצה לכבות שריפה, ר\"ל, ע\"י שפיכת נפט, מכיון שגם זה... נוזל כמים. וד\"ל.</p>\n<h4><i><b>ח'תשנו</b></i></h4>\n<p><b>מגיוס:</b> לצבא.</p>\n<p><b>הוא בדוגמת:</b> ראה גם לעיל חכ\"א אגרת ז'תת. חי\"ג אגרת ד'תקלה, ובהנסמן בהערות שם.</p>"],[1200970079,"ח'תשנז\n\n<p>ב\"ה, ח' שבט תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מה' שבט עם הפ\"נ שיקרא בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע,</p>\n<p>בו כותב אודות מחשבות של דאגה וכו'.</p>\n<p>ולפלא גדול ובפרט שהרי זכה ולמד כמה זמן בישיבה הק' תומכי תמימים (וקדושה אינה זזה ממקומה) כולל לימוד תורת החסידות המבארת ענין ההשגחה פרטית ושהוא יתברך עצם הטוב ומטבע הטוב להיטיב וכו' ומה טוב שילמוד סי' כ\"ג בספר תהלים עם כמה מפרשים ומזמן לזמן יחזור על סימן זה.</p>\n<p>כן מהנכון אשר יבדקו את התפילין שלו - באם לא נעשה כזה במשך שנים עשר חדש האחרונים -</p>\n<p>והרי הימים ימי סגולה בסמיכות ליו\"ד שבט יום הילולא של כ\"ק מו\"ח אדמו\"ר שעל הציון הק' שלו יזכירוהו.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תשנז</b></i></h4>\n<p><b>ולמד.. וקדושה:</b> ראה גם לקו\"ש חי\"ד ע' 313. וש\"נ.</p>"],[1200970080,"ח'תשנח\n\n<p>ב\"ה, ערב יום ההילולא של כ\"ק מו\"ח אדמו\"ר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד הווח אי\"א נו\"מ בחור מעם ומורם<br>\nמעם ודורש טוב<br>\nלעמו בעל מדות תרומיות ענף עץ אבות<br>\nמו\"ה שניאור זלמן<br>\nשליט\"א</p>\n<p>שלום וברכה!</p>\n<p>לקראת יום ההילולא, עת רצון, רצוני, כמנהגי, לחדש ולהדק את היחסים אשר בינינו בכתב עכ\"פ.</p>\n<p>והרי יום ההסתלקות של צדיק הוא יום סגולה, כביאור רבנו הזקן באגה\"ק סימן ז\"ך וביאורו, שלאחרי ההסתלקות, כאשר סרו ההגבלות הבאות ע\"י הגוף, אזי ההתקשרות עם צדיקא דאתפטר היא במדרגה נעלה יותר, הן במילי דשמיא והן במילי דעלמא, וכל הקרוב קרוב קודם לברכה. וכ' שי' הרי זכה להכיר את כ\"ק מו\"ח אדמו\"ר ובתור אדמו\"ר והן במילי דעלמא והן במילי דשמיא, מאז ביקורו של כ\"ק מו\"ח אדמו\"ר באה\"ק ת\"ו, וכרשום בזכרוני סיפר לי כ', אשר (אדרבה) ההתחלה הייתה ששמע אז לראשונה מאמר דא\"ח ממנו. ואף שלפי דברי כ' הי' הענין אז בבחינת מקיף, הרי ביארו נשיאי חב\"ד אשר מאמר חסידות נעמט מגיע לנשמה בכל ה' דרגות שלה נר\"ן ח\"י, שיחידה שבנפש היא אמתיות ענין המקיף.</p>\n<p>ועל פי מה שכותב בעל ההילולא בשיחתו קודש מי\"ט כסלו (צ\"ג, אות י\"ז) שחמש דרגות הנשמה הנ\"ל מכוונים הם כנגד ד' עולמות אבי\"ע ועולמות הא\"ס שלמעלה מהאצילות, כי איש הישראלי עולם מלא הוא כולל כל חמשה עולמות אלו.</p>\n<p>והיחידה שבנפש היא מקיף החודר בתכלית הפנימיות ועד העקב שבנפש ועד העקב שבגוף.</p>\n<p>ויהי רצון שזכות בעל ההילולא (כולל פי' החסידותי בזה - הזיכוך שפעל) יעמוד לכאו\"א בהמצטרך לו.</p>\n<p>בכבוד ובברכה.</p>\n<p>בהזדמנות זו אביע ת\"ח עבור הפ\"ש ע\"י הרב הילעוויץ והרב גורודצקי - שיחיו, כולל הנחת-רוח פנימי מנקודת הפ\"ש ששלח לי אשר - כלשון שנמסר לי - \"עמד במבחן בקשר עם הביקור הידוע\". ומסיימים בטוב.</p>\n<h4><i><b>ח'תשנח</b></i></h4>\n<p><b>מו\"ה שניאור זלמן:</b> שזר. אגרות נוספות אליו - לעיל ח'תרפב, ובהנסמן בהערות שם.</p>\n<p><b>ביקורו.. באה\"ק:</b> בקיץ תרפ\"ט. ראה גם ס' התולדות אדמו\"ר מוהריי\"צ ח\"ד ע' 23 ואילך.</p>\n<p><b>בשיחתו.. צ\"ג:</b> לקו\"ד כרך א' כה, ב. וראה גם סה\"מ מלוקט ח\"א ע' רפב. וש\"נ.</p>\n<p><b>פי' החסידותי:</b> ראה גם לקו\"ש ח\"כ ע' 12.</p>\n<p><b>הביקור הידוע:</b> ראה גם לעיל אגרת ח'תשלא.</p>"],[1200970081,"ח'תשנט\n\n<p><i>[נוסח המברק לקראת יו\"ד שבט תשכ\"ד]</i></p>\n<p>התועדויות פעילות וכפרשת השבוע ביד רמה ובשירה ובשיר להשם תורת הנגלה והחסידות.</p>\n<p>בברכה</p>\n<p><b>/מקום החתימה/</b></p>\n<h4><i><b>ח'תשנט</b></i></h4>\n<p>נדפס בסה\"מ באתי לגני ח\"א ע' שעב.</p>"],[1200970082,"ח'תשס\n\n<p>ב\"ה, ט\"ו שבט תשכ\"ד</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמו\"ה אפרים אליעזר שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מי\"ג שבט וכן הקודמו מה' שבט עם המצורף אליו,</p>\n<p>ות\"ח על שלחו לי, ומוחזר בזה, לאחרי העתקת המילי מעלייתא דברי כ\"ק מו\"ח אדמו\"ר בעל ההילולא דיו\"ד שבט דאזלינן מני',</p>\n<p>ובמיוחד התרשמתי ממה שמצאתי בסיום הענין, אשר בהד' אמות הקרובים לראש ההר מרגישים וכו',</p>\n<p>שע\"פ המדובר בההתועדות, מיוסד על הלכה בהנוגע לד' אמות קונות, ה\"ה עוד יותר מאשר עומד אחורי הכותל, שהרי כותל מפסיק אפילו כשיש בו חרכים מפסיק בכו\"כ ענינים משא\"כ בד' אמות, וק\"ל.</p>\n<p>להזכירו הגירסא דרבא באל\"ף, כמדומה הזכרתי בפירוש בהתועדות שכן הוא ביל\"ש (מ\"ב, ג) ר\"ח פסחים (קיז, א) ויש לעיין בדקדוקי סופרים לעוד מקומות.</p>\n<p>בברכה לענין יום זה דר\"ה לאילנות, כי האדם עץ השדה ובמיוחד ת\"ח (תענית ז, א).</p>\n<h4><i><b>ח'תשס</b></i></h4>\n<p><b>מו\"ה אפרים אליעזר:</b> יאלעס, פילדלפיא. אגרות נוספות אליו - לעיל חכ\"ב ח'רפח, ובהנסמן בהערות שם.</p>\n<p><b>בההתועדות:</b> דמוצש\"ק פ' בשלח י\"א שבט.</p>\n<p><b>בהד' אמות.. מרגישים וכו':</b> ראה גם לקמן אגרת ח'תתקעב.</p>\n<p><b>הלכה.. קונות:</b> בבא מציעא י, א.</p>\n<p><b>הגירסא דרבא:</b> בתניא פ\"ז (יא, ב): וכמו שעשה רבא לתלמידיו שאמר לפניהם מילתא דבדיחותא תחלה ובדחי רבנן. וראה גם ליקוט פירושים לתניא שם.</p>"],[1200970083,"ח'תשסא\n\n<p>ב\"ה, ט\"ו שבט תשכ\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מו\"ה יעקב שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מיום עשירי בשבט, יום הילולא של כ\"ק מו\"ח אדמו\"ר נשיא ישראל, עם הפ\"נ שיקרא בעת רצון על הציון הק' של בעל ההילולא,</p>\n<p>ובעמדנו בט\"ו בשבט, ראש השנה לאילנות, והרי האדם עץ השדה, ובמיוחד - ת\"ח -</p>\n<p>יהי רצון שתתחדשנה כל הפעולות הצומחות מ(לימוד - שהוא המביא לידי מעשה - לימוד) עץ חיים היא תורתנו תורת חיים, ויבואו פירות טובים מאי פירות - מצות,</p>\n<p>ומהתעוררות וכחות דיום ראש השנה זה - יומשך בכל ימות השנה הבע\"ל.</p>\n<p>והרי הוא גם יום דקיימא סיהרא באשלמותא.</p>\n<p>בברכה לבשו\"ט.</p>\n<h4><i><b>ח'תשסא</b></i></h4>\n<p><b>מו\"ה יעקב:</b> אורינשטיין, ירושת\"ו. אגרות נוספות אליו - לעיל חכ\"א ח'קח, ובהנסמן בהערות שם.</p>\n<p><b>ובעמדנו:</b> ראה גם ב' האגרות שלאח\"ז.</p>\n<p><b>מ(לימוד:</b> ראה קידושין מ, ב.</p>\n<p><b>ובמיוחד - ת\"ח: </b>תענית ז, א.</p>\n<p><b>פירות - מצות: </b>סוטה מו, סע\"א.</p>"],[1200970084,"ח'תשסב\n\n<p>ב\"ה, ט\"ו שבט תשכ\"ד</p><p>ברוקלין.</p><p>הנהלת צעירי אגודת חב\"ד סניף ירושלים<br>\nעיה\"ק בארצנו<br>\nהקדושה תבנה ותכונן במהרה בימינו ע\"י<br>\nמשיח צדקנו<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבם מערב יום ההילולא של כ\"ק מו\"ח אדמו\"ר נשיא ישראל,</p>\n<p>בו כותבים על אשר נבחרו להנהלה האמורה, ורצון ונדבת לבם הט' להרחיב פעולות הפצת המעינות וכו'.</p>\n<p>ויהי רצון שתקוים בהם במילואה הבטחת חז\"ל הבא לטהר, וידוע דיוק רבנו הזקן, לטהר אחרים, מסייעין לו.</p>\n<p>אלא - כיון שלהוספה בהצלחת כל ענין - צריכה להיות הוספה מתאימה</p>\n<p>באתעדל\"ת, בודאי שהם יעשו כל התלוי בם להמשכת ההחלטה מהלב לכל האברים, והרי לבא פליג לכל שייפין.</p>\n<p>ועד להמעשה בפועל, בפעולות יום יום, והרי המעשה הוא העיקר, ועוד דעשי' לעילא.</p>\n<p>וכמובן מפרשיות שבועות אלה בהם מדובר ע\"ד הקדמת נעשה לנשמע וגודל הענין דנעשה קודם לנשמע.</p>\n<p>ובעמדנו בט\"ו בשבט, ראש השנה לאילנות, והרי האדם עץ השדה, ובמיוחד - ת\"ח -</p>\n<p>יהי רצון שתתחדשנה כל הפעולות הצומחות מ(לימוד - שהוא המביא לידי מעשה - לימוד) עץ חיים היא תורתנו תורת חיים, ויבואו פירות טובים מאי פירות - מצות.</p>\n<p>ומהתעוררות וכחות דיום ראש השנה זה - יומשך בכל ימות השנה הבע\"ל.</p>\n<p>והרי הוא גם יום דקיימא סיהרא באשלמותא.</p>\n<p>בברכת הצלחה בעבודתם הק' האמורה ובאופן אשר תשים לפניהם, ובברכה לבשו\"ט ומפורטות בכל האמור.</p>\n<h4><i><b>ח'תשסב</b></i></h4>\n<p><b>לבא פליג:</b> ראה זח\"ג רכא, ב.</p>\n<p><b>המעשה הוא העיקר:</b> אבות פ\"א מי\"ז.</p>\n<p><b>דעשי' לעילא:</b> ראה זח\"א קטו, א. זח\"ג קח, ב.</p>\n<p><b>מ(לימוד:</b> ראה קידושין מ, ב.</p>\n<p><b>לטהר.. רבנו הזקן.. לו: </b>גירסא זו הובאה ונתבארה בלקו\"ת (דברים פט, ד).</p>\n<p><b>יום יום: </b>עיין לקו\"ת במדבר (יט, ג-ד).</p>\n<p><b>ובמיוחד ת\"ח: </b>תענית ז, א.</p>\n<p><b>פירות - מצות: </b>סוטה מו, סע\"א.</p>\n<p><b>תשים לפניהם: </b>ראה הל' ת\"ת לרבנו הזקן (סיום וחותם שלהן). תו\"א ר\"פ ואלה המשפטים.</p>"],[1200970085,"ח'תשסג\n\n<p>ב\"ה, ט\"ז שבט תשכ\"ד</p><p>ברוקלין.</p><p>מרת בענדער תחי'</p>\n<p>ברכה ושלום!</p>\n<p>אין ענטפער אויף אייער בריף פון /28;1amp&amp; מיט דאס בייגעלייגטע.</p>\n<p>בעת רצון וועט מען אייך מזכיר זיין אויף דעם ציון הק' פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע לויט דעם אינהאלט פון אייער שרייבען, און השם יתברך זאל אייך העלפען איר זאלט אנזאגען גוטע בשורות אין דעם,</p>\n<p>און בפרט אז מיר קומען דאך פון דעם טאג ט\"ו בשבט, וועלכער רופט זיך ראש השנה לאילנות (דער אנהויב יאר פאר ביימער) און ס'איז דא א שטארקע ענליכקייט פון מענשן צו ביימער, איז דעריבער דאס אריינטראכטען זיך אין דעם אנפאנג יאר פון ביימער, דארף בריינגען צו <b>וואקסען</b> און שטייגען אין אידישקייט, און זעהן עס זאל זיין גוטע פירות, און ווי חכמנו ז\"ל ערקלערן ס'זאל זיין גוטע מעשים מקיים זיין מצות, און אויך אין א וועג וואקסען אין דעם און צוגעבען אין דעם.</p>\n<p>און דער זכות הצדקה (לויט דער בייגעלייגטער קבלה) זאל אייך ביישטיין אין דעם.</p>\n<p>בברכה צו גוטע בשורות.</p>\n<h4><i><b>ח'תשסג</b></i></h4>\n<p><b>מרת בענדר:</b> ניו הייווען.</p>\n<p><b>ווי חכמנו:</b> סוטה מו, סע\"א.</p>"],[1200970086,"ח'תשסד\n\n<p>ב\"ה, יום ה' לסדר כל אשר דבר ה' נעשה, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>האברך יוסף שי'</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל מכתבך על דבר הסדרים ביום הבר-מצוה שלך, וכמובן לכל לראש אמירת דברי תורה, מאמר חסידות, ונתינה לצדקה.</p>\n<p>וכיון שההמשך יהי' ביום שבת-קדש פ' יתרו הבע\"ל, אשר נקודתה היא מתן תורתנו, תורת חיים, וההמשך לאחר זה בהתחלת פ' ואלה המשפטים.</p>\n<p>וידועים דברי רבנו הזקן בעל התניא (פוסק בנסתר דתורה) והשלחן ערוך (פוסק בנגלה דתורה) אשר על בני ישראל ללמוד מפרשת השבוע הוראות בעניני השבוע,</p>\n<p>יהי רצון אשר תמיד יהי' לנגד עיניך אחד מעקרי הלימודים מפרשיות האמורות, והוא:</p>\n<p><b>כי לי בני ישראל עבדים -</b> אומר הקב\"ה - ולא עבדים לעבדים. שלכן אסור לאיש הישראלי לומר אהבתי את כו', אשר נרמזו בזה כל עניני עולם הזה, שלא להיות מאלו אשר מפני תאוותם לעניני העולם נעשים עבדים ומשועבדים להיצר ועניניו,</p>\n<p>אלא לזכור תמיד - אנכי <b>ה' אלקיך</b> אשר הוצאתיך מארץ מצרים <b>מבית עבדים.</b></p>\n<p>להיות בן חורין אמתי, וכהוראת חכמינו ז\"ל אין לך בן חורין אלא מי שעוסק בתלמוד תורה, שהלימוד מביא לידי מעשה - קיום המצוות.</p>\n<p>וזכות הצדקה תעמוד לך בכל האמור ביתר שאת וביתר עוז ובאופן דמעלין בקדש.</p>\n<p>בברכה אשר הוריך שיחיו ירוו ממך רוב נחת אמתי נחת יהודי חסידותי, ולבשורות טובות בכל האמור.</p>\n<h4><i><b>ח'תשסד</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ו ע' 314 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>כי.. לעבדים:</b> בהר כה, נה. קידושין כב, ב.</p>\n<p><b>וכהוראת חכמינו:</b> אבות פ\"ו מ\"ב.</p>\n<p><b>שהלימוד:</b> קידושין מ, ב.</p>\n<p><b>דמעלין בקודש:</b> ברכות כח, א. וש\"נ.</p>"],[1200970087,"ח'תשסה\n\n<p>ב\"ה, כ' שבט תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>מיט גרויס פארוואונדערונג האב איך געלייענט אייער בריף פון יום ג', אז אייך דאכט זיך, אז (באוואוסטזיניג אדער אומבאוואוסזיניג) האט מען אייך געגעבען ניט די ריכטיגע אינפארמאציע, אלענספאל דער אינהאלט פון אייער בריף איז איבערגעגעבען געווארען צו דער הנהלה פון דער ישיבה צו וועמען די גאנצע אנגעלעגענהייט באלאנגט.</p>\n<p>איך מוז אויסדריקען מיטן גרויס פארוואנדערונג אויף א אידן וועלכע האבען געזעהן די חסדים פון השם יתברך און די נסים, וועלכע האט זיי געראטעוועט פון גוישע הענט, און האט זיי באשאנקען מיט א גוטען זון א בעל כשרון, איז ווי עס זעהט אויס די איינציגע זאך וואס באאומרוהיגט זיי, איז ווי אזוי קען מען עם נויטען און איינארדנען, אז דער זון זאל אוועקנעמען א טייל פון זיינע יונגע יארען פון לערנען אונזער הייליקער תורה תורת <b>חיים</b> און אוועקגעבן דאס נאר אויף וכו' און די אלע \"חשבונות\" מיט וועלכע מ'וויל בארעכטיגען, אזא איינשטעלונג, איז דאך דאס ניט פאר די וועלכע האבען געזעהן און איבערגעלעבט יענע צייט - ניט היינט געדאכט - און ניט זיי דארפען זיך לאזען אפנארען פון דעם יצר הרע.</p>\n<p>איך וויל ניט מאריך זיין אין דעם גאנצען ענין, וואס ווי געזאגט באלאנגט דאס צו דער הנהלה פון דער ישיבה און די עלטערן, וויבאלד אבער איר האט בארירט די פראגע און ווילט דאס פארבינדען מיט די עשרת הדברות פון כבד את אביך ואת אמך, קען איך זיך ניט ערלויבען אריבערגיין מיט שווייגען און אויסגעדריקט מיין אויבענדערמאנטע פארוואונדערונג.</p>\n<p>און השם יתברך זאל העלפען אז סוף כל סוף זאל יעדער איד מאן און פרוי, דערזעהען דעם אמת'ן אמת, דאס איז תורתנו הק' תורת אמת און מקיים זיין אירע מצות, אויף וועלכע עס שטייט וחי בהם, און זעהן צו פארשפרייטען זיי אין דער מאקסימאלסטער מעגליכקייט פון צייט אין דער גאנצער אומגעבונג, און אלס ערשטע בנוגע צו קינדער פאר וועלכע מ'טראגט <b>א טיפע נשמה'דיקע אחריות און</b> <b>פאראנטווארטליכקייט,</b> וק\"ל.</p>\n<p>בברכה צו גוטע בשורות אין דאס אלץ אויבען געזאגטע.</p>"],[1200970088,"ח'תשסו\n\n<p>ב\"ה, כ\"א שבט, תשכ\"ד</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח והרה\"צ רב פעלים וכו' וכו'<br>\nהרנ\"מ שליט\"א</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ה טבת - שהגיעני ז\"ע - בו כותב אודות אמוץ ילד ע\"י...</p>\n<p>בהוקרה ובכבוד ובברכה.</p>\n<p>בכללות הענין דאימוץ ילדים, פלא שלא מצאתי עד עתה מי שישים לב להבא להלן. ואף שכבר נדפסו כמה שו\"ת ומפורטות בכמה דינים המשתלשלים מענין האמוץ, אין מעורר על עצם הענין וכו'.</p>\n<p>והחששות שנתעוררו אצלי, שהרי האמוץ בימינו אלה הוא לא כבדורות שלפנינו, בקיום המצוה דלגדל יתום בתוך ביתו וכו', אשר כל הסביבה כולל גם המגודל ידעו שאין זה ההורים שלו. ועתה הוא <b>להיפך</b> - עושים ככל האפשרי להעלים פרט זה, ולא עוד אלא שע\"פ לחץ רופאים, האומרים שהם מומחים לעניני נפש, מחליטים שאסור לגלות זה להילד (כי עלול לפגוע במנוחת נפשו וכו'), - שמזה תוצאה, שתהי' הנהגתם עם המאומץ כאילו הי' זה ילידם ממש, שבמילא ישנם כל הענינים דיחוד, חבוק ונישוק וכו' וכו' בכל יום. ובודאי אי אפשר להזהר מזה באם אפילו המאמצים יראי שמים באמת.</p>\n<p>ואפילו באם מגלים להמאומץ כשיגדל שאין זה הוריו, צע\"ג האפשר לשנות אז הנהגה שהיתה מכמה שנים מקודם. והרי בהאמור - איסור דרבנן ודאי ישנו, ולדעת הרמב\"ם גם איסור דאורייתא. והרי גם בנוגע לאיסור דרבנן - שאני כשהוא דבר ההולך ונשנה ונשלש וכו'. (נוסף על המובא ומבואר בספרי נגלה בזה - יעוין ג\"כ אגרת התשובה לרבנו הזקן פרק ז'). ולכאורה ע\"פ האמור צע\"ג בכל ענין האמוץ, וטעם דהיתירא בכגון זה דמוטב שיהיו שוגגין וכו' - לכאורה ברור, אשר כו\"כ ימנעו מאמוץ באם ידעו את הנ\"ל. ועיין ג\"כ שו\"ע או\"ח סי' תר\"ח ובשו\"ע רבנו הזקן שם כמה גדרים במוטב שיהיו וכו' - שע\"פ זה אין ההיתר דמוטב וכו' ברור בנדון דידן. ובודאי לדכוותי' דכת\"ר - האריכות אך למותר.</p>\n<h4><i><b>ח'תשסו</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ב ע' 244 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>הרנ\"מ:</b> פרלוב, ברוקלין. האדמו\"ר מנובומינסק.</p>\n<p><b>דאימוץ ילדים:</b> ראה גם לעיל אגרת ח'תש, ובהנסמן בהערות שם.</p>\n<p><b>ולדעת הרמב\"ם:</b> הלכות איסורי ביאה פכ\"ב ה\"ב. וראה אוצר הפוסקים (כרך ט') הל' אישות ריש סכ\"ב. וש\"נ.</p>"],[1200970089,"ח'תשסז\n\n<p>ב\"ה, יום ג', סדרה ופרשה אם כסף תלוה, ה'תשכ\"ד</p><p>ברוקלין נ.י.</p><p>חברה גמילות חסדים שומרי שבת<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל מכתבם עם המצורף אליו, בם מודיעים ע\"ד האסיפה השנתית במוצש\"ק מברכים ראש חדש אדר.</p>\n<p>וע\"פ הוראת חכמינו ז\"ל במשנתם, באחד באדר משמיעים על השקלים ועל הכלאים, דלכאורה אינה מובנת השייכות דשני הענינים, ועד - שמשמיעים ומכריזים על שניהם ביום אחד.</p>\n<p>ויש לבאר בדרך אפשר- ע\"פ דברי מפרשי טעמי המצות, באיסור ענין כלאים, כי משנים עי\"ז חוקי הטבע ודרכיו, שהטביע בורא עולם ומנהיגו, שיהי' דשא עשב ועץ עושה פרי למינהו דוקא.</p>\n<p>ובהתאם לזה - משמיעים על השקלים, שיהיו קרבנות צבור מתרומה חדשה דוקא, שאין לערב שנה בשנה.</p>\n<p>ואדרבה - מקדימה המשנה (שגם ההקדמה - תורה היא), ההכרזה על השקלים להכרזה על הכלאים,</p>\n<p>אף שלכאורה דין קדימה להכרזה על הכלאים, כי ההקדם בזה מוכרח (בכדי שלא יזרע בנתיים כלאים) וכן האיסור - כל השנה תדיר הוא, וכאו\"א מוזהר ע\"ז - מה שאין כל זה בשקלים, ובפרט שאפשר לשקלם גם באיחור זמן, כיון שתורמין גם על העתיד לגבות.</p>\n<p>ומובן ע\"פ האמור - כי בכדי שתהי' הנהגה הרצוי' בעולם, ההתחלה היא ותלוי זה בהנהגת בני ישראל בעניניהם באופן זה, ומרוחניות - משתלשל בגשמיות.</p>\n<p>ולכן <b>לאחרי</b> שבי\"ד מביאים בפועל הלכה של תורה ושולחים בכל ערי ישראל ומכריזין שיביאו שקליהן, כי אין לערב שנה בשנה בנוגע לקרבנות וענינים רוחנים אשר בעולם, משתלשל מזה גם לזרע (הצומח) בארץ (הדומם) שיהי' למינהו דוקא.</p>\n<p>ועד\"ז במצות גמ\"ח, שהיא מעלה הגדולה בצדקה השקולה כנגד כל הקרבנות -על ידי שבני ישראל עושים בזה בסבר פנים יפות, הנה מעשיית המצוה - משתלשל למטה בהמצטרך לאדם בכל צרכיו בבני חיי ועד למזוני (לחם- צומח) ועד לקיום ההבטחה, עשר בשביל שתתעשר כפשוטה - בכסף וזהב (דומם),</p>\n<p>ובמדה כנגד מדה - בספ\"י של מלכו של עולם - כל הנ\"ל, רוויחי.</p>\n<p>בברכת הצלחה בעבודתם בכל האמור ומתוך שמחה וטוב לבב</p>\n<p><b>מ. שניאורסאהן</b></p><p>מצו\"ב שעק - השתתפותי, בל\"נ בהנ\"ל.</p>\n<h4><i><b>ח'תשסז</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ד ע' 1273 ח\"ו ע' 338 והושלמה עפ\"י צילום האגרת. וראה גם לקמן אגרת ח'תשעה. לקו\"ש חי\"ז ע' 227 ואילך.</p>\n<p><b>שגם ההקדמה:</b> ראה גם לקמן אגרת ט'כז. וש\"נ.</p>\n<p><b>ומרוחניות:</b> ראה תניא פ\"ג.</p>\n<p><b>ההבטחה:</b> שבת קיט, א.</p>\n<p><b>במשנתם: </b>ריש מס' שקלים.</p>\n<p><b>ע\"פ דברי: </b>רמב\"ן קדושים יט, יט. (זח\"ג פו, ב). וראה חולין ס, סע\"א (בהנוגע <b>לדינם</b> של דשאים).</p>\n<p><b>ובמדה:</b> פס\"ז שמות ג, ו.</p>\n<p><b>על העתיד לגבות: </b>שקלים ספ\"ג.</p>\n<p><b>מעלת הגדולה: </b>שו\"ע יו\"ד סרמ\"ט ס\"ו.</p>\n<p><b>השקולה.. הקרבנות: </b>ראה תניא פל\"ד ופל\"ז.</p>\n<p><b>בסבר פנים יפות: </b>שו\"ע שם ס\"ג.</p>\n<p><b>משתלשל למטה: </b>ולא עוד אלא שפועל גם למעלה מעלה כו' (עיין אגה\"ק ס\"ח).</p>\n<p><b>שמחה וטוב לבב: </b>שו\"ע שם.</p>"],[1200970090,"ח'תשסח\n\n<p>ב\"ה, כ\"ג שבט, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>חברה ש\"ס של ק\"ק שארית ישראל אשר<br>\nבעיר באלטימאר<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בנועם נודעתי ע\"י רבם הרה\"ג וו\"ח אי\"א נו\"נ צנמ\"ס וכו' הרמ\"מ שי' הכהן, אשר מתכוננים לחגיגת סיום מס' נדרים, בשבוע דשבעה באדר הבע\"ל, בו נולד משה רבנו מושיען של ישראל,</p>\n<p>אשר קבל תורה מסיני ומסרה כו' עד - לתלמידים הרבה אשר במשך כל הדורות,</p>\n<p>כי אף אשר במעמד הר סיני, היו נוכחים את אשר ישנו פה ואת אשר איננו פה כמבואר בדברי רז\"ל, הרי משה רועה נאמן, הוא העומד בין ה' ובינינו עומד ומחבר ומגיד ומפרש את דבר ה' לבני ישראל,</p>\n<p>אשר כל אחד ואחת מהם <b>מושבע</b> הוא מהר סיני לקיים התורה ומצותי'. אשר השבעה זו היא גם נתינת כח מלמעלה לקיים המצות, וכמבואר בריש מסכת נדרים, דאפילו מה שנשבע מעצמו לקיים המצוה, הרי עי\"ז מזרז עצמו, עאכו\"כ המושבע מנותן התורה ובורא האדם.</p>\n<p>ואף שלכאורה קשה: באם מה שמושבע ועומד מהר סיני אינו מספיק שיוכל לעמוד במלחמת היצר ולנצחו - מה תוסיף השבעת עצמו לקיים המצוה?</p>\n<p>- מובן הביאור ממרז\"ל בסיום המסכת: אם איתי' דעבד איסורא (כי לא עמד במלחמת היצר היצר ועבר על רצון בוראו, בכל זה) ארכוסי הוא מירכס, כדי שלא <b>יראה</b> קלונו - כי לפעמים מורא בשר ודם ובושה מלפניו - פועל יותר מאשר מורא שמים וכו',</p>\n<p>שדוגמת זה הוא הנשבע לקיים המצוה - שבועת הנשמה בגוף בשר ודם ובפרט שמגלה וגם מבטא השבועה בפה ולשון ושפתים הגשמים.</p>\n<p>ועובדא הנ\"ל (דסיום המס') דאשה ובעלה נואף - השייכות לעניננו ורמז מתאים במיוחד, שהרי מעמד הר סיני זוהי חתונתו של הקב\"ה עם עמו ישראל, אשר נצטוו: ועשיתם אותם (מצות התורה) ולא תתורו אחרי וכו' אשר אתם <b>זונים</b> אחריהם, אזהרה מכל חטא ועון ופשע, אשר שרשם והתחלתם הוא חטא הראשון דנחש הקדמוני ובא נחש על חוה והטיל בה זוהמא, וכמרומז ומבואר בכ\"מ, ובהר סיני פסקה זוהמתן.</p>\n<p>ויהי רצון אשר כאו\"א בתוככי כלל ישראל יתחזק ויוסיף בלימוד התורה באופן המביא לידי מעשה - קיום המצות, זאת התורה להבדיל בין הטמא ובין הטהור ו(בסוג הטהור) בין הקדש ובין החול - רצון וצרכי הנשמה ורצון וצרכי הגוף,</p>\n<p>אשר דוקא בשותפות שניהם יחד ניתנה להם התורה,</p>\n<p>ובאופן אשר השותפין <b>(בה\"א הידיעה)</b> ירצו שניהם לעשות מחיצה - בכל לבבך בשני יצריך -</p>\n<p>אבל עובי המחיצה - ה\"ז מתאים למנהג (וטבע) המדינה: יש מי שאין יצרו עומד לנגדו כגון שהוא מתמיד בטבעו ומחוסר הרגש הנאה בטבעו - ולכן דיו שלא ישתקע בצרכי גופו (שאותו אוהב יותר בטבעו) ע\"י הציווי מהר סיני; למטה ממנו זה אשר יצרו בוער וכו' - הזקוק לזירוזי נפשי' ע\"י שמשביע את עצמו וכו'</p>\n<p>אבל גם בזה הובטחנו כי לא ידח - שבודאי סופו לעשות תשובה וכפס\"ד בחותם וסיום המסכתא: איתתא שריא.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תשסח</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ח ע' 269 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>הרמ\"מ שי':</b> פלדמן.</p>\n<p><b>בו נולד:</b> מגילה יג, ב.</p>\n<p><b>אשר קבל:</b> אבות רפ\"א.</p>\n<p><b>אשר השבעה זו:</b> ראה גם לקמן אגרת ט'ה.</p>\n<p><b>שהרי מעמד:</b> ראה תענית כו, ב.</p>\n<p><b>ולימוד:</b> קידושין מ, ב.</p>\n<p><b>השותפין:</b> ראה בבא בתרא בתחלתה.</p>\n<p><b>כי לפעמים: </b>ראה ברכות כח, ב. תניא פמ\"א (נז, סע\"א).</p>\n<p><b>הנשמה בגוף כו': </b>להעיר מהראב\"ע (תהלים קיט, קו): נשבעתי ואקיימה.. אז (בהר סיני) הי' בכח ועתה במעשה.</p>\n<p><b>זונים אחריהם: </b>דאין שייך בפנוי' (דאין הלכה כ' אלעזר - יבמות סא, ב). וראה לקו\"ת שלח (נג, ג).</p>\n<p><b>ובא נחש: </b>ראה שבת שם. זח\"א נב, ב.</p>\n<p><b>דוקא בשותפות: </b>שבת פח, ב ושם. וראה ס' ערה\"כ ערך שותפין.</p>\n<p><b>שאין יצרו כו': </b>ראה תניא פט\"ו, ט\"ז, למ\"ד.</p>\n<p><b>שבודאי סופו: </b>ראה הלכות תלמוד תורה לרבנו הזקן פ\"ד סוס\"ג.</p>"],[1200970091,"ח'תשסט\n\n<p>ב\"ה, ערב שבת- קודש מברכים אדר,</p><p>ברוקלין, נ.י.</p><p>פ' משפטים ופ' שקלים, תשכ\"ד<br>\nצום יערלעכן באנקעט פון דער ליידיס אקזילערי פון<br>\nבראנזוויל און איסט ניו-יארק פאר די ליובאוויטשער<br>\nישיבות תומכי תמימים,</p>\n<p>שלום וברכה!</p>\n<p>אין צוזאמענהאנג מיט דעם יערלעכן באנקעט, י' אדר הבע\"ל, שיק איך מיין וואונטש און ברכה צו אלע מיטהעלפער און אנטיילנעמער תי'. דער אויבערשטער זאל העלפן, אז די אונטערנעמונג זאל זיין מיט גרויס הצלחה אין אלע הינזיכטן.</p>\n<p>די סדרה פון דעם שבת - פ' משפטים - איז א פארזעצונג פון מתן-תורה, ווי אונזערע חכמים, זכרונם לברכה, זאגן אויף די ווערטער <b>ואלה</b> המשפטים, אז דער \"ואו\" איז א הוספה און המשך.</p>\n<p>אויך די סדרה <b>תשא</b>, וואס מען לייענט פון איר דעם שבת די <b>פרשת שקלים,</b> דערמאנט אונז מתן תורה, ווען דער אויבערשטער האט אונז געגעבן די צווייטע לוחות.</p>\n<p>בא מתן תורה זיינען אידן געווארן אמת <b>פריי</b> דורכדעם וואס זיי האבן גענומען אויף זיך צו זיין <b>עבדי ה'</b> - צו דינען דעם אויבערשטן אליין. און דעריבער איז דער ערשטער ענין וואס די סדרה משפטים באהאנדלט גלייך פון אנהויב פון אנהויב - דער ענין פון אן <b>עבד עברי,</b> א אידישער קנעכט, און ווי אזוי א איד זאל ניט וועלן זיין פארשקלאפט צו א צווייטן, און זאל ניט וועלן זאגן <b>אהבתי את אדוני.. לא אצא</b> <b>חפשי -</b> \"איך האב ליב מיין האר (מיט אלע וועלטלעכע באקוועמלעכקייטן)... איך וויל ניט ארויס אויף דער פריי\" - נאר זאל דווקא וועלן זיין פריי צו דינען דעם אויבערשטן אליין. און דערפאר זאגט די תורה, אז א איד וואס וויל בלייבן א קנעכט צו א צווייטן קנעכט, דארף מען דורכבויערן זיין אויער, דעם אידישן אויער וואס האט געהערט דעם ג-טלעכן אנזאג ביים בארג סיני: <b>כי לי בני ישראל עבדים -</b> \"אידן זיינען מיינע - ג-ט\"ס - קנעכט\".</p>\n<p>א לעבעדיקער מוסטער פון אן <b>עבד ה'</b> איז מרדכי היהודי, ווי די מגילה פון פורים דערציילט אונז: <b>ומרדכי לא יכרע ולא ישתחווה -</b> \"מרדכי קניט ניט און בוקט זיך ניט\" צו המן \"ען מיט זיין עבודה זרה.</p>\n<p>צו דערציען א \"מרדכי פאלק\" (עם מרדכי) קען מען בלויז דורך א תורה טרייען חינוך, א חינוך על טהרת הקדש, וואס דאס איז דער צוועק און די אויפגאבע פון די ישיבות \"תומכי תמימים\" ליובאוויטש, וואס ווערט אנגעפירט ב\"ה מיט גרויס הצלחה.</p>\n<p>און גרויס איז דער זכות פון יעדן איינעם און איינער וועלכע האבן א חלק אין דעם.</p>\n<p>השם יתברך זאל אייך מצליח זיין איר זאלט פארזעצן אייער גוטע ארבעט אין א פארגרעסערטער מאס, און בזכות זה וועט איר אויך געבענטשט ווערן אין א פארגרעסערטער מאס, אין אלץ וואס איר און אייערע בני-בית שיחיו נויטיגען זיך, בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה להצלחה ולבשורות טובות</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תשסט</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"א ע' 291 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>אונזערע חכמים:</b> שמו\"ר פ\"ל, ג. פרש\"י עה\"פ.</p>"],[1200970092,"ח'תשע\n\n<p>ב\"ה, כ\"ו שבט, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>כבוד המתפללים - והגבאים בראשם - דבית</p>\n<p>הכנסת</p>\n<p>פועלי אגודת ישראל אשר בקרית שלום ע\"י</p>\n<p>תל אביב</p>\n<p>בארצנו הקדושה, תבנה ותכונן במהרה</p>\n<p>בימינו על ידי</p>\n<p>משיח צדקנו,</p>\n<p>ה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בשעתו נמסר לי הפ\"ש ע\"י הרה\"ח אי\"א נו\"נ בעל מידות הרח\"ן שי' קובלסקי וכן ההודעה אודות סדר אמירת תהילים וכו'.</p>\n<p>וגודל הענין דאמירת תהילים ולימוד שיעורי תורה בבית הכנסת בודאי אין דורש אריכות, שהרי מבואר הוא בכ\"מ בספרינו הק' ובבאור היטב במכתבי ושיחות הק' של כ\"ק רבותינו נשיאינו נשיאי ישראל.</p>\n<p>ולא באתי אלא לזירוז ולהעדפה ע\"פ מאמר חז\"ל אין מזרזין אלא למזורזין: זירוז בהשתדלות להרבות המשתתפים בשיעורי לימוד בתורה, בנגלה דתורה ובפנימיות התורה שבדורנו נתגלתה בתורת החסידות, וכן - לכלול כל מתפללי בית הכנסת באמירת תהילים.</p>\n<p>אמירת תהילים בכל יום לאחרי תפלת הבקר - כפי שנחלק התהילים לימי החודש - ובשבת קודש מברכין החדש בבקר קודם התפלה, סיום כל חמישה ספרי תהילים, שהם מכוונים לחמשה חומשי תורה.</p>\n<p>ויש לקשר האמור גם בפרשת שבוע זה, פרשת תרומה לה', לבנין המקדש והמקדש דאיקרי משכן,</p>\n<p>אשר ענינם - כדרז\"ל - מקום תפלה ועד אשר <b>כל</b> התפילות מכוונות לקדש הקדשים: מקום הארון - הוא ענין לימוד התורה,</p>\n<p>וספר תהילים הרי זה - התפילה שבתורה.</p>\n<p>בכבוד ובברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תשע</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"א ע' 317 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מאמר חז\"ל:</b> מכות כג, א.</p>\n<p><b>והמקדש:</b> עירובין בתחלתה.</p>\n<p><b>תורה בבית הכנסת: </b>ראה ברכות ח, א.</p>\n<p><b>במכתבי ושיחות: </b>ראה קובץ מכתבים תהילים.</p>\n<p><b>שהם מכוונים: </b>כנקבע בה\"יהי רצון\" שלאחרי אמירת תהילים. וראה קידושין ל, סע\"א.</p>\n<p>ד\"ה לפיכך נקראו, תרצ\"ט.</p>\n<p><b>כל התפלות מכוונות לקדש הקדשים: </b>שו\"ע או\"ח רסצ\"ד.</p>\n<p><b>הארון.. לימוד התורה: </b>ראה שהש\"ר פ\"ה ט\"ו: על שני לוחות אבנים.. כתובים בין כל דיבור ודיבור פרשיותי' ודקדוקי' של תורה.</p>\n<p><b>התפלה שבתורה: </b>ראה ברכות ג, ב. פסחים קיז, א.</p>"],[1200970093,"ח'תשעא\n\n<p>ב\"ה, כ\"ו שבט, תשכ\"ד</p><p>ברוקלין</p><p>הרה\"ג וו\"ח אי\"א נו\"נ רב פעלים מו\"ה דוב<br>\nיהודא שי'</p>\n<p>שלום וברכה!</p>\n<p>לאחרי הפסק נתקבל מכתבו מכ\"ג שבט, בו כותב אודות ענין בית הכנסת.</p>\n<p>הנה אף כי בכלל אין עניני להתערב בכגון זה ועד ששואלים דעתי במפגיע וכו', אבל כיון שכפי השערתי הרקע איז <b>ניט</b> קיין גלאטער, ועוד וג\"ז עיקר שהמושכל ראשון צ\"ל להרבות בבתי כנסיות שעל טהרת הקדש בפרט בתקופתנו זו ובמחנם הט' וכיו\"ב, לכן חוויתי דעתי בהתאם לזה שאף שבאופן זמני נכון הדבר ומכמה טעמים שיהי' כת\"ר בביהכ\"נ אודותה כותב, אבל בהנוגע לקביעות - ע\"פ הנ\"ל טוב שייסד ביהכ\"נ לעצמו ואפילו אם יהי' ראשיתו מצער הרי אחריתו ישגה עכ\"פ ויהי רצון שישגה מאד.</p>\n<p>מובן שאין לדיין אלא מה שעיניו רואות ואין זה מסוג עניני בכלל להעמיד דוקא על חוות דעתי כהאמורה, אלא שמאידך גיסא איני רשאי להעלים הנראה לי לטובת כל המעונינים והמעורבים - שיהי' באופן הנ\"ל, ואפילו באם אי אפשר שיהי' ביהכ\"נ בביתו ממש, צריך להשתדל ע\"ד ביהכ\"נ שיכול להיות עצמאי יותר מאשר בביהכ\"נ דעתה.</p>\n<p>וכיון שמתקרבים אנו לחדש אדר אשר נקודתו ואמצע החדש הם ימי הפורים, דמשלוח מנות איש לרעהו, ואחד הטעמים בזה קירוב לבב כל ישראל ועד לאחדות אמיתית, יהי רצון שתתחיל פעולה זו תיכף מש\"ק מברכין חדש אדר הלוך והוסיף ועד דקיימא סיהרא באשלמותא באמצע החדש.</p>\n<p>בכבוד ובברכה לבשו\"ט בכל האמור ולנחת אמיתי מבנו שי' אודותו כותב - בתוככי כל יו\"ח שי' - ביחד עם זוגתו הרבנית תחי'.</p>\n<h4><i><b>ח'תשעא</b></i></h4>\n<p><b>מו\"ה דוב יהודא:</b> שוחט, טורונטו. אגרות נוספות אליו - לעיל חי\"ד ד'תתקסח, ובהנסמן בהערות שם.</p>\n<p><b>ראשיתו מצער:</b> ראה גם לעיל חכ\"א אגרת ז'תתקנח, ובהנסמן בהערות שם.</p>\n<p><b>שאין לדיין:</b> בבא בתרא קלא, א. וש\"נ.</p>\n<p><b>ואחד הטעמים:</b> ראה מנות הלוי (לר\"ש אלקבץ) עה\"פ אסתר ט, כז. ועוד.</p>"],[1200970094,"ח'תשעב\n\n<p>ב\"ה, כ\"ח שבט, תשכ\"ד</p><p>ברוקלין</p>\n<p>שלום וברכה!</p>\n<p>אין ענטפער אויף אייער בריף פון ט\"ז שבט, אין פארבינדונג מיט דער פראגע פון אדאפטען א קינד וכו'.</p>\n<p>אזוי ווי דער צוגאנג פון אדאפטען א קינד, אין אונזער צייט, איז אז מ'שטריינגט אן אלעס צו מאכען דעם קינד באקוועם, אויך אין דעם אז ער זאל פילען, אז דאס זיינען זיינע אמת'ע נאטירליכע עלטערן, זעה איך ניט אפילו נאכן באווארענען די אנדערע זאכען, ווי מ'קען אויסמיידען עניני יחוד, קירוב נשיקה וכו' [אפילו ווען דער קינד זאל וויסען אז דאס זיינען אדאפטירער עלטערן, עאכו\"כ ווי עס פירט זיך איצטער ווי געזאגט אז מען באהאלט דאס אויס פון דעם קינד], און מ'קען זאגען אז דאס איז אונמעגליך, און דאס זיינען דאך זיכערע איסורים מדרבנן, און טיילווייז [לויט אנדערע פוסקים] - פון זיי אויך מן התורה איסורים.</p>\n<p>און ווי געזאגט אויבען, איז דאס אלץ אפילו נאכן באווארענען די אנדערע זאכען, ווי דער הערקונפט פון קינד און די כשרות זיינע וכו'.</p>\n<p>איז לויט ווי געזאגט אויבען זעה איך ניט קיין מעגליכקייט צו העלפען וועמען אין אזא אנגעלעגנהייט, און אין געגענטייל אז מ'דארף גאר אפריידין פון דעם, און געוויס איז די אריכות אין דעם ניט נויטיג.</p>\n<p>חאטש איר דערמאנט ניט וועגן דעם, רעכין איך אז איר האט זיך באראטען מיט א דאקטאר ספעציאליסט אויף דעם געביט בנוגע צו האבען קינדער און בפרט אז אין די לעצטע יארען זיינען ענדעקט געווארען נייע באהאנדלונגס מיטלען אויף דעם געביט, ויהי רצון איר זאלט קענען אנזאגען גוטע בשורות אין דאס אלעס אויבען געזאגטע.</p>\n<p>בעת רצון וועט מען אייך מזכיר זיין אויף דעם ציון הק' פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע צו דער ערפילונג פון אייער הארץ פארלאנג צום גוטען.</p>\n<p>ומהנכון אז מ'זאל בודק זיין אייערע תפילין און אויך די מזוזות אין אייער דירה אז זיי זאלען זיין אלע כשר'ה ווי דער דין איז, און אייער פרוי תחי' זאל אפהיטען דעם גוטען מנהג פון אידישע פרויען צו געבען אויף צדקה יעדער מאל פאר ליכט צינדען ערב שבת און ערב יום טוב.</p>\n<p>בברכה לבשו\"ט בכל האמור</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תשעב</b></i></h4>\n<p><b>אדאפטן א קינד:</b> ראה גם לעיל אגרת ח'תש, ובהנסמן בהערות שם.</p>\n<p><b>לויט אנדערע פוסקים:</b> ראה לעיל אגרת ח'תשסו, ובהנסמן בהערות שם.</p>"],[1200970095,"ח'תשעג\n\n<p>ב\"ה, שלהי שבט, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד מר בן ציון שי' המכונה פרופ. דינור</p>\n<p>שלום וברכה!</p>\n<p>זה עתה נתקבל התדפיס מתוך הקובץ האישיות ודורה, ות\"ח עבור שימת לבבו לשלחו לי.</p>\n<p>ובהזדמנות זו עלי להתנצל שמפני כמה סיבות, ובעיקר מפני רבוי הטרדות, לא הבעתי לו ע\"ע תודתי הלבבית בעד התדפיסים וספרים הקודמים ששלח לי. ותקותי שדנני לכף זכות, כהוראת חכמינו ז\"ל.</p>\n<p>ובהיותי עדין תחת רושם יום ההילולא של כ\"ק אדמו\"ר, ועל יסוד דברי האריז\"ל קדושה אינה זזה ממקומה, ובפרט על פי הפתגם השגור בפי חסידים \"איינמאל א חסיד - אלעמאל א חסיד\" ארשה לי להעירו על זכותו שזכה והצליח להסתופף באהלה של ישיבת תומכי תמימים כמה חדשים; ועל פי האמור בטוחני שלא רק שלא זזה ממקומה, אלא זזה ממקומה למעליותא, ומוצאת בטוי מזמן לזמן בפעולות טובות אשר \"מתנגד\" לא הי' מסוגל להן, כי זקוקות הן לאור וחום אשר מקורם בחסידות ועניני'.</p>\n<p>ומענין לענין באותו ענין, והוא אישור בת\"ח (ובהמשך לאישור) ספרו \"עולם ששקע\", אשר מובן מהכתוב לעיל שאפשר לומר כן רק בנוגע לעולם גשמי וחומרי ואפילו בנוגע לביהמ\"ק - <b>באם</b> הוא זה עשוי מעצים ואבנים, ואם גוילין נשרפין אבל האותיות קיימות ולא עוד אלא שחוזרות למטה ונכתבות מחדש, ועד - באופן של חקיקה בלבות אלפים ורבבות בני ובנות ישראל, ועד לחקיקה באותיות של אש, וכשתי הגרסות שבזה. אש לבנה (וגם) אש שחורה, שהרי צריכים להיות שני הקוים, ימין מקרבת ושמאל דוחה, ובכללות יותר סור מרע ועשה טוב, ובעבודת הנפש הוא ענין האהבה והיראה, אשר הדרך לבוא אליהן היא מהנושאים העקריים של ספר תניא קדישא.</p>\n<p>מובן שבהתענינות מיוחדה קראתי העמודים האחרים בספרו הנ\"ל בהם מדבר על זמן שהותו, כנ\"ל, בד' אמות של קדושת תו\"ת ולמרות שכמה ביטויים \"לכאורה\" חילופם עיקר וראוי הי' להחליפם בהפכיים מהם, אבל ביחד עם זה הנה גם מבטויים אלה נתחזק אצלי הרגש אשר עדין נמצא תחת השפעת תקופה ההיא ועניני', ועד כדי כך - שמוצא הכרח להגן על עצמו מפני ההשפעה דאז, ולהצדיק צעדים ופעולות וכולי וכולי. במילים אחרות, נראה לי שגם בעולמו הפרטי לא שקע עולם זה, ויהי רצון שלא לבד שלא יתנגד להשפעה זו, אלא אדרבה, ינצלה ככל האפשריות שלו, ועד לסיסמה הידועה - דהפצת המעינות. ואם יצא פס\"ד עלי ש(מזמן לזמן) אהי' בעל דמיון וכו' יהי רצון שהכתוב לעיל אף שלכאורה ובקריאה ראשונה יאמר שפרי דמיון הוא, יומשך לעולם המעשה, והרי בתקופתנו רבת הפלאות ותופעות בלתי מצויות - נפגש הדמיון ונתגשם במעשה - שהוא העיקר.</p>\n<p>וכאן מקום אתי לאשר בתודה רבה גם קבלת כרך א' מחבורו \"ישראל בגולה\".</p>\n<p>וכדרך בני ישראל ארשה לעצמי לבא גם בזה בהערה, מיוסדת על השוני אשר בספרי גדולי ישראל - הראשונים וגם מימי הבינים, והוא אשר בנוגע לעניני תורה או ענינים הקשורים בתורה - דנים עליהם כאילו היו חלק מחיי היום-יום והזמן של זה הדן עליהם, וכדוגמת השקו\"ט בעניני קדשים וטהרות כמה מאות שנים לאחרי חורבן בית המקדש, וכדומה. וכן לא רק בנוגע למפרשי המשנה וכולי, אלא אפילו בספרי שאלות ותשובות שגם בהם נמצאים כמה וכמה ענינים הדנים על דברים שאירעו לבני ישראל במדבר וכו'. מהאמור מובן שכשמצטטים מספרים שנתחברו בתקופה מסויימת שדנים הם באיזה ענין או מאורע, אין מזה ראי' כלל שבזמנו של בעל הספר הי' ענין זה אקטואלי בחיי היום יום, וצריך בירור מיוחד בראיות צדדיות שאכן כן הוא.</p>\n<p>הדברים אמורים בפרט כלפי שאלת קריאת התורה שכ' נוגע בה בספרו.ענין זה נזדמן לידי - שעה שנתקבל ספרו וחפשתי גם בו ומצאתי שכאילו בזמן רש\"י הי' סדר קריאת התורה אחת לשלש שנים, והראי' על זה - שרש\"י דן בזה בספר פלוני וכולי. ועל פי האמור לעיל אין מזה הוכחה כלל. ואף שכעת איני בענין זה, אבל כמדומה לי - ברור שזמן רב לפני תקופת רש\"י, ובפרט במדינות בהן דר רש\"י והסמוכות להן, היתה הקריאה לסיום התורה אחת לשנה.</p>\n<p>דרך אגב, אבל באותו ענין, בודאי ידוע גם לכ' אשר יש בזה גירסא דשלש שנים וחצי שנה, וציוני המקומות לזה בספרו של מרדכי מרגליות על החילוקים שבין אנשי מזרח ובני א\"י חילוק מח.</p>\n<p>אתענין לדעת אם יש לכ' חומר היסטורי על דבר המלכה של שבטים יהודים בצפון אפריקה (סהרה) בימי הבינים. כרשום בזכרוני הי' שמה כהן או דומה לזה, וסוף סוף נפלה ג\"כ במלחמה ופסקה מלכותה.</p>\n<p>כנהוג בישראל לסיים מעין הפתיחה, הנני מרשה לעצמי לצרף בזה עלון תדפיס שהופיע בקשר עם הילולת כ\"ק מו\"ח אדמו\"ר.</p>\n<p>בכבוד ובברכה.</p>\n<p><i>ח'תשעג</i></p>\n<p>חלקה נדפס בלקו\"ש חל\"ג ע' 250 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מר.. דינור:</b> אגרות נוספות אליו - לעיל חי\"ז ו'תכח. חי\"א ג'שצו.</p>\n<p><b>כהוראת חכמינו:</b> אבות פ\"א מ\"ו.</p>\n<p><b>דברי האריז\"ל.. תמימים:</b> ראה לקו\"ש חי\"ד ע' 313. וש\"נ.</p>\n<p><b>וכשתי הגרסות:</b> ראה ירושלמי שקלים פ\"ו ה\"א. פרש\"י ברכה לג, ב מתנחומא בראשית א.</p>\n<p><b>ימין מקרבת:</b> ראה סוטה מז, א. וש\"נ.</p>\n<p><b>במעשה:</b> אבות פ\"א מי\"ז.</p>"],[1200970096,"ח'תשעד\n\n<p>ב\"ה, אדר\"ח אדר, תשכ\"ד</p><p>ברוקלין</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מיום שהוכפל בו כי טוב עם המצורף אליו, בו כותב אודות בנו התמים...</p>\n<p>ואינו ברור כ\"כ ממכתבו האם שואל גם בשם בנו שי' וזוגתו תחי' כיון שגם ע\"ד נסיעתם מדובר, או שלע\"ע רק בשם עצמו ולאחרי השקו\"ט בזה יתהווה סברות לכאן ולכאן וכו'</p>\n<p>בכל אופן מובן שבעניני שידוך אין על הבן להחליט בעצמו מבלי שמי מההורים יהיו על אתר, וכן לכאורה יש מקום להוודע ע\"י ידידים בשתי המדינות שמזכיר, באם יש איזו הצעות עכ\"פ שמשערים שמשביעות רצון, ורק לאחרי זה לעשות הנסיעה הכרוכה בהוצאות של כספים זמן וכו' ובפרט שהן באה\"ק ת\"ו והן בארצוה\"ב יש לו ידידים וכו' ובהתאם להידיעות שתתקבלנה יהי' קל יותר להחליט איך לפעול.</p>\n<p>ויהי רצון מהשי\"ת המשגיח על כאו\"א בהשגחה פרטית שינחם בהאמור כטוב בכל הפרטים.</p>\n<p>התקוה אף שאין מזכיר ע\"ד ההתועדות דיו\"ד שבט, שעשו כן התועדות, ומתכוננים גם להתועדות דימי הפורים הבע\"ל שמצות היום ביין לכל ראש <b>יינה</b> של תורה, רזין דאורייתא וכמבואר בכ\"מ, והובטחנו הבא להטהר - וידוע דיוק רבנו הזקן לטהר גם אחרים - מסייעין אותו.</p>\n<p>בברכת חדש טוב ופורים שמח ולבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תשעד</b></i></h4>\n<p><b>מצות היום:</b> מגילה ז, ב.</p>\n<p><b>וכמבואר בכ\"מ:</b> ראה גם לקו\"ש חל\"א ע' 179 ואילך. וש\"נ.</p>\n<p><b>והובטחנו.. דיוק:</b> יומא לח, ב. לקו\"ת דרושים לשמע\"צ פח, ב.</p>\n<p><b>במשנתם: </b>ריש מס' שקלים.</p>\n<p><b>ע\"פ דברי: </b>רמב\"ן קדושים יט, יט. (זח\"ג פו, ב). וראה חולין ס, סע\"א (בהנוגע <b>לדינם</b> של דשאים).</p>\n<p><b>על העתיד לגבות: </b>שקלים רפ\"ב וספ\"ג.</p>\n<p><b>מעלה הגדולה: </b>שו\"ע יו\"ד סרמ\"ט ס\"ו.</p>\n<p><b>השקולה.. הקרבנות: </b>ראה תניא פל\"ד ופל\"ז.</p>\n<p><b>בסבר פנים יפות: </b>שו\"ע שם ס\"ג.</p>\n<p><b>משתלשל למטה: </b>ולא עוד אלא שפועל גם למעלה כו' (עיין אגה\"ק ס\"ח).</p>\n<p><b>שמחה וטוב לבב: </b>שו\"ע שם.</p>"],[1200970097,"ח'תשעה\n\n<p>ב\"ה אחד באדר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הנהלת קופת גמילות חסד ע\"י בית הכנסת<br>\nחב\"ד אשר בבני ברק בארצנו הקדושה תבנה<br>\nותכונן במהרה בימינו על ידי משיח צדקנו<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בנועם קראתי הדו\"ח ור\"פ מפעולות הקופה בתקופה שעברה, מכתב יו\"ר הקופה הוו\"ח אי\"א נו\"נ עוסק בצ\"צ רב פעלים וכו' מו\"ה מנחם ישראל שי' - ממוצש\"ק פ' אם כסף תלוה.</p>\n<p>וה\"ז גם מענין יומא דא - אחד באדר, וכהוראת חכמינו ז\"ל במשנתם: באחד באדר משמיעים על השקלים ועל הכלאים,</p>\n<p>והנה לכאורה אינה מובנת השייכות דשני הענינים, ועד - שמשמיעים ומכריזים על שניהם ביום אחד.</p>\n<p>ויש לבאר בדרך אפשר- ע\"פ דברי מפרשי טעמי המצות, באיסור ענין כלאים, כי משנים עי\"ז חוקי הטבע ודרכיו, שהטביע בורא עולם ומנהיגו שיה' דשא עשב ועץ עושה פרי למינהו דוקא,</p>\n<p>ובהתאם לזה - משמיעים על השקלים, שיהיו קרבנות צבור מתרומה חדשה דוקא, שאין לערב קרבנות שנה ועניני' באלו דשנה אחרת.</p>\n<p>ואדרבה - מקדימה המשנה, (שגם ההקדמה - תורה היא), ההכרזה על השקלים להכרזה על הכלאים,</p>\n<p>אף שלכאורה דין קדימה להכרזה על הכלאים, כי ההקדמה בזה מוכרח (בכדי שיעקור הכלאים בהקדם ועוד יותר - בכדי שלא יזרע בנתיים כלאים) וגם איסור זה - כל השנה תדיר הוא, וכאו\"א מוזהר ע\"ז - מה שאין כל זה בשקלים, ובפרט שאפשר לשקלם גם באיחור זמן, ולא עוד אלא שכשהוא תורם את הלשכה - מתכוון לתרום גם על העתיד <b>לגבות</b>.</p>\n<p>ומובן ע\"פ האמור - כי בכדי שתהי' הנהגה הרצוי' בעולם, ההתחלה היא ותלוי זה בהנהגת בני ישראל בעניניהם באופן זה, ומרוחניות - משתלשל בגשמיות.</p>\n<p>ולכן <b>לאחרי</b> שבי\"ד שולחים בכל ערי ישראל ומכריזין שיביאו שקליהן, כי אין לערב שנה בשנה בנוגע לקרבנות וענינים רוחניים אשר בעולם, משתלשל מזה גם בנוגע לזרע (הצומח) בארץ (הדומם) שיהי' למינהו דוקא.</p>\n<p>ועד\"ז במצות גמ\"ח, שהיא מעלה הגדולה בצדקה השקולה כנגד כל הקרבנות - על ידי שבני ישראל עושים בזה בסבר פנים יפות, הנה מעשיית המצוה - משתלשל למטה בהמצטרך לאדם בכל צרכיו בבני חיי ועד למזוני (לחם - צומח) ועד לקיום ההבטחה, עשר בשביל שתתעשר כפשוטה - בכסף וזהב (דומם),</p>\n<p>ובמדה כנגד מדה - בספ\"י של מלכו של עולם - כל הנ\"ל, רוויחי.</p>\n<p>בברכת הצלחה בעבודתם, בכל האמור ומתוך שמחה וטוב לבב.</p>\n<p>מצו\"ב המחאה - השתתפותי, בל\"נ, בהנ\"ל.</p>\n<h4><i><b>ח'תשעה</b></i></h4>\n<p><b>מו\"ה מנחם ישראל:</b> מלוב.</p>\n<p><b>וכהוראת:</b> ראה גם לעיל אגרת ח'תשסז.</p>\n<p><b>שגם ההקדמה:</b> ראה גם לקמן אגרת ט'כז. וש\"נ.</p>\n<p><b>ומרוחניות:</b> ראה תניא פ\"ג.</p>\n<p><b>ההבטחה:</b> שבת קיט, א.</p>\n<p><b>ובמדה:</b> פס\"ז שמות ג, ו.</p>"],[1200970098,"ח'תשעו\n\n<p>ב\"ה, ג' אדר, תשכ\"ד</p><p>ברוקלין</p><p>הוו\"ח אי\"א בעל מדות רב פעלים מו\"ה אשר<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>מזל טוב לבואו ביחד עם ב\"ב שי' ולעלייתו לאה\"ק ת\"ו.</p>\n<p>ויהי רצון שיה' בשעה טובה ומוצלחת בכל הפרטים הן בגשמיות והן ברוחניות, ותקוים בו הבטחת חז\"ל לפום צערא אגרא ומתאים לתוכן מ\"ש אודך ה' וגו' ותנחמני ומתוך בריאות הנכונה שמחה וטוב לבב ירווה רוב נחת יהודי חסידותי מכל יו\"ח שי'.</p>\n<p>ויהי רצון מתאים להענין דמצוה גוררת מצוה (והרי מצוה דפדיון וכו' מצוה רבה היא), שרבים בכמות ורבים באיכות יוציאם השי\"ת מן המיצר אל המרחב בכל הפירושים ובעגלא דידן.</p>\n<p>בברכה לבריאות ולבשו\"ט.</p>\n<p>נ.ב. מתאים לטעם עלייתו לאה\"ק ת\"ו מובן שצ\"ל משך זמן עם משפחתו תחי' ובודאי יכתוב בפרטיות הדרושה.</p>\n<p>ז\"ע נתקבל מכתבו מר\"ח אדר בו מרבין בשמחה ואזכירו בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<h4><i><b>ח'תשעו</b></i></h4>\n<p><b>מו\"ה אשר:</b> ששונקין.</p>\n<p><b>הבטחת חז\"ל:</b> אבות ספ\"ה.</p>\n<p><b>דמצוה:</b> אבות פ\"ד מ\"ב.</p>\n<p><b>מרבין בשמחה:</b> תענית כו, ב.</p>"],[1200970099,"ח'תשעז\n\n<p>ב\"ה, ג' אדר, תשכ\"ד</p><p>ברוקלין</p><p>האברך עזרא בנימין שי'</p>\n<p>שלום וברכה!</p>\n<p>... מכתביו הקודמים להנ\"ל נתקבלו. ונעם לי לראות שמעיין ומדייק דרך לימודו בתניא כו' ואף שבכלל הדיוק בכל תיבה לאנשים כערכנו - הוא רק לאחרי בקיאות בכמה ס' ומאמרי חסידות. ולקושיותיו הרבות באגה\"ת - ידבר בזה עם המשפיעי דא\"ח שנפגש עמהם.</p>\n<p>ולשאלתו בהמבואר בהליקוט לפ' יתרו במעלת המצות לאחרי מ\"ת על לפני מ\"ת, דלכאורה אין שייך זה במצות <b>שנצטוו</b> עליהם לפני מ\"ת (ע\"פ המבואר בליקוט לפ' לך לך): והרי גם במילה וכו' כותב בפיהמ\"ש (חולין ספ\"ז) מעלת מ\"ת -</p>\n<p>והחילוק (בקיצור עכ\"פ): מה שקיימו מעצמן לפני מ\"ת - רק ריחות ורוחניות היו, ולכן במקלות דיעקב וכיו\"ב לא נשארה שום קדושה לאח\"ז. מה <b>שנצטוו</b> לקיימן (<b>ובגשם</b> דוקא) - נשארה קדושה בהגשם גם לאח\"ז (ולכן הוכרח אברהם להשביע באופן דשים ידך תחת ירכי) - אבל רק קדושה שהנברא (המטה) יכול להגיע אלי' (שרש הנבראים), כי גזירה שלא יעלו תחתונים למעלה. לאחרי מ\"ת שענינו ביטול הגזירה - קדשנו <b>במצותיו</b>, שלא בערך שרש הנבראים (ריחות בערך קדושת הבורא).</p>\n<p>מ\"מ היסוד לחילוק הנ\"ל - ראה בליקוטים הנ\"ל.</p>\n<h4><i><b>ח'תשעז</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 326 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>האברך עזרא בנימין שי':</b> שוחט. אגרות נוספות אליו לעיל ח'תשג, ובהנסמן בהערות שם.</p>\n<p><b>בהליקוט לפ' יתרו:</b> נדפס בלקו\"ש ח\"ג ע' 887 ואילך.</p>\n<p><b>בליקוט לפ' לך לך:</b> נדפס שם ע' 757 ואילך.</p>"],[1200970100,"ח'תשעח\n\n<p>ב\"ה, ד' אדר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>כבוד המשתתפים בלימוד הש\"ס אשר בבית<br>\nהכנסת שערי<br>\nאמונה בעיר טורונטה<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בנועם נודעתי מהוו\"ח אי\"א נו\"נ רב פעלים בעל מדות ורב מרץ הר\"א שי' פרשן, אשר מסיימים את הש\"ס, ובודאי כמנהג ישראל גם הם מתכיפין התחלה להשלמה, התחלת הש\"ס, אור ליום הרביעי, פרשה ויקחו אליך שמן זית וגו' להעלות נר תמיד,</p>\n<p>ויהי רצון אשר לימוד התורה, הנגלה והפנימית (מאור שבתורה) המרומזים שניהם בכתוב האמור: להעלות נר, ויקחו שמן זית</p>\n<p>וכמארז\"ל, הרואה שמן זית בחלום יצפה למאור תורה שנאמר שמן זית וגו',</p>\n<p>תורותי אשר <b>טהורות</b> הן, תורה הנגלית ופנימית התורה, כי דברי תורה אינן מקבלין טומאה, ומחויבים בתלמוד תורה תמיד, ביום ובלילה כפשוטם, וביום ובלילה ברוחניות, בזמן שבית המקדש קיים ובזמן הגלות, אשר על אז נאמר השוכן אתם בתוך טומאותם.</p>\n<p>וכמרומז בכתוב ובמבואר במרז\"ל תמיד ואפילו בטומאה,</p>\n<p>ימשיך אורה לכל בני ישראל בכל מושבותיהם.</p>\n<p>וכמרומז בכתוב ומבואר במרחז\"ל למה צריך לנר, בשביל להאיר לנו, להעלות נר תמיד שיהא אורך לפני תמיד.</p>\n<p>לפני בני ישראל דוקא, וכמרומז בכתוב ומבואר ברז\"ל ואתה תצוה את</p>\n<p>בנ\"י - (ישראל דוקא) - מפני שהמליכוני עליהם על הים.</p>\n<p>ומאז ועד עתה פעמיים בכל יום, כשקורין את שמע, בערבין ובשחרית, וכמרז\"ל יקבל עליו עול מלכות שמים, אמליכתי' למעלה ולמטה ולארבע רוחות השמים.</p>\n<p>והקדמה לכל האמור הוא כאמור בכתוב, כתית למאור, וכפירוש רבנו הזקן בעל התניא והשו\"ע: ע\"י כתית (ונפשי כעפר לכל תהי' - נעשה) למאור (פתח לבי בתורתך - ועד למאור שבתורה).</p>\n<p>בכבוד ובפ\"ש כל המשתתפים בחגיגה הכי נעלית האמורה - שליט\"א.</p>\n<h4><i><b>ח'תשעח</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ד ע' 1276 והושלמה עפ\"י העתק המזכירות. וראה גם לקמן אגרת ח'תשפ.</p>\n<p><b>וכפירוש:</b> ראה תורה אור תצוה פא, סע\"ג.</p>\n<p><b>מתכיפין התחלה להשלמה: </b>רשות לחתן בראשית.</p>\n<p><b>והפנימית (מאור: </b>ראה ג\"כ קה\"ע לחגיגה פ\"א ה\"ז בסופה.</p>\n<p><b>הרואה שמן: </b>ברכות נז, א.</p>\n<p><b>טהורות.. טומאה: </b>ראה ערוך ערך אב (א). בהקדמת הרמב\"ם לפיהמ\"ש: טהרות והפכם.</p>\n<p><b>אז נאמר: </b>יומא נז, א. ובזח\"ג קנה, א: הארון.. אע\"ג דאינון סטאן כו'.</p>\n<p><b>ואפילו בטומאה: </b>תו\"כ אמור כד, ב.</p>\n<p><b>למה צריך: </b>תנחומא (באבער) תצוה ד.</p>\n<p><b>מפני שהמליכוני: </b>פסיקתא דר\"כ פ' שקלים.</p>\n<p><b>וכמרז\"ל יקבל: </b>ברכות יג, א. ושם.</p>"],[1200970101,"ח'תשעט\n\n<p>ב\"ה, ה' אדר, תשכ\"ד</p><p>ברוקלין</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ הר\"צ שי'<br>\nהמכונה ד\"ר הרכבי</p>\n<p>שלום וברכה!</p>\n<p>באיחור זמן נתקבל מכתבו, בו כותב אודות שילוח עניני דפוס ובריבוי וכו' לשם וכו' וכו'.</p>\n<p>וכיון שבענין זה ישנם כמה סברות לכאן ולכאן הנני מושך את ידי מלחוות דיעה ומלהשתתף וכו' ואתו רוב הסליחה.</p>\n<p>לפלא שזה מזמן רב שלא נתקבל כל עניני דפוס שבהוצאתו, אף שבטח כמנהגו מאז במשך זמן זה הו\"ל כמה מהם ובטח ישלח ע\"י עו\"ר מכל שהופיע, ותודה מראש.</p>\n<p>ארשה לעצמי על יסוד סגנון חז\"ל עד מאה פעמים- לעורר על מה שנדברנו כ\"פ גודל ענין לימוד פנימיות התורה שבדורנו נתגלתה בתורת החסידות, במיוחד בדורנו רב המבוכות וערעור היסודות וכו' ובפרט בארץ הקדושה עלי' נאמר עיני ה\"א בה מראשית השנה ועד אחרית שנה, וכבר משנים רבות נעשה לימוד זה נפוץ והולך ומוסיף כדברי רבנו הזקן מייסד תורת חב\"ד, אשר תורת החסידות היא נחלת כל עם ישראל כולו, כפירושו כפשוטו לא כענין אשר מייקרים אותו יקר מכל יקר ולכן מצניעים אותו מעין כל וגם מעיני עצמו, ובסגנון הידוע רזא דרזין, כי בדורותינו אלה \" <b>מצוה</b> לגלות זאת החכמה\", גילוי גם בחיי היום יומים דימי החול ועד שיהי' ניכר בכל דרכיך דעהו, ואין הדבר תלוי אלא ברצון כי היכולת נתונה מאז ומקדם, והציווי הרי מבואר הוא בכמה מספרנו הק' ובהדגשה מיוחדת בספרי הגר\"א לא פחות מאשר בספרי רבנו הזקן.</p>\n<p>בברכה לבשו\"ט בכל האמור ובברכת פורים שמח.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תשעט</b></i></h4>\n<p><b>הר\"צ.. הרכבי:</b> אגרות נוספות אליו - לעיל ח'תשיט, ובהנסמן בהערות שם.</p>\n<p><b>לשם:</b> רוסיא.</p>\n<p><b>לפלא:</b> ראה גם לקמן אגרת ח'תתכד.</p>\n<p><b>עו\"ר:</b> עושי רצונו.</p>\n<p><b>סגנון חז\"ל:</b> בבא מציעא לא, א.</p>\n<p><b>כדברי רבנו הזקן:</b> ראה גם לעיל אגרת ח'תשכד, ובהנסמן בהערות שם.</p>"],[1200970102,"ח'תשפ\n\n<p>ב\"ה, ז' אדר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>כבוד המתפללים - והגבאים בראשם - דבית<br>\nהכנסת<br>\nשומרי שבת ומשתתפים בהקביעות עתים<br>\nלתורה<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בנועם נודעתי ע\"י הרה\"ח הוו\"ח אי\"א נו\"נ וכו' הרי\"ל שי' רסקין,</p>\n<p>מהקביעות עתים בלימוד תורתנו הק' ברבים בביהכנ\"ס הנ\"ל,</p>\n<p>וגודל הענין דלימוד שיעורי תורה בבית הכנסת בודאי אין דורש אריכות, שהרי מבואר הוא בכ\"מ בספרינו הק' ובביאור היטב במכתבי ושיחות הק' של כ\"ק רבותינו נשיאינו זצוקללה\"ה נבג\"מ זי\"ע,</p>\n<p>ולא באתי אלא לזירוז ולהעדפה ע\"פ מאמר חז\"ל אין מזרזין אלא למזורזין, זירוז בהשתדלות להרבות מספר המשתתפים בשיעורי לימוד בתורה, בנגלה דתורה ובפנימיות התורה שבדורנו נתגלתה בתורת החסידות, וכן להשתדל לכלול כל מתפללי בית הכנסת בזה.</p>\n<p>ויש לרמז בתחלת וראש פרשת שבוע זה:</p>\n<p>ואתה תצוה גו' ויקחו אליך שמן זית וגו' להעלות נר תמיד,</p>\n<p>לימוד התורה, הנגלה והפנימית (מאור שבתורה) המרומזים שניהם בכתוב האמור: להעלות נר, ויקחו שמן זית</p>\n<p>וכמארז\"ל, הרואה שמן זית בחלום יצפה למאור תורה שנאמר שמן זית גו',</p>\n<p>ומחויבים בתלמוד תורה תמיד, ביום ובלילה כפשוטם, וביום ובלילה ברוחניות, בזמן שבית המקדש קיים ובזמן הגלות, אשר על אז נאמר השוכן אתם בתוך טומאותם.</p>\n<p>וכמרומז בכתוב ומבואר במרז\"ל תמיד ואפילו בטומאה,</p>\n<p>ועי\"ז תומשך אורה לכל בנ\"י בכל מושבותיהם.</p>\n<p>וכמרומז בכתוב ומבואר במאחז\"ל למה צריך לנר, בשביל להאיר לנו, להעלות נר תמיד שיהא אורך לפני תמיד,</p>\n<p>לפני בנ\"י דוקא, וכמרומז בכתוב ומבואר ברז\"ל ואתה תצוה את בנ\"י - מפני שהמליכוני עליהם על הים,</p>\n<p>ומאז ועד עתה פעמיים בכל יום, כשקורין את שמע, בערבין ובשחרית, וכמרז\"ל יקבל עליו עול מלכות שמים, אמליכתי' למעלה ולמטה ולארבע רוחות השמים,</p>\n<p>והקדמה לכל האמור הוא כאמור בכתוב, כתית למאור, וכפירוש רבנו הזקן בעל התניא (פוסק בנסתר דתורה) והשו\"ע (פוסק בנגלה דתורה): ע\"י כתית (ונפשי כעפר לכל תהי' - נעשה) למאור (פתח לבי בתורתך - ועד למאור שבתורה).</p>\n<p>בכבוד ובברכה לבשו\"ט בכל האמור</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תשפ</b></i></h4>\n<p><b>תורה בבית הכנסת: </b>ראה ברכות ח, א.</p>\n<p><b>במכתבי ושיחות: </b>ראה קובץ מכתבים - תהלים.</p>\n<p><b>והפנימית (מאור: </b>ראה ג\"כ קה\"ע לירוש' חגיגה פ\"א ה\"ז בסופה.</p>\n<p><b>הרואה שמן: </b>ברכות נז, א.</p>\n<p><b>אז נאמר: </b>יומא נז, א. ובזח\"ג קנה, א: הארון.. אע\"ג דאינו סטאן כו'.</p>\n<p><b>ואפילו בטומאה: </b>תו\"כ אמור כד, ב.</p>\n<p><b>למה צריך: </b>תנחומא (באבער) תצוה ד.</p>\n<p><b>מפני שהמליכוני: </b>פסיקתא דר\"כ פ' שקלים.</p>\n<p><b>וכמרז\"ל יקבל: </b>ברכות יג, א. ושם.</p>"],[1200970103,"ח'תשפא\n\n<p>ב\"ה, ז' אדר, תשכ\"ד</p><p>ברוקלין.</p><p>מר גרשון שי'</p>\n<p>שלום וברכה!</p>\n<p>לאחרי הפסק הכי ארוך נתקבל מכתבו מג' אדר,</p>\n<p>ויהי רצון אשר תכה\"י יבשר טוב מהנעשה אתו וב\"ב שי' ובנוסח הידוע טוב הנראה והנגלה, ומובן טוב בגשמיות וברוחניות גם יחד, ובפרט אשר בני ישראל נקראים גוי אחד בארץ וכפירוש רבנו הזקן בזה, שגם בעניני ארץ ממשיכים אחדות השם ובאופן גלוי.</p>\n<p>בעת רצון יזכירו את... על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע מתאים לתוכן כתבו, ומה טוב שיודיע גם שם האם של הנ\"ל שכן נוהגים להזכיר בתפלה.</p>\n<p>לכתבו בסיום מכתבו באיחולי לבבו לטובה להיות פעיל וכו'.</p>\n<p>בודאי שנכון ונחוץ הדבר במאד, שמזה גם מובן שלכל אחד ניתנה היכולת והאפשריות למלאות תפקיד גם בתור משפיע בסביבה, ואיך לפעול הרי תלוי זה בבני הסביבה ותכונות נפשות האנשים עליהם רוצים להשפיע, ומה להשפיע הרי מבואר בסיום מגילת קהלת, את האלקים ירא ואת מצותיו שמור כי זה כל האדם ובסגנון חז\"ל המעשה הוא העיקר, חיי יום יום מתאימים ע\"פ הוראות תורתנו תורת חיים.</p>\n<p>והרי ימים אלו, ימי ערב פורים מזכירים ומורים על כל הנ\"ל וכמ\"ש ורבים מעמי הארץ מתייהדים וגו' שבטח מרומז בזה גם עמי הארץ שישנם בתוך כאו\"א, היא הנפש הבהמית, רוח הבהמה היורדת למטה.</p>\n<p>בברכה לבשו\"ט ולפורים שמח.</p>\n<h4><i><b>ח'תשפא</b></i></h4>\n<p><b>מר גרשון שי':</b> סגל, כפר חב\"ד. אגרת נוספת אליו - לעיל חט\"ו ה'תשלא.</p>\n<p><b>וכפירוש רבנו הזקן:</b> ראה גם לעיל חכ\"ב אגרת ח'תיד, ובהנסמן בהערות שם.</p>\n<p><b>ובסגנון חז\"ל:</b> אבות פ\"א מי\"ז.</p>\n<p><b>מרומז בזה:</b> ראה גם לעיל חכ\"ב אגרת ח'שסא. חט\"ז אגרת ו'קכג. לקו\"ש ח\"ד ע' 1281.</p>"],[1200970104,"ח'תשפב\n\n<p>ב\"ה, י\"א אדר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו,</p>\n<p>ובמעמדנו ימים אחדים לפני ימי הפורים,</p>\n<p>ובפרט ע\"פ דברי חז\"ל במשנתם: מגלה נקראת בי\"א כו' בט\"ו - כי מתחיל מאחד עשר באדר זמן פורים הוא, או גם <b>יום</b> פורים הוא -</p>\n<p>יקוים בכאו\"א, בתוככי כלל ישראל, כמו שהי' בימים ההם בזמן הזה, וכמו שנאמר ליהודים היתה אורה ושמחה וששון ויקר, כפשוטו של מקרא וכדרשת חז\"ל: אורה זו תורה ושמחה זה יו\"ט כו'.</p>\n<p>בברכה לבשו\"ט ולפורים שמח ולפעולות בתומ\"צ ומאור שבתורה באופן דהפצה</p>\n<p><b>מ.שניאורסאהן</b></p>\n<h4><i><b>ח'תשפב</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ו ע' 375 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>סד\"ה.. תרכ\"ט:</b> סה\"מ תרכ\"ט ע' פו.</p>\n<p><b>חז\"ל במשנתם: </b>ריש מס' מגלה.</p>\n<p><b>בי\"א כו' בט\"ו: </b>י\"א כמנין אותיות ו\"ה שבשם, ט\"ו כמנין י\"ה שבשם שהפריד ביניהם עמלק (של\"ה פ' תצוה - שכט, א), שמבני בניו הי' המן (תרגום שני למג\"א. מס' סופרים פי\"ג). וראה סד\"ה מגלה נקראת, תרכ\"ט.</p>\n<p><b>זמן.. יום פורים: </b>שתי דעות בגמרא שם.</p>\n<p><b>גם יום: </b>מדויק יותר מ\"זמן\" (ראה מט\"מ סתר\"צ בפי': זמן מתן תורתנו).</p>\n<p><b>וכדרשת חז\"ל: </b>מגלה טז, סע\"ב.</p>"],[1200970105,"ח'תשפג\n\n<p>ב\"ה, י\"א אדר, תשכ\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מו\"ה משה שי'<br>\nהכהן</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל פ\"ש ממנו, בשעתה, ע\"י הרבנים השלוחים, הוו\"ח אי\"א נו\"נ וכו'</p>\n<p>הרה\"ח מו\"ה שניאור זלמן שי' הלוי דוכמאן,</p>\n<p>והרה\"ח מו\"ה קדיש שי' רומנוב.</p>\n<p>אשר ביקרו במחנם הט' וגם מסרו לי בקשתו ברכה פ\"נ.</p>\n<p>ובעת רצון הזכרתים על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, מתאים לתוכן הבקשה, ויהי רצון אשר יבשר טוב בזה.</p>\n<p>והרי מתקרבים אנו לימי הפורים, עליהם נאמר, ליהודים היתה אורה ושמחה וששון ויקר, כדרשת רז\"ל וכפשוטו, שהרי כלל הוא, שאין מקרא יוצא מידי פשוטו.</p>\n<p>בברכה לבשו\"ט ולפורים שמח.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תשפג</b></i></h4>\n<p><b>מו\"ה משה:</b> שייעוויטש, שיקגו. אגרות נוספות אליו - לעיל חכ\"ב ח'תרמא, ובהנסמן בהערות שם.</p>\n<p><b>כדרשת רז\"ל:</b> מגילה טז, סע\"ב.</p>\n<p><b>כלל הוא:</b> שבת סג, א. וש\"נ.</p>"],[1200970106,"ח'תשפד\n\n<p><i>[י\"ג אדר תשכ\"ד]</i></p>\n<p>(1) אי שילוח מכתב - <b>בודאי</b> שלא יוסיף מאומה לתיקון ושיפור. ושילוחו - עכ\"פ מידי ספק לא יצא (ובנוגע <b>לכללות</b> הענין, אבל) בנוגע ליחידים - <b>בודאי</b> שכו\"כ ימנעו עי\"ז.</p>\n<p>מפני הכבוד ועוד טעמים להתחיל (ולכתוב?) להרב <b>מרא</b> דביהכנ\"ס.</p>\n<p>(2) - עיין בפרשת שבת זו: משה טען: הבאת עליו חטאה גו' ואהרן הצטדק אתה ידעת את העם כי ברע הוא גו' - ופשוט בחז\"ל כי משה הצודק והוזקק אהרן לכפרה (תו\"כ לשמיני ט, ב).</p>\n<h4><i><b>ח'תשפד</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ו ע' 448.</p>\n<p><b>אי שלוח:</b> מכתבי מחאה לבני הקהלה נגד ריקודים בתערובות.</p>"],[1200970107,"ח'תשפד*\n\n<p><i>(נוסח המברק לקראת חג הפורים תשכ\"ד)</i></p>\n<p>פורים שמח והועדות פעילה באורה זו תורה כו'.</p>\n<p><b>מקום החתימה</b></p>\n<h4><i><b>ח'תשפד*</b></i></h4>\n<p><b>באורה של תורה:</b> מגילה טז, סע\"ב.</p>"],[1200970108,"ח'תשפה\n\n<p>ב\"ה, ימי הפורים, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד הוו\"ח אי\"א נו\"מ בחור מעם ומורם<br>\nמעם ודורש טוב<br>\nלעמו בעל מדות תרומיות ענף עץ אבות מו\"ה<br>\nשניאור זלמן<br>\nשליט\"א</p>\n<p>שלום וברכה!</p>\n<p>כמנהגי, מיוסד על מצות ומנהג בית ישראל, רצוני בזה לקיים משלוח מנות איש לרעהו, וכל' הכתוב, על ידי שליח.</p>\n<p>מטעם זה ועוד טעמים שיתבהרו לקמן, הנני שולח (וגם מכתב) זה לכ' על ידי ציר מיוחד, כיון שלפי ידיעותי הוא ענין שהזמן גרמא וגם כדי שלא ימשמשו בו יד רבים. ואף שהתורה חסה על ממונם של ישראל, אבל בודאי בכגון זה לא חיישינן.</p>\n<p>א. זה עתה בא לידיעתי ענין שאם יצא לפועל - עלול להביא לידי מחלוקת חדשה והתלהבות היצרים וכולי בין אלו שלאחרונה התחילו לכנותם דתיים והלעומת זה.</p>\n<p>(הנני משתמש בתיבה \"לכנותם\" במתכוון, כי כל כינוי אינו אמתיות השם המציין את אמתיות הדבר הנקרא בשמו; שהרי כל בני ישראל מאמינים בני מאמינים הם, אין יוצא מכלל זה. אלא שמכמה סיבות יש כאלו אשר, בלשון הרמב\"ם, יצרם אנסם ונדמה להם שהענין דמאמינים בני מאמינים אינו הולמם. אבל האמת סוף סוף מנצחת, והרי זוהי גם הבטחת הכתוב לא ידח ממנו נדח).</p>\n<p>הענין הוא, כפי שנודעתי, שהאוניברסיטה העברית בירושלים מתכוננת להוציא לאור מהדורה חדשה של תורה שבכתב בהביא בחשבון תגליות הכי אחרונות וכתבי יד שונים, ולכל לראש כת\"י המכונה</p>\n<p>[...] אלעפו קודקס (כתר תורה!). ולא עוד - ועל זה באתי - שעלה בדעת המכינים את הנ\"ל לדפוס שהפנים לא יהי' הנוסח המקובל והמקודש שעליו נתחנכו כמה וכמה דורות של בני ובנות ישראל, ובהם גם אלו בדורנו שהם בבחינת יצרם אנסם, כי אם הנוסח של הקודקס האמור. וכיון שחלק חשוב ממנו חסר, כמדומה לי לערך שליש, ישלימו את החסר מכתבי יד אחרים שלדעת המוציאים לאור יש לסמוך עליהם.ובחלק ההערות, אם בשולי הגליון או בסוף כל כרך, יעירו ג\"כ על הנוסח המקובל ונוסחאות של עוד כתבי יד וכולי וכולי.</p>\n<p>מובן הסער שעלול להתחולל אם יקימו מחיצה בין חוגים שונים בבני ישראל גם בנוגע לתורה שבכתב. והרי די לנו הצרות שיש לנו על ידי מחיצות מעשה בני אדם משוחדים - בענינים שונים ומשונים, אלא שלעת עתה על כל פנים בנוגע לתורה שבכתב נוסח אחד לכולם, ובזה נבדלו בני ישראל מאלו שהולכים אחרי תרגום השבעים, תרגום השומרונים וכולי וכולי; ועד שאפילו אלו מבני ישראל שנלחמו בתורה שבכתב, מתחיל מהענין דיציאת מצרים ומתן תורה, על כל פנים בנוגע לנוסח עצמו לא נכנסו למלחמה.</p>\n<p>ועתה, הי' לא תהי', מתכוננים להקים מחיצה גם בזה.</p>\n<p>מה שמגדיל הסכנה הוא עוד ענין, שכנראה מזדיינים בטעם ונימוק שזוהי \"דרישת המדע הטהור\", כיון שנוסח המקובל שלנו כאילו מיוסד אך ורק על נוסח יעקב בן חיים וכו', משא\"כ כשזכינו לעוד כתבי יד, וכאילו נתברר שאפילו הרמב\"ם גירסות אחרות היו לו, ולכל לראש הקודקס האמור, ואם כן, והיות שבני ישראל בעלי מסירות נפש הם - יוצאים במלחמת מצוה כביכול על טהרת תורה שבכתב ובלבד שהפנים יודפס דוקא בשינויים, כאמור לעיל.</p>\n<p>ואף שהשינויים, כפי שהודיעוני, אינם בולטים כל כך ובעיקר הוא בנוגע חסר ויתיר, נקודות וטעמים וכיו\"ב, הרי, כנ\"ל, אין כאן השאלה בכמות השנויים וכיו\"ב, כי אם עצם הענין של הקמת מחיצה ופירוד לבבות.</p>\n<p>אין כוונתי במכתבי זה לשלול כל הענין של השוואת כתבי יד וכולי, ואדרבה - אלא שלא לנגוע בהפנים, שישאר בנוסח המקובל דוקא, ורק בהערות ובמבוא וכיו\"ב יבואו שנויי הנוסחאות, ואדרבה כל המאריך ומפרט בהם הרי זה משובח (ובלבד שלא יציע סברת עצמו בתוך מסקנא מוחלטה של רבים או כדבר הפשוט, כי אם לומר כל דבר בשם אומרו).</p>\n<p>והרי גם באופן כזה כבוד המדע במקומו מונח, אלא שיהי' גם כן בדרכי נועם ובדרכי שלום, והליגה הידועה - תוכרח לחפש ענין אחר לנמק מלחמה במאמינים בני מאמינים.</p>\n<p>כדרך \"אנשי מדע\" בתקופתנו, אי אפשר לגשת לאיזו שקו\"ט בענין כהנ\"ל מבלי שיביאו ראיות שגם פרופסור פלוני סובר כן. ואף שאין זה מקצועי שלי, אבל כמדומה ברור הוא שאפילו הגרמני קיטל בהוצאות הראשונות שלו של התנ\"ך לא העיז לשנות את הפנים, וכל הערותיו באו בשולי הגליון וכיו\"ב. ורק לאחרי מלחמת העולם השני' וההשמדות וכולי - הדפיסו הוצאה חדשה (שלישית) שלו והפנים הוא על פי כתב יד לנינגראד, תחת השפעת שותפו לעריכה קאלעה P. kahle ואף שמאז כמה גויים הלכו בעקבותיו, הרי אין זה מכריח שדוקא בירושלים עיר הקדש יעשו ג\"כ ענין שכזה.</p>\n<p>כפי הידיעות שבידי, העומד בראש כל הענין הוא פרופ. גושן-גוטשטיין איני יודע יחסו לדת ולאהבת ישראל ולשלום בין בני ישראל וקנאתו למדע, ובכל אופן בודאי טוב יותר לקדם פני הרע באופן חשאי ובהקדם. ולכן, כנ\"ל, נשלח מכתב זה על ידי ציר מיוחד, ואל בינת כ' אשען - אם ינהל הדברים ואיך, ויהי רצון שיצליח בזה, ואצפה לבשורות טובות.</p>\n<p>וביתר הדגשה, כל הנ\"ל במקומו עומד אם אפילו הי' הקודקס האמור בשלמותו, על אחת כמה וכמה שחסר ממנו כשליש ויוצרכו להשלימו מכתבי יד אחרים וכולי.</p>\n<p>ב. ומענין לענין, בענין ימי פורים, אשר ביטול הגזרה היתה על ידי זה שמרדכי היהודי קיבץ אלפי תנוקות של בית רבן ולימדם תורת ה' ועד שאמרו אתך אנו לחיים או כו' - הנני נוגע בזה עוד הפעם בבעי' הכאובה של המיסיון, ובהמשך לשיחתנו הטלפונית, כיון שקבלתי ידיעה שהיתה החלטה להשליט גם עליהם חוק חינוך חובה ורישום רשמי, שעל ידי זה תוגבל פעולתם וכו', ושמסרו הענין לועידה מיוחדה שתחקור המצב ותגיש דו\"ח וכו'.</p>\n<p>מובן ופשוט שעמדתי בהאמור אין ברשותי שלא לפרטה בפירוש, והיא: אשר אין עצה אחרת לנגע זה, עבודה זרה ואביזרייהו, כי אם - ביעור. ומה שלא תהיינה התחבולות הזמניות, מוכרח ללכת בדרך התרופה היחידה לנגע האמור, ולהזהר שלא להטעות את דעת הצבור שההחלטה האמורה (דכניסתם תחת חוק חינוך חובה) היא תרופה לעצם הבעי' ועל ידי כך להסיח דעת הצבור מזה ולהרדימו. שהרי החלטה הנ\"ל הוא ענין פשוט מלכתחילה, שלא יהא חוטא מסית ומדיח - נשכר, ובנוסח כ' בשיחתנו, שחוק כל זמן ששורר הוא מוכרח על כל אחד לקיימו, ודוקא המסיתים והמדיחים פטרו מזה. ממילא אין זו החלטה חדשה, כי אם הפעלת חוק ישן, ועדיין לא התחילו בנוגע לנגע המיסיון.</p>\n<p>לטענה הידועה האם אפשר לבער נגע המיסיון בתקופתנו, תקופת הדימוקרטי' וכו' ומה יאמרו אומות העולם, הרי בכמה מדינות יש חוק כזה מכמה שנים, כגון באוסטרי' ובנורבגי' ובכמה מדינות אחרות, באין פוצה פה ומצפצף שכאילו יש בזה נדנוד קל של כפי' או שלילת חופש מצפון, וכדומה.</p>\n<p>כפי ידיעתי, עיקר הקושי מקורו בצרפת, שכנראה לה מסיון הכי גדול באה\"ק, ועוד ועיקר, שכיון שקיימים יחסים מיוחדים עם צרפת, תובעים הם זכויות מיוחדות ובתקיפות יתר, עד שכפי השמועה הי' הראשון שהתחיל צווח כקוזק הנגזל - שגריר צרפת, המסתמך כנראה על אותם היחסים. וגם שמעתי ששגריר צרפת הוא אדוק קיצוני ביותר, והוא מנצל יחסים אלו בענין זה הקרוב ללבו. ויש סוברים שיש גם הסכם סודי בנוגע זכויות מיוחדות לצרפת, ולפיכך הרשו להם ג\"כ גידול החזיר, ואף שהנימוק הרשמי הוא שזהו רק לצורך עצמם וכולי, אבל הנימוק הפנימי, על פי האמור, הוא שלא לקפח זכויותיהם של הצרפתים.</p>\n<p>והלא מכל נקודת ראות צודקת הטענה והדרישה: מה לזכויות של צרפת באה\"ק ולהעברת בני ובנות ישראל על דתם? והאם בכלל אפשר שתהיינה \"זכויות\" כאלו? וגם מה להם כי נזעקו, שהרי הפצת הנצרות אינו ענין מדיני של צרפת אלא של הוואטיקאן! ובודאי יש עוד הסברים דיפלומטיים להשפיע על הצרפתים, וכולי.</p>\n<p>בהוקרה ובכבוד ובברכה</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תשפה</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חכ\"ג ע' 342 וחלקה בחכ\"ד ע' 428 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מו\"ה שניאור זלמן:</b> שזר. אגרות נוספות אליו - לעיל ח'תרפב, ובהנסמן בהערות שם.</p>\n<p><b>שהתורה חסה:</b> ר\"ה כז, א.</p>\n<p><b>מאמינים:</b> שבת צז, א.</p>\n<p><b>בלשון הרמב\"ם:</b> הל' גירושין ספ\"ב.</p>\n<p><b>שאפילו.. קיטל:</b> ראה גם לעיל ח\"כ אגרת ז'תקנח.</p>\n<p><b>ביטול הגזרה:</b> אסת\"ר פ\"ט, ג (ד).</p>"],[1200970109,"ח'תשפו\n\n<p>ב\"ה, י\"ז אדר, תשכ\"ד</p><p>ברוקלין.</p><p>מר מתתי' שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מיו\"ד אדר.</p>\n<p>בעת רצון יזכירו את אמו תחי' ואותו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע מתאים לתוכן כתבו, ויהי רצון שיבשר טוב בתוכנו,</p>\n<p>ובפרט שככתבו נמנה הוא על צאצאי בעל התניא אשר בעל הציון הק' כ\"ק מו\"ח אדמו\"ר, נינו ומ\"מ בתור נשיא ישראל.</p>\n<p>וע\"פ האמור התקוה חזקה שיש לו קביעות לימוד בתורת בעל התניא היא תורת חסידות חב\"ד בכל יום ובהוספה ביום השבת אשר קדש הוא לה', ובודאי לדכוותי' ההכרח בזה אין דורש אריכות.</p>\n<p>בכבוד ובברכה לבשו\"ט.</p>\n<h4><i><b>ח'תשפו</b></i></h4>\n<p><b>מר מתתי':</b> צייגר, חיפה.</p>"],[1200970110,"ח'תשפז\n\n<p>ב\"ה, י\"ז אדר, תשכ\"ד</p><p>ברוקלין.</p><p>מר משה איסר שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל מכתבו מאור ליום ד', בו כותב אודות מצב רוחו והשקפתו בנוגע לחסידות, תורתה ועניני' וכו'.</p>\n<p>ותקותי חזקה אשר ע\"י הכירו תורה זו בפנימיות יותר ובעומק, יתקרב לה ולמסקנות שלה, וביחוד שסוף סוף פנימיות התורה שנתגלתה בתורת החסידות, הרי היא נשמה ופנימיות של תורתנו הק' תורת הנגלה, ובסגנון הזהר הק' - נשמתא דאורייתא.</p>\n<p>ולהזכירו במכתבו, שבדורות הקודמים היו שהתנגדו לתורה זו וכו', הרי ביארו טעמם ונמוקם באריכות, שחששו שעל ידי הליכה בתורה זו יתרחקו ח\"ו מקיום מצות מעשיות וכיו\"ב, ואם בתקופה ההיא היו חילוקי דיעות, היש איזה מקום לחשש כזה, הרי לאחרי עבור כמאתים שנה, מעת נתגלתה תורת החסידות, הכל מודים ועונים על השאלה, מהו סימן של חסיד, שמאריך הוא בתפלה יותר מזה שאינו חסיד, מניח שני זוגות תפילין ולא זוג אחד, זקנו מגודל וכו', ז.א. שבאה המציאות והוכיחה, שלא רק שאין כל יסוד לחשש האמור, אלא אדרבה, כשפוגעים בשוק איש שזקנו מגודל בעל פיאות, לבושו ארוך, אוכל שמורה בחג הפסח, מניח תפילין דרבנו תם גם כן, קרוב לאמר שנתגדל על ברכי תורת החסידות.</p>\n<p>פשוט שאין בהאמור כוונה ח\"ו לפגוע במי שהוא מנוחי נפש שחששו בתקופה ההיא להנ\"ל, כיון שאז הי' בסמיכות זמן לכתות הידועות שפרצו גדר וכו' ובעת חירום הרי חוששים גם לספק ספיקא רחוק מאד, מה שאין כן לאחרי תקופת נסיון גדולה כל כך, ובעיקר לאחרי המציאות שרואים גם בעיני בשר.</p>\n<p>ולהזכירו במכתבו אודות מנהג אבות וכו', הרי כל חסידים הראשונים היו בני אבות שלא היו חסידים, וק\"ל.</p>\n<p>ויהי רצון שמתאים להוראות ימי הפורים דאזלינן מנייהו, אשר ליהודים היתה אורה ושמחה וששון ויקר וגו' ומשלוח מנות וגו' כן תהי' לנו, היינו קירוב הלבבות, שנקודתו אהבת ישראל המכוונת על ידי אהבת התורה ואהבת השם, שכל זה מיסודי תורת החסידות ועניני'.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תשפז</b></i></h4>\n<p><b>ובסגנון הזהר:</b> ח\"ג קנב, א.</p>\n<p><b>שבדורות הקודמים:</b> ראה גם לעיל חכ\"ב אגרת ח'תרנב. חי\"ד אגרת ה'לד. חי\"א אגרת ג'תשכב.</p>"],[1200970111,"ח'תשפז*\n\n<p>ב\"ה, ח\"י אדר, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>התלמידים... ישיבת ליובאוויטש, טורונטו</p>\n<p>שלום וברכה!</p>\n<p>עס האט מיר געפרייט צו באקומען אייער בריוו, אין וועלכן איר שרייבט וועגן די פארשידענע סיומים וואס איר מאכט.</p>\n<p>זיכער איז איבעריג מדגיש צו זיין פאר אייך, אז בא אידן איז [א] סיום מער ניט כדי אריבערצוגיין אויף א העכערע מדריגה, אזוי אז א סיום איז באמת א התחלה צו דערגרייכן ווייטער און העכער.</p>\n<p>השם יתברך זאל אייך מצליח זיין איר זאלט לערנען בהתמדה ושקידה לימוד המביא לידי מעשה - קיום המצוות בהידור, און איר זאלט זיין א קוואל פון אמת-אידישע און חסידישע נחת פאר אייערע עלטערן און לערערס, דאס איז אייגנלטעך בא אייך אין די הענט, ווי חכמינו ז\"ל האבן געזאגט <b>יגעת ומצאת:</b> מען דארף נאר וועלן.</p>\n<p>איך האף אז איר האט געהאט א גוטן און פריילעכן פורים און האט מקיים געווען אלע ענינים פון פורים. בפרט אז אידישע קינדער האבן געהאט גאר א גרויסן חלק אין דעם נס פון פורים, ווי חכמינו ז\"ל דערציילן, אז ווען מרדכי האו צוזאמענגעקליבן טויזנטער אידישע קינדער און האט מיט זיי געלערנט תורה ביז מסירות נפש - דאן איז בטל געווארן די גזירה, וליהודים היתה אורה ושמחה וששון ויקר.</p>\n<p>דער אויבערשטער זאל העלפן, אז בא אייך בתוך כלל ישראל זאל מקויים ווערן \"כן תהי' לנו\".</p>\n<p>בברכה להצלחה ולבשורות טובות,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>ניסן מינדל</p>\n<p>מזכיר</p>\n<h4><i><b>ח'תשפז*</b></i></h4>\n<p><b>לימוד.. מעשה:</b> קידושין מ, ב.</p>\n<p><b>חכמינו.. געזאגט:</b> מגילה ו, ב.</p>\n<p><b>אידישע קינדער.. פורים:</b> אסת\"ר פ\"ט, ג (ד).</p>"],[1200970112,"ח'תשפח\n\n<p>ב\"ה, כ\"ב אדר, תשכ\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מו\"ה נתן מנחם שי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת ספרו, רמב\"ם על התורה, ות\"ח על שימת לבבו לשלחו לי.</p>\n<p>ויהי רצון אשר ינצל האפשריות אשר ישנה בידו להפצת היהדות המסורתית כפי שנתבאר וע\"פ ההוראות דתורתנו תורת חיים, אשר שני ענינים עיקרים בזה, הוראה (תורה מלשון הוראה) בחיים, ותורה (שהיא הנותנת) חיים ומורה דרך, איך שיהיו החיים מתאימים לשמם.</p>\n<p>שהעיקר בכל האמור, הרי הוא המעשה בפועל, ובלשון חז\"ל, המעשה הוא העיקר, קיום מצות מעשיות, כולל גם דקדוקיהם ועד לדקדוק קל של דברי סופרים ומנהגי ישראל, בהקדמת שלילת כל דבר אסור ואפילו בלתי רצוי וכו',</p>\n<p>שע\"י כל זה האדם (אתם קרוים אדם) מקיים תכלית בריאתו, וכמ\"ש נעשה אדם בצלמנו כדמותנו*, אדם על שם אדמה לעליון, וכמודגש במיוחד בתור הקדמה למתן התורה, ואתם תהיו לי ממלכת כהנים, והרי גם עבודת הכהנים הוא בסדר האמור, רחיצה* (והרחקת כל דבר בלתי רצוי) בכיור, ולאחר זה העבודה בקדש.</p>\n<p>בכבוד ובברכה.</p>\n<p>נ.ב. לעצם הענין דרמב\"ם על התורה, מובן שרובי השקפות הרמב\"ם ופי' על התורה יש למצוא, לא בספריו שהם פסקי הלכות, כי אם בספריו ומאמריו שתוכנם עיקרי הדת, פירושים וביאורים וכו' שמזה המסקנא, שאף שמכמה טעמים מוכרח להביא הנמצא בפסקי דינים יד החזקה שהביאורים שבתורה דשם גם הם הלכה פסוקה ומוחלטת, לכל לראש מקום לצטט מספרו מורה נבוכים, האגרות שלו ופירוש המשניות, וק\"ל.</p>\n<h4><i><b>ח'תשפח</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ג ע' 232 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מו\"ה נתן מנחם:</b> מנדל. אגרות נוספות אליו - לעיל חכ\"ב ח'רמ, ובהנסמן בהערות שם.</p>\n<p><b>ובלשון חז\"ל:</b> אבות פ\"א מי\"ז.</p>\n<p><b>אתם:</b> יבמות סא, א.</p>\n<p><b>אדם:</b> של\"ה כ, ב. שא, ב. ובכ\"מ.</p>\n<p>*) תחלת הס' וסופו.</p>"],[1200970113,"ח'תשפט\n\n<p>ב\"ה, כ\"ב אדר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הנהלת פרחי אגודת ישראל אשר בניו יארק<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל מכתבם, בו מודיעים על עריכת סיום ששה סדרי משנה, במוצש\"ק הבא עלינו ועל כל ישראל לטובה, שבת פרשת ויקהל פקודי.</p>\n<p>ועל פי ההוראה הידועה של רבנו הזקן (בעל התניא והשו\"ע) שעל כל איש הישראלי ללמוד בכל יום מפרשת השבוע וללמוד מפרשת השבוע הוראות בחיי השבוע,</p>\n<p>יש ללמוד רבות גם בענין האמור ובזה: פרשיות האמורות (ויק\"פ) ופרשת השבוע המתחיל במוצאי שבת זה (ויקרא) מדברים בהקמת המשכן <b>בפועל,</b> אשר ענינו הוא, כלשון הכתוב, ושכנתי בתוכם, וכדיוק חז\"ל בהכתוב: בתוכו לא נאמר אלא בתוכם, בתוך כאו\"א מישראל,</p>\n<p>עשיית שלום וגם חיבור של הגשמיות והרוחניות בכל הדרגות והבחינות:</p>\n<p>להמשיך שכינתו ית' בעולם ועד לעולם הזה הגשמי, ע\"י ששוכן בהמשכן שנעשה מזהב וכסף ונחשת וכו', עניני עולם הגשמי, ע\"י הקרבת הקרבנות מן הבהמה וגו', שבני ישראל עושים את הבהמה קדש ועולה על המזבח לרצון לה',</p>\n<p>ועוד מקודם לזה - ע\"י תרומת ישראל לבנין המשכן, שהרימו (גם לשון - הגבהה) זהב וכסף וכו',</p>\n<p>שכל זה בא ע\"י השראת והגברת הנשמה על הגוף, הנפש האלקית על הנפש הבהמית.</p>\n<p>והדרך לעשיית שלום זה, ה\"ה כהוראת חז\"ל - ע\"י העסק בתורה, שהעוסק בתורה לשמה משים שלום בפמליא של מעלה ובפמליא של מטה,</p>\n<p>וכסיום הששה סדרי משנה, אשר השלום הוא כלי מחזיק ברכה לישראל, שנאמר ה' יברך את עמו בשלום, וההקדמה וההכנה לזה - ה\"ה מפורשת בהתחלת כתוב זה (ולכן גם ההתחלה הובאה במשנה זו כאן) ה' עוז לעמו יתן, עוז זו התורה, שעל ידי נתינת התורה והעסק בה, הרי (כסיום ששה סדרי הגמרא) תלמידי חכמים מרבים שלום בעולם.</p>\n<p>וניתנה תורה שהיא עוז - לישראל שהם עזים שבאומות, בכדי שישתמשו בהעוז שבטבעם - לעניני תורה ומצותי' (הקו - דועשה טוב) והעוז דתורה יתיש את העז פנים שבעניני העולם (הקו - דסור מרע).</p>\n<p>וע\"פ האמור - הרי מובן גודל ההכרח של לימוד התורה וגודל הפעולה</p>\n<p>שעי\"ז - דוקא בתקופת העוז אשר בחיי האדם, בעת היותו צעיר ובחור.</p>\n<p>ויהי רצון אשר לימוד האמור יהי' כהוראת חז\"ל, לימוד המביא לידי מעשה, הנהגה מתאימה בחיי יום יום וגם בעניני חול ובימות החול,</p>\n<p>וכמובא בספרי מוסר וחסידות - הרמז דהתחלת ששה סדרי משנה: מאימתי קורין את שמע בערבין, אשר התחלת התורה וההוראה של חכמינו ז\"ל במשנתם היא, אשר בערבין - כשחושך בעולם, מצווה כאו\"א לקרות את שמע - להקריא אשר ה' אלקינו הוי' <b>אחד,</b> שה <b>א'</b> רומז לאלופו של עולם, וקורא וממשיך את ה <b>א</b> ב <b>ח</b> (ז' רקיעים וארץ) וב <b>ד</b> (ד' רוחות העולם), עושים שלום בין הקב\"ה והעולם.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תשפט</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ד ע' 1291 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>קונטרס:</b> ס' השיחות תש\"ב ע' 27.</p>\n<p><b>המשכן בפועל:</b> ראה גם אגרת שלאח\"ז.</p>\n<p><b>שהרימו.. הגבהה:</b> ראה גם לקו\"ש חכ\"א ע' 316, ובהנסמן בהערה 12.</p>\n<p><b>כהוראת חז\"ל:</b> קידושין מ, ב.</p>\n<p><b>וכמובא:</b> ראה גם לעיל חי\"ט אגרת ז'תכב. ח\"ח אגרת ב'תמח.</p>\n<p><b>הוראה הידועה: </b>ראה קונטרס [ביקור] שיקאגא ע' ה' ואילך.</p>\n<p><b>וכדיוק חז\"ל: </b>הובא בשל\"ה פ' תרומה ובכ\"מ.</p>\n<p><b>כהוראת חז\"ל: </b>סנהדרין צט, ב. ונתבאר בלקו\"ת מטות פו, ב.</p>\n<p><b>עוז זו התורה: </b>זבחים קטז, סע\"א.</p>\n<p><b>עזים שבאומות: </b>ביצה כה, ב. ובחדא\"ג מהרש\"א שם.</p>\n<p><b>שהא' רומז.. העולם: </b>סמ\"ק הובא בב\"י או\"ח סס\"א.</p>\n<p><b>עושים.. והעולם: </b>שהש\"ר ז, א.</p>"],[1200970114,"ח'תשצ\n\n<p>ב\"ה, ערב שבת קדש ויקהל-פקודי, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>צו דער קאנווענשאן פון נשי ובנות חב\"ד<br>\nמאנטרעאל<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>אין איינקלאנג מיט דעם באקאנטן תורה-ווארט פון דעם אלטן רבי'ן, בעל התניא והשלחן-ערוך, דער גרינדער פון חב\"ד, אז \"א איד דארף לעבן מיט דער צייט\" - מיט דער סדרה פון דער וואך, ווארום די תורה שפיגלט אפ אלע לויפנדע געשעענישן, און גיט די נויטיגע אנווייזונגען, אין טאג-טעגלעכן לעבן -</p>\n<p>האבן די סדרות <b>ויקהל-פקודי</b> פון דעם שבת, און די סדרה <b>ויקרא</b> דעם קומענדיגען שבת, זייער פאסנדע און צוטרעפלעכע אנווייזונגען פאר דער קאנווענשאן.</p>\n<p>אויף אייניגע פון זיי וועל איך זיך דא אפשטעלן:</p>\n<p>אין ויקהל-פקודי דערציילט די תורה ווי אזוי דער משכן מיט אלע הייליגע כלים זיינען <b>פאקטיש</b> געמאכט געווארן, ווידערהוילענדיג דערביי אלע פרטים וועלכע זיינען שוין אויספירלעך איבערגעגעבן געווארן אין תרומה און תצוה. די גאנצע אריכות, וואס די תורה האט אייגנטלעך געקענט איינשפארן, אונטערשטרייכט די וויכטיקייט פון <b>עשי',</b> ווי אונזערע חכמים, זכרונם לברכה, דריקן זיך אויס <b>מעשה עיקר.</b> אויב פריער האט זיך גערעדט ווי אזוי דער אויבערשטער האט איבערגעגעבן צו משה רבנו אויפן בארג סיני דעם גאנצן פלאן פון דעם משכן, ווערט איצט דערציילט ווי אזוי די זאך איז פאקטיש <b>אפגעטאן</b> געווארן דורך דעם <b>פערזענלעכן</b> אנטייל פון יעדן מאן און יעדער פרוי (<b>כל</b> <b>איש ואשה</b>); דערביי ווערט אבער אונטערשטראכן, אז די פרויען האבן געוויזן א לעבעדיגען ביישפיל פער די מענער (<b>ויבואו האנשים על הנשים</b>), מיט זייער הארציגער אפפערוויליקייט צו דערפילן דעם ג-טלעכן רצון.</p>\n<p>די אינערלעכע כוונה פון דעם משכן איז געווען <b>ושכנתי בתוכם - בתוך כל אחד</b> <b>ואחת</b>: אז יעדע אידישע הארץ און יעדע אידישע היים זאל זיין א דירה פאר דער ג-טלעכער שכינה; פונקט ווי די אינערלעכע כוונה פון די קרבנות איז געווען, אז יעדע אידישע הארץ זאל זיך דערנעענטערן צום אויבערשטן (<b>מכם קרבן</b>), ווי די תורה אונטערשטרייכט באלד פון אנהויב <b>ויקרא.</b></p>\n<p>דערמיט קומט צום אויסדרוק די <b>נצחיות התורה</b> - די אייביקייט פון דער תורה.</p>\n<p>ווארום כאטש דער משכן פון זהב וכסף וכו' איז צייטווייליג חרוב געווארן, און די קרבנות פון בקר וצאן זיינען צייטווייליג אפגעשטעלט געווארן, איז אבער דער משכן <b>בתוכם</b> און די <b>עבודה שבלב</b> ניט אנגערירט געווארן; אדרבה, נאך פארשטארקט געווארן.</p>\n<p>אריינטראכטנדיג זיך אין די דערמאנטע סדרות פון דער תורה אין דער דאזיגער צייט, דארף יעדער איינער און איינע דערוועקן אין זיך נייע כוחות צו טאן אלץ וואס מען קען צו ברענגען צום אויסדרוק די אייביקייט פון דער תורה דורך לעבעדיגע מעשים אין טאג-טעגלעכן לעבן, אזוי אז אויף יעדע אידישע הארץ און יעדע אידישע היים זאל דער אויבערשטער קענען זאגן: דאס איז מיין משכן, און זייערע תפלות זיינען מיינע קרבנות!</p>\n<p>צו העלפן פארווירקלעכן דאס אויבנדערמאנטע, ניט נאר בא זיך נאר אויך בא אנדערע, אין דעם גאנצן ארום - דאס איז די אויפגאבע פון נשי ובנות חב\"ד, און דערפאר האט זיי דער אויבערשטער באשאנקען מיט א גאר גרויסער מאס הארציגע און טיפע געפילן פון <b>אהבת השם, אהבת התורה</b> און <b>אהבת ישראל,</b> און מזכה געווען צו זיין די <b>עקרת הבית</b> פון יעדער אידישער היים.</p>\n<p>השם יתברך זאל אייך מצליח זיין אין אייער יערלעכער אונטערנעמונג און אין אייער טעטיקייט א גאנץ יאר, צו דערפילן אייער ווייט-גרייכנדיגע אויפגאבע אין דער פולסטער מאס.</p>\n<p>בברכה להצלחה ולבשורות טובות</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תשצ</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ו ע' 397 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>חכמים.. עיקר:</b> אבות פ\"א מי\"ז.</p>\n<p><b>ושכנתי.. בתוך:</b> הובא בשל\"ה פ' תרומה. ובכ\"מ.</p>\n<p><b>מכם קרבן:</b> ראה לקו\"ת ויקרא ב, ב.</p>\n<p><b>תפלות.. קרבנות:</b> ראה ברכות כו, ב.</p>"],[1200970115,"ח'תשצא\n\n<p>ב\"ה, כ\"ז אדר, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>צו דער יערלעכער מסיבה פון די \"נציבי<br>\nהישיבה\" תומכי<br>\nתמימים ליובאוויטש אין מאנטרעאל,<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>די יערלעכע מסיבה קומט היי-יאר פאר באלד נאך דעם יארצייט פון כ\"ק אדמו\"ר מוהרש\"ב נ\"ע, דער גרינדער פון דער ערשטער ישיבה \"תומכי-תמימים\" אין ליובאוויטש, צוזאמען מיט זיין זון, מיין שווער כ\"ק אדמו\"ר נ\"ע, דער מיט-גרינדער און מנהל פועל פון דער ישיבה אין ליובאוויטש און דער גרינדער פון דער ליובאוויטשער ישיבה אין מאנטרעאל.</p>\n<p>איינע פון די אנווייזונגען פון דעם בעל-ההילולא, וואס איז ספעציעל וויכטיג פאר אונזער צייט, איז:</p>\n<p>אין דער איצטיגער צייט, קען מען ניט, און מען טאר ניט, מאכן חשבונות וואס עס לאזט זיך אפטאן און וואס ניט; נאר דאס וואס עס פאדערט אן אויסבעסערונג - מוז מען זיך גלייך פארנעמען דערמיט מיט אנגעשטרענגטע כוחות, און דאן העלפט דער אויבערשטער.</p>\n<p>(קונטרס ומעין, ע' 22)</p>\n<p>די דאזיגע הוראה איז באזונדערס נוגע דעם געביט פון חינוך. אויב מיט יארן צוריק האט מען נאך געקענט טראכטן אין געוויסע פאראנטווארטלעכע קרייזן, וואס מען קען און וואס מען קען ניט פארלאנגען פון דעם נייעם דור, און ווי אזוי \"צוצוציען\" זיי אד\"ג.</p>\n<p>איז אבער איצט גאנץ קלאר, אז דער איינציגער צוגאנג צו חינוך איז אוועקצושטעלן דעם חינוך אויף די פעסטע יסודות פון תורה און מצוות, אן פשרות און אן פארוואסערונגען, נאר מיט דעם ענטגילטיגען באשלוס, אז מ'דארף און מ'מוז אין דעם טאן מיט אנגעשטרענגטע כוחות. דאן איז מען געזיכערט, אז מען פירט אויס מיט ג-ט'ס הילף אין דער פולסטער מאס.</p>\n<p>בפרט אז אונזער דור שרעקט זיך ניט פאר אן ארויספאדערונג (\"טשאלענדזש\") און איז שטענדיג מער גרייט אויפצונעמען דעם פולן אמת ווי א האלבן-אמת, אדער א פערטל-אמת.</p>\n<p>און דאס איז דער צוגאנג פון \"תומכי-תמימים\", וואס דער נאמען אליין ווייזט שוין אויף <b>תורת ה' תמימה</b> - די ג-טלעכע תורה, סיי נגלה דתורה און סיי פנימיות התורה, תורת החסידות - איז <b>איינע און א גאנצע</b>; און די תלמידים <b>תמימים</b> - זיינען <b>גאנצע,</b> גאנצע אין זייערע השקפה און גאנצע אין זייערע הנהגה.</p>\n<p>די הצלחה, בעזרת ה', פון דער ליובאוויטשער ישיבה תומכי-תמימים אין מאנטרעאל האט באשטעטיגט ווי ריכטיג דער צוגאנג איז. עס איז צו האפן, אז די חשובע בעלי-בתים, וועלכע האבן דערמעגלעכט דעם כסדר'דיגען וואוקס, אין כמות און אין איכות, פון דער ישיבה אין פארלויף פון די אלע יארן, וועלן אויך ווייטער אנשטרענגען אלע כוחות צו דערהאלטן און נאך מער אויסברייטערן אלע טעטיקייטן פון דער ישיבה.</p>\n<p>דער זכות פון החזקת התורה און הפצת התורה והמצוות וועט זיכער אלעמען ביישטיין, יעדן איינעם און איינער שי', אין אלץ וואס מען נויטיגט זיך, בגשמיות וברוחניות.</p>\n<p>בברכה להצלחה ולבשורות טובות.</p>\n<h4><i><b>ח'תשצא</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ב ע' 150.</p>\n<p><b>אן פשרות:</b> ראה גם לעיל אגרת ח'תרצד, ובהנסמן בהערות שם.</p>"],[1200970116,"ח'תשצב\n\n<p>ב\"ה, כ\"ח אדר, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>מר אברהם שי' קריניצי</p>\n<p>שלום וברכה!</p>\n<p>אף שזמן רב לא שמעתי מכ' באופן ישיר, אבל מובן שמקבל אני פ\"ש מאנשי כפר חב\"ד, שמודיעים לי גם כן מזמן לזמן על דבר התענינותו הערה בעניני הכפר, וכאיש מעשי ורב פעלים הרי זו מתבטאת בעזרה ממשית, ובפרט בנוגע לגנים ופרחים, שהיא ג\"כ הסיסמה של רמת גן.</p>\n<p>ובהמשך לשיחתנו כשהי' כאן, עצור מלים לא אוכל, להוסיף שבודאי הפרחים האמתיים ענינם לא רק להרהיב העין, אלא בעיקר לעשות פירות ופירי פירות טובים למאכל והכרחיים לקיום המין. ובמובן הרוחני אצל יהודים, וכלשון השגור בפי חכמינו ז\"ל, אין פירות אלא מצוות ומעשים טובים שיפים והדורים הם ונותנים המשך וקיום נצחי לדורות ודורי דורות.</p>\n<p>ולסיים מימי הפורים דאזלינן מהם, המביאים אורה ושמחה וששון ויקר לכל היהודים, יהי רצון שכן תהי' לו ולכל אשר לו בתוככי כלל ישראל, ושבבריאות הנכונה ימשיך בפעולותיו בישוב ארצנו, אשר <b>ארץ הקדש</b> יקרא לה, שגם בזה חיבור ארציות וקדושה, ועד שנעשה דבר אחד.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תשצב</b></i></h4>\n<p><b>מר אברהם קריניצי:</b> אגרות נוספות אליו - לעיל חכ\"ב ח'תקעב. ח\"כ ז'תמז.</p>\n<p><b>וכלשון:</b> ראה סוטה מו, סע\"א.</p>"],[1200970117,"ח'תשצג\n\n<p>ב\"ה, כ\"ח אדר, תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>בתמהון גדול, ובצער גדול עוד יותר, קראתי מכתבו מתמול, בו כותב הטעמים, כביכול, להצדיק התנגדותו לתכנית חנוך דתי ע\"י חוגים מסויימים, ואפילו כמו שהמצב הוא בנידון דידן, שאין עתה לחוג אחר כל אפשריות לחדור לסביבה ולמקומות אודותם מדובר. זאת אומרת - שהנוער שם יהא מופקר לחנוך הפכי, ולא רק נייטראלי, כפי שהורה הנסיון בעבר הקרוב.</p>\n<p>להתחלת מכתבו שרוצה - להוסיף הסברה, לא זכיתי להבינה. שהרי הסברה זו אין בה כל חדש, וכבר כתובה היתה פעמים ושלש וכמה פעמים בעתונות המפלגות, ולא עוד אלא שגם בשיחתנו נגע בנקודה האמורה. יתר על כן, לולא הסברה זו, הרי מלכתחילה לא הי' כל מקום אפילו לספק מוטעה בנוגע לשאלה זו. ומובן ופשוט, שכל הספקות שכותבם, והספקות שהוסיפו בעתונות הנ\"ל במטעמים ותבלין וכולי וכולי אינם בערך כלל להיזק שעלול לבא לאלפים מילדי בני ישראל, וחוששני לומר - לעשיריות אלפים.</p>\n<p>וההיזק, כפי שאמרתי בשיחתנו, הוא לא רק בנוגע לנוער - ע\"י חינוך דלעומת זה, אלא גם איבוד האפשריות להחדיר הוי דתי למקומות שלולא זאת אפשר שלא ידעו אפילו על עצם מציאות של תפלין, וכשרות וכו' וכו', וכמו שידוע לכ' וחבריו על כמה מקרים כאלו, ובפרטיות. - שהרי כשמייסדים בתי ספר דתיים, אפילו בתכנית מינימאלית, מוכרח להכניס לשם זוגות החיים חיים דתיים, שוחט, מוהל, מקוה, וכו'.</p>\n<p>לפעמים רבות קורה שמרוב השקו\"ט בענין, שוכחים על גוף השאלה כפשוטה. והרי לכל לראש - כל ענין זה הוא שאלה מעשיית שנוגעת לרישום שיהי' בעוד שבועות אחדים וגם בשבועות לאחר זה - בנוגע לעולים חדשים שבכל חודש וחודש באים הם.</p>\n<p>והשאלה אינה סובלת דיחוי, כיון שהתוצאות, באם ח\"ו תושלל האפשריות של פתיחת בתי ספר דתיים על ידי חוגים האמורים, הן מיידיות שיורגשו תיכף בשיכוני העולים החדשים, ותיכף כפשוטו - באותו יום עצמו, שאפשר שלא יהי' שם כל ענין של דת - לא כשרות, ולא שמירת שבת, ולא טהרת המשפחה, וכולי וכולי. ולאחרי ימים אחדים, כשהנוער יבקר בבתי ספר שכאילו הם ניטראליים אבל המציאות - שלא יראה ולא ימצא שם כל ענין של דת, הרי מובנות התוצאות.</p>\n<p>ולאחרי בקשת סליחתו, במצב ובעת כזאת - מתבוננים מהי הכוונה הפנימית של חוג פלוני, ואשר בודאי גנוז בה החשבון מה תהי' ההשפעה בעת הבחירות וכו'.</p>\n<p>ואפילו אם תמצא לומר שהחששות אודותן כותב מבוססות הן ועד כדי כך שיוצאות מגדר שמא שלכן בכוחן לשלול את הברי לתועלת על אתר, גם אז הי' מקום לומר - יצא הפסדו בשכרו. והרי זה השלית עצמו לומר שהחששות בגדר ברי הן, ולדעתי - ברובן גם ספק אינן, אלא להיפך קרוב לודאי שלא יתגשמו, ואפילו באם באיזהו מקומן יתגשמו בפועל, גם שם גדול השכר בערך ההפסד אודותו חושש.</p>\n<p>כפי שאני רואה את המצב, וכנראה במוחש בכמה מקומות באה\"ק ת\"ו, הבעי' כשהיא לעצמה בלי כחל וסרק היא, שמחד גיסא אפשר שבחדשים הקרובים ילמדו עם ילדות וילדים על דבר מלך מלכי המלכים הקב\"ה, ויספרו להם על דבר תורתו, ולא באופן תיאורתי, אלא (בהכרח?) גם על חלק המעשה שבזה, ובעשיריות שכונות יראו דוגמא של חיים על פי התורה והמצוה; ומאידך, התאחדות עם אנשי הקצה השמאלי וגם שבחוג אודותו כותב, כדי - הי' לא תהי' - להלחם שלא להכניס את ה' תורתו ומצוותיו לאלפים ממשפחות בני ישראל. וכפי שאמרתי לכ' בשיחתנו, לעני אין כל נפקא מינה מפני מה מונעים ממנו לחם לשבור רעבונו, ומה שלא תהיינה הכוונות הרי גווע הוא מרעב ר\"ל.</p>\n<p>לכאורה מקום לקושי': באם המצב הוא פשוט כל כך כמובא לעיל, איך זה אפשר שיהי' ספק מה צריכה להיות הגישה של איש דתי? אבל גם זה מובן מדיוק <b>סדר</b> הכתוב אשר השוחד יעוור עיני חכמים ויסלף דברי צדיקים, שאין מקרא יוצא מידי פשוטו, שגם <b>לאחרי</b> שבא העיוורון והסילוף קוראים לו חכם וצדיק, אלא שעיוור הוא ר\"ל. וכמשל המובא בספרי מוסר, אשר פיסת נייר קטנה באם נמצאת קרוב ממש אל העין, מכסה ומסתירה היא כל העולם במלואו. ובודאי לדכוותי' האריכות אך למותר.</p>\n<p>פשוט שיש לי לימוד זכות על תוכן מכתבו, ובהקדמת הערה למה שכותב בתחילת מכתבו שהרהר בדברי, שתקותי חזקה שלא בדברי הרהר, ומפני שני טעמים: חדא, מפני שהיו פשוטים ביותר ואין מקום להרהור נוסף בהם. ותו, שאינם דברי, כי אם גישה פשוטה של איש פשוט, שכל אחד ואחד מחוייב ויבוא למסקנה האמורה (מלבד זה שנדמה לו שיש לו פיסת נייר האמורה). ולימוד הזכות הוא שבטח וקרוב לודאי שאין אלו הרהורים שלו, כי אם תגובת מישהו מהמפלגה וכיו\"ב שסיפר לו ע\"ד תוכן השיחה והלז הטיל ספק או גם הרעיש איך זה אפשר לנגוע באינטרסים של מפלגה, אפילו באם הנגיעה היא בגדר ספק וס\"ס, ובפרט שכבר היתה החלטה. וכיון שהיתה החלטה, הרי כסיסמה הידועה אין כאן מקום לספק ושאלה, כי אם צריך למצוא הצדקה על ההחלטה שנתקבלה, שאחרי שנתקבלה נעשית בבחינת חוקה חקקתי גזרה גזרתי ואין לך רשות להרהר אחרי'.</p>\n<p>טרם סיומי אכפול בקשת סליחה על בטויים האמורים, ולא ח\"ו שמתחרט אני עליהם, כי בערך חומר הבעי' אינם מתאימים כלל וכלל, כי חלשים הם מדי. ובקשת הסליחה היא על הכניסי בטויים בלתי רגילים במכתבים אשר כ' מקבלם, שלכאורה, כששני אנשים נפגשים פעם אחת אין עדין רשות להשתמש בבטויים כהנ\"ל, וכו'.</p>\n<p>ויהי רצון שדברים האמורים, יצאו, על כל פנים במשך הזמן, מגדר של דברים בטלים, היינו דברים שאין להן תוצאות. וזכות אלפי משפחות מבני ישראל לתבוע בכל תוקף מכל אחד ואחד: לא תעמוד על דם רעך, (בעקב שלילת אפשריות לחינוך מתאים, על כל פנים מתאים במינימום, לבניהם ובנותיהם, תביעה בקול גדול, ואלו שאין תובעים - הרי אדרבה לאמתו של ענין הדרישה שלהם היא עוד בתוקף יותר) - תעמוד להם.</p>\n<p>ואזכיר לכ' מה שאמר ושנה איזה פעמים בשיחתנו בקשר עם הבעי' האמורה: הלואי אותי (קרי - המפלגה) עזבו ואת תורתי שמרו. ומובטחני שבאם בנוסח זה ישמיע הדברים הנ\"ל להמפלגה, הרי בודאי שכמה יסכימו על זה, ואפילו אלו שלא יסכימו, יפעל עליהם חלישות. ושכרו בצדו, שכר של כל דובר אמת, ובפרט כשהוא לעת עתה במיעוט.</p>\n<p>בכבוד ובברכת חג הפסח כשר ושמח.</p>\n<p>מובן ופשוט שינעם לי לקבל תגובתו על כל האמור, אפילו אם לע\"ע לא יסכים על כל הנ\"ל.</p>\n<p>מובן גם כן שברשותו למסור תוכן מכתבי למי שלדעתו תהי' על ידי זה תועלת בנוגע לאלפי משפחות בני ישראל האמורות. ובכל אופן ינעם לי לשמוע מהתוצאות בכל הנ\"ל.</p>\n<p>אתאפק לא אוכל מלהוסיף עוד הערה, אשר אירוני הדבר, שכל הטענות שכותב שמסקנתן לשלול מחוג פלוני ההתעסקות בענינים דתיים, הן הן הטענות עצמן מצד חוג העומד מימין למפלגה שלו שטוענים אותן כנגד מפלגתו באותן מסקנות עצמן.</p>\n<p>ועוד הערה שלכאורה מיותרת היא, אבל ליתר שאת גם זו עלי להעלות על הכתב, והיא אשר פשוט שהשקפתי היא שאפילו כשחוג הנ\"ל אודותו המדובר יקיים כל ההבטחות שיתנו בנוגע להנהלת בית הספר הדתי, בודאי ובודאי שאין זה המקסימום, ואפילו לא דרך המיצוע. ולהוסיף גם כן, שעל דרך זה הוא גם בנוגע לכללות בתי ספר דתי ממלכתי שבאה\"ק ת\"ו, שהרמה שלהם בנוגע ל\"דתי\" היא בגדר של מינימום, כמובן כולל גם בתי ספר החב\"דיים אשר בזרם דחינוך דתי ממלכתי; ואפילו בתי ספר דתים העצמאי אף הם בערך ברמה כזו - מפני סיבות שאפשר שבחלקן אינן תלויות בהנהלת בתי ספר האמורים, אבל בחלקן בודאי תלויות בהן. ואין כאן מקום להאריך בענין מצער ומכאיב כהנ\"ל.</p>\n<p>והלואי ונזכה שלחג הפסח הבע\"ל יהיו כל הארבעה בנים שבכל בתי בני ישראל, שבכל החוגים ובכל המקומות, בסוג דבן חכם, ועל ידי זה יחישו היציאה משעבוד לגאולה, יציאה מגלות המרה חושך כפול ומכופל בו נמצאים בני ישראל שבארצות הברית שבאה\"ק ת\"ו ושבכל מושבותיהם, על ידי הגאולה האמתית והשלמה, ועד לסיום סדר פסח כהלכתו - לשנה הבאה בירושלים.</p>\n<h4><i><b>ח'תשצג</b></i></h4>\n<p><b>שאין מקרא:</b> שבת סג, א. וש\"נ.</p>\n<p><b>דברים בטלים:</b> ראה גם לעיל חכ\"ב אגרת ח'תקל. חי\"ג אגרת ד'תקצא, ובהנסמן בהערות שם.</p>"],[1200970118,"ח'תשצד\n\n<p>ב\"ה, עש\"ק כ\"ט אדר, תשכ\"ד</p><p>ברוקלין.</p><p>נשי חב\"ד אשר בכפר חב\"ד מיסודו<br>\nובהנהלתו של כ\"ק<br>\nמו\"ח אדמו\"ר נשיא ישראל,<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>בנועם קבלתי הפ\"ש ע\"י הרה\"ח אי\"א נו\"נ וכו' מו\"ה שמחה שי' גאראדעצקי,</p>\n<p>כן מסר הנר שעוה להדלקה ביום ההילולא של כ\"ק אדמו\"ר (מוהרש\"ב) אביו של כ\"ק מו\"ח אדמו\"ר - זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ויהי רצון אשר יאיר ה' מזלן, מזל כל אחת ואחת מהן ושל כל אחד ואחת מבני ביתן שי' וכולן יחד, בנר מצוה ותורה אור, חיים ע\"פ התורה ומצותי', וגם חיים של אור כפשוטן, בריאות הגוף שמחה וטוב לבב.</p>\n<p>ובנקודה הפנימית, לקבל רוב נחת אמיתי, הוא נחת יהודי מסורתי חסידותי מכל ילידיהם שיחיו.</p>\n<p>והרי עומדים אנו ערב ראש חדש ניסן הוא חדש הגאולה, גאולת כל אחד ואחת בתוככי כלל ישראל.</p>\n<p>בברכת שבת טוב וחדש טוב וחג פסח כשר ושמח.</p>"],[1200970119,"ח'תשצה\n\n<p><i>[אדר תשכ\"ד]</i></p>\n<p>אי אתה מחשב שעות לחדשים ומקריבין קרבן ר\"ח בביהמ\"ק כו' - אע\"פ שהמולד אז אמתי (משא\"כ בימינו שע\"פ החשבון - רק אמצעי - כדאיתא ברמב\"ם) <b>ומקום</b> המולד (שנכסית הלבנה בפועל) הוא באה\"ק וסמיכות שלה (משא\"כ בארצה\"ב - שהוא כבר <b>כו\"כ</b> שעות <b>לאחרי</b> שנכסית כו').</p>\n<h4><i><b>ח'תשצה</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ט ע' 331. והוא מענה למו\"ה שמואל פסח שי' בוגומילסקי לשאלתו אם לקבוע זמן החתונה אור ליום א' דרש חודש כשהמולד הוא ביום א' דראש חודש בבוקר. אגרות נוספות אליו - לעיל חי\"ט ז'רמח. לקמן ח'תתב. ח'תתכח. ח'תתעה*.</p>\n<p>ח'תתקמא*.</p>\n<p><b>ואי אתה:</b> מגילה ה, א. רמב\"ם הל' קדה\"ח פ\"ח ה\"א.</p>\n<p><b>כדאיתא ברמב\"ם:</b> שם פ\"ו ה\"א.</p>\n<p><b>ומקום המולד:</b> שם פי\"א הי\"ז.</p>"],[1200970120,"ח'תשצו\n\n<p><i>[חורף תשכ\"ד]</i></p>\n<p>... בשעה\"כ שם: ומהדרין לאומרו בצבור - ולא ראיתי מקפידין בזה.</p>\n<h4><i><b>ח'תשצו</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ד ע' 412.</p>\n<p><b>בשעה\"כ שם:</b> פי\"ז ס\"ב - בנוגע לאמירת הודו בע\"ש קודם מנחה.</p>"],[1200970121,"ח'תשצז\n\n<p>ב\"ה, י\"א ניסן תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד מר משה שי' ארם</p>\n<p>שלום וברכה!</p>\n<p>ימים אלו נודעתי ע\"ד בחירת כ' למשרתו החדשה בסוכנות וכו', וכיון שכל ענין הוא בהשגחה פרטית וכל מינוי נותן אפשרויות חדשות ומתוך כך גם אחריות נוספת, אביע תקותי וברכתי שכ' ינצל במילואן האפשרויות החדשות שנתוספו לו על הקודמות - וכמו שדברנו בשיחתנו בעת פגישתנו - להפצת הערכים הנצחיים של עמנו בני ישראל מיום היותנו לעם במעמד הר סיני.</p>\n<p>ובפרט שרואים במוחש שדוקא ערכים אלו הם סוד קיומו הנצחי של עמנו בני ובנות ישראל, למרות אשר אנחנו המעט בין העמים, וחסד לאומים חטאת, וכמו שנוכח דורנו אוד מוצל מהשואה ושמדות שלא היו כמותן היל\"ת, וכל האומות הנאורות ובלתי נאורות עמדו מנגד וכו', אשר אין לנו להשען אלא על אבינו שבשמים, אלקים חיים הנותן לנו תורת חיים ומצותי' עליהן נאמר וחי בהם.</p>\n<p>וכיון שנבחר כ' פה אחד, הרי זה מגדיל עוד יותר כח השפעתו ואפשריותו, ויהי רצון שיצליח להוציאן מן הכח אל הפועל הנ\"ל.</p>\n<p>ולקראת חג המצות, זמן חירותנו, הבא עלינו ועל כל ישראל לטובה, הנני בזה להביע ברכתי לחג כשר ושמח ולחירות אמתית, חירות מדאגות בגשם ומדאגות ברוח, ולהמשיך מחירות ושמחה זו בכל ימי השנה.</p>\n<p>בברכת החג.</p>\n<p>וכאן עלי חובה נעימה להביע עוה\"פ תודתי למר עבור התענינותו בעניני כפר חב\"ד, אשר בודאי גם להבא יושיט להם עזרתו באם יוזקקו לה, ועוד וגם זה עיקר, שיתענין בהנעשה שם ולא רק על ידי שמיעה אלא גם על ידי ראי' וביקור וכו'.</p>\n<h4><i><b>ח'תשצז</b></i></h4>\n<p><b>מר משה ארם:</b> אגרות נוספות אליו - לעיל חכ\"ב ח'שפו, ובהנסמן בהערות שם.</p>"],[1200970122,"ח'תשצח\n\n<p><i>[י\"א ניסן תשכ\"ד]</i></p>\n<p>ת\"ח על הבשו\"ט מכ\"ז אדר ע\"ד הנחת תפילין דר\"ת, ולכתבו ע\"ד הרעדה בזה וכו' הנה בכלל כל אחד מצווה, עבדו את ה' בשמחה וגילו ברעדה, אולם מה שמקשר הרעדה עם הנחת תפילין דר\"ת, יעוין אודות חשיבות הנחת תפילין דר\"ת ועוד <b>יותר</b> מחשיבות, בשער הכולל פי\"א (להרב לאוואוט על הסידור) ובכו\"כ ספרים (בפרט בס' מאסף לכל המחנות).</p>\n<h4><i><b>ח'תשצח</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"א ע' 357.</p>\n<p><b>חשיבות.. דר\"ת:</b> ראה גם לקו\"ש ח\"ב ע' 507 הערה 39. וש\"נ.</p>"],[1200970123,"ח'תשצט\n\n<p>ב\"ה, י\"א ניסן ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ צנמ\"ס<br>\nכו'<br>\nמו\"ה שלמה יוסף שי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום ו' ניסן והקודמו.</p>\n<p>ולקראת חג המצות, זמן חירותנו, הבא עלינו ועל כל ישראל לטובה, הנני בזה להביע ברכתי לחג כשר ושמח ולחירות אמתית, חירות מדאגות בגשם ומדאגות ברוח - מכל דבר המעכב עבודת ה' בשמחה ובטוב לבב.</p>\n<p>ולהמשיך מחירות ושמחה זו בימי כל השנה כולה.</p>\n<p>ובפרט שעבודת השם, כמצווה עלינו בתורתנו תורת חיים, הרי היא בכל עניני האדם ובמשך כל היום וכל הלילה, וכמו שנאמר בכל דרכיך דעהו.</p>\n<p>בברכת החג ולמילוי משאלותיו לטובה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>לכתבו ע\"ד השו\"ב.. - גם מלכתחילה לא חוו\"ד בגוף הטענות ומי הצודק וכו' - כ\"א רק שישנן טענות מבהילות ובמילא מוכרח בירור. ותל\"מ.</p>\n<p>בהתקבל הידיעה ע\"ד הבחרו למוהר\"ר - מובן שנהנתי מזה שהבוחרים הכירו בכת\"ר וכו' וכו'; מאידך גיסא נבוך הייתי בנוגע \"להנבחר\" האם זהו ענין לכתיבת מז\"ט כו', או כו' - כיון שזוהי כניסה לתפקיד מלא נסיונות, ומסובכים דוקא. ויה\"ר שיצא מכל הנסיונות בשלום ובשלימות ועוד יותר - וזה יוכיח על תחילתו שהי' זה ענין של ברכת מז\"ט והצלחה.</p>\n<h4><i><b>ח'תשצט</b></i></h4>\n<p><b>מו\"ה שלמה יוסף:</b> זוין. אגרות נוספות אליו - לעיל ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>ע\"ד השו\"ב:</b> ראה גם לעיל אגרת ח'תשנב.</p>\n<p><b>ותל\"מ:</b> ותו לא מידי.</p>\n<p><b>למוהר\"ר:</b> למועצת הרבנות הראשית. ראה גם לעיל שם.</p>"],[1200970124,"ח'תת\n\n<p>ב\"ה, יא ניסן ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>אל בני ובנות ישראל אשר בכל מקום ומקום<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>יעדער יום-טוב האט זיין אייגנארטיקן אינהאלט און זיינע ספעציעלע אנווייזונגען, וועלכע דארפן קומען צום אויסדרוק ניט נאר אין די טעג ווען דער יום טוב ווערט געפייערט, נאר אין אלע טעג פון א גאנץ יאהר.</p>\n<p>די אפלערנונג פון יעדן יום טוב איז א צווייפאכיקע: אין דעם קו (ריכטונג) פון ועשה טוב - וואס מען דארף טאן; און אין דעם קו פון סור מרע - וואס מען דארף אויסמיידן. און פיל מאהל, איז די צווייטע טייל נאך וויכטיקער, ווארום אויב מען איז ניט אויסגעהיט פון דאס אומגעוואונשענע, קען פאסירן אז דאס גוטע און פאזיטיווע זאל אויך אויסגענוצט ווערן אין א נעגאטיווער ריכטונג.</p>\n<p>דאס אויבנגעזאגטע איז באזונדערס וויכטיק אין צוזאמענהאנג מיט דעם ערשטן פון צווישן די ימים טובים - פסח, דער יום טוב פון יציאת מצרים, וועלכער פארנעמט אזא צענטראלן ארט אין אידישן לעבן, ביז אז די תורה האט אנגעזאגט יעדער אידן צו געדענקען און דערמאנען יציאת מצרים <b>אלע טאג,</b> און יעדן טאג גופא - סיי באטאג און סיי באנאכט.</p>\n<p>* * *</p>\n<p>גאולת מצרים, דער אינהאלט פון <b>יום טוב פסח</b> - איז פארבונדן מיט דעם <b>קרבן</b> <b>פסח.</b></p>\n<p>גאולת מצרים איז געווען ניט נאר א גאולה פון אסך יחידים, פון זעקס הונדערט טויזענט ערו[ו]אקסענע מיט זייערע משפחות, נאר די גאולה האט זיך אנגעהייבן פון ראה ראיתי את עני <b>עמי</b> (איך האב געזען די פיין פון מיין <b>פאלק</b>) וואס דערפאר האט מען געפאדערט בא פרעה שלח את <b>עמי</b> (שיק ארויס מיין פאלק) און משה האט אויסגעפירט זיין שליחות והוצא את עמי בני ישראל ממצרים (נעם ארויס מיין פאלק, ישראל'ס קינדער, פון מצרים).</p>\n<p>לויט דעם האט אייגענטלעך אויך באם קרבן פסח געדארפט אונטערשטראכן ווערן די נקודה (מאטיוו) פון <b>עם</b> בני ישראל, דעם גאנצן ציבור. פאקטיש אבער איז דער צוגאנג און אנזאג פונקט א פארקערטער. מען האט טאקע אנגעזאגט כל עדת ישראל, צו אלע אידן צוזאמען ווי זיי זיינען איין עדה, אבער דער אנזאג איז געווען: יעדע הויז מוז האבן איר אייגענעם קרבן פסח; יעדערער האט געדארפט פריער אויסגעטיילט ווערן, געציילט ווערן צו דעם קרבן פסח; יעדערער האט געמוזט זיין די גאנצע צייט פון עסן דעם קרבן אין זיין באשטימטער הויז אדער חבורה (קאמפאני).</p>\n<p>דערמיט לערנט אונז די תורה, אז דער וועג צו אויפטאן, אפילו ווען עס רעדט זיך וועגן אויפטאן פאר דעם כלל און אפילו ווען עס רעדט זיך וועגן דער גאולה פון דעם כלל, איז אפילו ווען די ווענדונג דארף זיין צום כלל, מוז אבער דער אינהאלט זיין אז יעדער איינער מוז צום אלעם ערשטן זיך קאנצענטרירן אויף זיך און זיינע בני בית און זיין גאר נאענטן קרייז, און אויך דא - זיך קאנצענטרירן ניט אויף אלגעמיינע באטראכטונגען און כללות'דיגע באשלוסן, נאר אפגעבן זיין הויפט אויפמערקזאמקייט און ענערגיע אויף דורכפירן אין טאג טעגליכן לעבן די איינצעלנע \"קליינע\" באשלוסן וואס דוקא דאס בריינגט, סוף סוף, די גאולה פון דעם יחיד און די גאולה פון דעם כלל.</p>\n<p>באזונדערס וויכטיק איז די דאזיקע הוראה פאר מנהיגים און פירער פון גרופן און באוועגונגען, און ספעציעל פאר די וועלכע דארפן זיין גייסטיקע פירער אין זייערע קהילות. צו אפט איז מען פארקאכט אין \"וועלט פראבלעמען\", אין \"גרויסע ענינים\", און נאר פון צייט צו צייט, אדער גאר זעלטן אז מען הערט א פירער פארנעמען זיך מיט די \"געוויינלעכע קליינע\" פראבלעמען פון טאג טעגליכן לעבן, וועלכע רירן דירעקט אן זיינע קהילה-מיטגלידער.</p>\n<p>וואס מער פראמינענט א פירער איז, אלץ מער \"דארף\" ער ריידן צו דער גאנצער מענטשהייט; און אויב ער האט א גוטן כח הדמיון, שטעלט ער זיך פאר אז ער רעדט אויך צו די צוקונפטיקע דורות. אויב ער איז באשאנקען מיט אראטארישע פייאיקייטן, האלט ער פאר זיין פליכט אויפצוטרייסלען דעם \"וועלט געוויסן\" מיט פייערדיקע ווערטער, וועלכע געפינען אן אפקלאנג אין דער פרעסע, אזוי אז ער ווערט אויך א פירער פון פירער און ווארט-זאגער וועלכע זיינען מקנא \"זיין פרעסע\" און זוכן אים נאכצוטאן און אריבערשטייגן.</p>\n<p>ניט זעלטן ווערט דער \"געפירטער\" צוהערער מיטגעשלעפט, און צוזאמען מיט דעם פירער באשליסט מען וואס די פארשידענע רעגירונגן דארפ'ן טאן, ווי די מענטשהייט אין אלגעמיין דארף זיך פירן, און ווי מען זאל גליקלעך מאכן אלע צוקונפטיקע דורות; און \"זעלבסטפארשטענדליך\" אז נאך אזוינע \"וועלט באשלוסן\" האט קיין ארט ניט \"אראפלאזן זיך\" און מאכן א געוואלד געשריי וועגן דעם גרויסן פראצענט קינדער וואס די \"געפירטע\" ערציען זיי אזוי אז בשום אופן קען מען זיי ניט אריין נעמען אין דער קאטאגאריע פון דעם בן חכם פון דער הגדה, אפילו ניט וועגן די קינדער וואס באקומען א מער \"פארגעשריטענע ערציאונג\" און זיי זיינען א פינפטער בן וואס איז בכלל ניטא באם סדר.</p>\n<p>און זיינען טאקע די פירער זיכער, אז יעדערער פון די \"געפירטע\" עלטערן איז יא באם סדר?</p>\n<p>* * *</p>\n<p>ווי דאס איז אין כלל, אזוי אויך אין פרט: יעדער מענש באשטייט פון א \"פירער\" - (די קאפ און הארץ, שכל און געפיל) - און \"געפירטע\" - (די איברים). און דא אויך קומט אפט פאר דאס זעלבע ווי אויבנדערמאנט: מען נעמט אן אלגעמיינע כללות'דיקע באשלוסן וועגן דעם גאנצען עולם (קטן - דעם מענטש): מען וועט זיין גוט און פרום צום אויבערשטן און צו לייטן, גלייך באם אויפחאפן זיך פון שלאף איז ער מודה אז דער אויבערשטער גיט אין עם אריין די נשמה וואס באלעבט עם; שוין בא דער ערשטער ברכה ווייס ער אז דער אויבערשטער איז מלך העולם - דער פולער בעל הבית פון דער גאנצער וועלט; גאנץ פרי פארן דאוונען נעמט ער אן אף זיך די מצות עשה \"ואהבת לרעך כמוך\" (זאלסט ליב האבן דיין חבר ווי זיך אליין) -</p>\n<p>אז עס קומט אבער צו פרטים און \"קלייניקייטן\" ווי ניט \"שלינגן\" די ווערטער אין דאוונען בכלל און אין קריאת שמע בפרט, אריינטראכטן זיך אין דעם אויבערשטן'ס גרויסקייט און, להבדיל, אין דער קליינקייט פון דעם מענשן (ניט אויסשליסענדיק זיך אליין) פאר יעדער \"שמונה עשרה\" יעדן טאג - פעלט עם אויס צייט און געדולד; אויסהיטן זיך פון השגת גבול דורך אפציען א קונה פון א צווייטן - האט ער מורא אז <b>דורכדעם</b> וועט פעלן אין דער פרנסה וואס... דער אויבערטשער גיט עם. און אז עס קומט פאר פסח און ער דארף ארויסהעלפן א פשוט'ן ארעמאן מיט מעות</p>\n<p>חטים - שטעלט ער זיך פאר די הערליכקייט פון יציאת מצרים און באשליסט אז אזוי ווי דאמאלס - מוז בא עם און זיינע בני בית זיין כלי כסף וכלי זהב ושמלות (זילבערנע כלים, גאלדענע כלים און קליידער), איז וואס בלייבט שוין פאר מעות חטים.</p>\n<p>* * *</p>\n<p>ויהי רצון - דער אויבערשטער זאל בענשן און מצליח זיין, אז יעדער איינער און איינע זאלן זיך אפלערנען פון די דערמאנטע, און אלע אנדערע, דרינגענדע אנווייזונגען פון דעם יום טוב פון זמן חירותנו (אונזער באפרייאונג), און פונקט ווי בשעת יציאת מצרים איז די גאולה פון דעם כלל געקומען אלס פועל יוצא פון דער גאולה פון דעם פרט, זאל דאס אזוי אויך זיין היינט,</p>\n<p>אז יעדער אידישער יחיד און יעדע אידישע משפחה, זאל זייער טאג טעגליכע הנהגה - ביז אין די קלענסטע איינצעלהייטן - זיין א תורה הנהגה אן שום פשרות און אן פארוואסערונג, און דאס וועט ברענגען די גאולה האמתית והשלימה על ידי משיח צדקנו, עס וועט מקויים ווערן - כימי צאתך מארץ מצרים אראנו נפלאות.</p>\n<p>בברכה לחג הפסח כשר ושמח,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ח'תת</b></i></h4>\n<p>נדפסה בהגדה של פסח ח\"ב ע' תרא (הוצאת תשנ\"א).</p>\n<p><b>הוראת פאר מנהיגים:</b> ראה גם לעיל חכ\"ב אגרת ח'תרעט.</p>\n<p><b>אין אלע טעג: </b>הארת כל המועדים מאירה בכל יום (שיחת חה\"פ, ה'תש\"ג).</p>\n<p><b>דאס גוטע כו' זאל אויך כו': </b>להעיר ממחז\"ל לא זכה נעשית (תורתו) לו סם כו' (יומא עב, ב). וראה הל' ת\"ת לרבנו הזקן פ\"ד ס\"ג.</p>\n<p><b>דעם ערשטן: </b>ר\"ה פ\"א מ\"א. וע\"פ דיוק הלשון שהוא <b>ראש</b> לרגלים (ולא \"תחלה\") מובן שהוא ראשון גם בחשיבות.</p>\n<p><b>תורה האט אנגעזאגט: </b>ועד שזהו מ\"ע מן התורה (רמב\"ם הל' ק\"ש פ\"א ה\"ג. שו\"ע אדה\"ז או\"ח ר\"ס סז).</p>\n<p><b>יום טוב פסח: </b>שכן נקרא בתושבע\"פ. וע\"פ פי' ת\"י - גם בתושב\"כ (שמות לד, כה).</p>\n<p><b>ראה.. שלח.. והוצא.. כל עדת: </b>שמות ג, ז. ה, א. ג, י. יב, ג.</p>\n<p><b>הויז אדער חבורה: </b>פסחים פו, א.</p>\n<p><b>יעדער מענש באשטייט: </b>זח\"ב קנג, א. וראה שיחת שמח\"ת תרס\"ט (ס' השיחות תורת שלום ע' 120 ואילך).</p>\n<p><b>נעמט און אלגעמיינע: </b>עד\"ז ג\"כ בענין התבוננות - ראה ש' היחוד פ\"ד. קונטרס העבודה פ\"ו.</p>\n<p><b>עולם (קטן: </b>האדם (תנחומא פקודי ג).</p>\n<p><b>באם אויפחאפן: </b>מיד שניעור (שו\"ע אדה\"ז רס\"א. בסידורו).</p>\n<p><b>פארן דאוונען: </b>פרי ע\"ח ש\"ה פ\"א. וראה סידור רבנו הזקן (קודם מה טובו).</p>\n<p><b>פאר יעדער: </b>שו\"ע או\"ח ר\"ס צח.</p>\n<p><b>גאולה פון דעם כלל כו' דעם פרט: </b>הדברים שבזכותם נגאלו ממצרים (מכילתא בא.</p>\n<p>ויק\"ר פל\"ב, ה. ועוד) עניני הפרט הם. וכן בדמייך חיי בדמייך חיי - שהם דם מילה ודם פסח (שמות רבה פי\"ז, ג).</p>"],[1200970125,"ח'תתא\n\n<p>ב\"ה, י\"ב ניסן תשכ\"ד</p><p>ברוקלין.</p><p>יוסף יצחק שי'</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל מכתבך מיום ה' ניסן.</p>\n<p>והתקוה אשר מתקדם אתה בלימוד וגם בהנהגה, לימוד תורתנו תורת חיים והלימוד מביא לידי מעשה, קיום מצותי' והנהגה האמורה.</p>\n<p>וכן בודאי למדת כבר פירוש ההגדה של פסח, וגם תשאל הארבע קושיות דמה נשתנה, ועל ידי לימוד האמור והנהגה האמורה, תכנס בסוג דבן חכם, לנחת רוח הוריך שי' וכשתרצה באמת תצליח בכל האמור.</p>\n<p>בברכה לבשורות טובות בכל האמור ולחג שמח.</p>\n<h4><i><b>ח'תתא</b></i></h4>\n<p><b>יוסף יצחק שי':</b> צאלער, ציריך.</p>\n<p><b>והלימוד:</b> קידושין מ, ב.</p>"],[1200970126,"ח'תתא*\n\n<p><i>[נוסח המברק לקראת חג הפסח תשכ\"ד]</i></p>\n<p>שבת וחג הפסח כשר ושמח ועונג וחרות אמיתיים.</p>\n<p><b>/מקום החתימה/</b></p>"],[1200970127,"ח'תתב\n\n<p><i>[כ\"ו-כ\"ז ניסן תשכ\"ד]</i></p>\n<p>כמובן באם אין בזה ענין השגת גבול.</p>\n<p>בין מקום קרה\"ת ואה\"ק - לפחות שורה א' יושבים הפסק.</p>\n<p>המחיצה - למעלה מקומת איש.</p>\n<p><b>שאינה זכה</b> להמביטים מעזרת אנשים. מה הכריחו זיך אנשלאגן מיט א היתר (שהוא בלאה\"כ מדוחק גדול) - מבלי להרגיש שכאן העזרת נשים למעלה <b>(וביותר)</b> בגובה מעזרת אנשים, וראה סוכה נא, סע\"ב: והיו באים כו' ועדיין היו באים כו' (עד ש)התקינו כו' מלמעלה - ובחדא\"ג שהשינוי שיושבות למעלה נקרא <b>בפ\"ע</b> תיקון <b>גדול</b> לגבי לפני זה!</p>\n<p>וכלאחר יד ביטל בדיבורו - השוואתו כ\"ז!</p>\n<h4><i><b>ח'תתב</b></i></h4>\n<p>נדפסה בלקו\"ש חט\"ז ע' 615 והושלמה עפ\"י העתקה. והוא מענה למו\"ה שמואל פסח שי' בוגומילסקי לשאלתו באיזה תנאים לקבל את הרבנות בביהכ\"נ. אגרות נוספות אליו - לעיל ח'תשצה, ובהנסמן בהערות שם.</p>\n<p><b>ואה\"ק:</b> וארון הקודש.</p>\n<p><b>הפסק:</b> עי\"ז נחשב בימה באמצע ביהכ\"נ. וראה לקמן אגרת ח'תתכח.</p>\n<p><b>המחיצה:</b> ראה גם לעיל חי\"ד אגרת ד'תתקפח. לקמן ח'תתעה*.</p>\n<p><b>למעלה מקומת איש:</b> על השאלה אם הכוונה ל- 6 רגל, הי' המענה (בכ\"ז ניסן): לפחות.</p>\n<p><b>שאינה זכה:</b> על שאלתו באם אפשר לעשות המחיצה מזכוכית כמו בביהמ\"ד של כ\"ק אדמו\"ר שליט\"א.</p>"],[1200970128,"ח'תתג\n\n<p>ב\"ה, כ\"ז ניסן תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבם מכ\"ה ניסן, בו כותבים ע\"ד ענינים וכו', וסברות בנוגע לזמן לימודים הבא.</p>\n<p>והעיקר חסר לגמרי, כוונתי ע\"ד התמדתם ושקידתם בלימוד התורה נגלה וחסידות, וגם מן הצד לא שמעתי עד\"ז, ובפרט לאחרי מכתבי מאמצע החורף, שבודאי הגיע* גם אליהם, כיון שגם להם נתכוונתי, הרי נוסף על האמור שהוא העיקר - על כאו\"א מתלמידי הישיבה הק' תורת אמת, להשתדל ולעשות כל התלוי בו, להרבות מספר התלמידים, וגם מפעולותיהם בזה לא נשמע מאומה, ובודאי במכתבם בדואר החוזר, יודיעו בפרטיות כנ\"ל ע\"ד ההתקדמות של כאו\"א מהם בלימוד הנגלה ובלימוד החסידות (ופשיטא שאופן הלימוד הוא כהוראת חז\"ל, מביא לידי מעשה, התקדמות בקיום המצות בהידור) וכן כמה תלמידים נצטרפו לכותלי הישיבה ע\"י השתדלות כאו\"א מהם,</p>\n<p>והרי על כגון זה נאמר, יגעת ומצאת, יגעת ולא מצאת אל תאמין, ז.א. שבאם לא מצאו, בודאי לא השתדלו בזה.</p>\n<p>בברכה לבשו\"ט בכל האמור וכן אודות כ\"א מחבריהם שי'.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>מזכיר</p>\n<p>נ.ב. מובן שלהקלוגינקער לא יחסרו אמתלאות ותירוצים (באם חסר בהנ\"ל ח\"ו) ויתלה האשם במי שהוא, ואשר אתם הצדק, וכבר הודיעונו חז\"ל שכל הנשמע ומקבל אמתלאות כאלו, נשמע הוא לרצון הקלוגינקער.</p>\n<p>וע\"פ האמור מובן ופשוט שעליהם להיות בד\"א של הישיבה תו\"א, והלימוד יהי' אליבא דנפשי' וכנ\"ל מבלי לשים לב לפיתוי הקלוגינקער, וק\"ל.</p>\n<h4><i><b>ח'תתג</b></i></h4>\n<p>*) עיין לקו\"ת שמיני (יח, א) אן רירען בל\"א.</p>\n<p><b>מכתבי:</b> דלעיל ח'תשמו.</p>\n<p><b>כהוראת חז\"ל:</b> קידושין מ, ב.</p>\n<p><b>נאמר:</b> מגילה ו, ב.</p>"],[1200970129,"ח'תתד\n\n<p>ב\"ה, כ\"ז ניסן תשכ\"ד</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>בעתו קבלתי מכתבה, ומפני כמה סיבות נתעכב המענה עד עתה, ותקותי אשר לעת קבלת מכתבי זה כבר הוטב מצב רוחה.</p>\n<p>ומכוון הנני המענה לסיום וחותם חדש ניסן, הוא חדש החירות וגאולה, כולל כמובן ופשוט גם גאולה פרטית מכל מחשבות וענינים המבלבלים, והכנה לחדש אייר הוא חדש זיו, אשר כפירוש חכמנו ז\"ל מתגבר הזיו והאור בעולמנו זה.</p>\n<p>ומובן אשר כוונתי בהאמור בנוגע אלי', ששעת הכושר עתה הוא להוספה בברכת השם להצלחתה בכל עניני' מתחיל מחיזוק הבריאות כפשוטה, ועל ידי פעולה בזה (אפילו קלה) מצד האדם, נותנים לו ומוסיפים כמה פעמים ככה בהברכה מלמעלה, ופעולת האדם הרי לכל לראש היא - התחזקות בהבטחון בהשם והתבוננות בענין השגחתו, השגחה פרטית על כל פרט מבני אדם ועל כל פרטי חייהם, שמסקנא המידית מזה, לא לשים לב למחשבות המעוררות איזה דאגה או עצב ח\"ו, ובפרט ע\"פ המבואר בתורת רבותינו נשיאינו תורת החסידות, איך שענין העצבות מושלל בהחלט הוא, והשלילה הרי צריכה להיות לא ע\"י שקלא וטריא עם עצמו והבאת ראיות וכו' - כי אם על ידי היסח הדעת והעדר שימת לב למחשבות אלו, ובאם לא קל להפטר מהם, הרי מהעצות היעוצות - להעסיק המחשבה בענינים שאין להם כל שייכות כלל למחשבה הקודמת, אפילו לא לשלילת המחשבה, כי אם בענין שונה לגמרי.</p>\n<p>ועוד להוסיף, אשר כיון שלכל דבר צריכה להיות איזו אחיזה בדרכי הטבע, מהנכון שתשאל דעת רופא ותמלא הוראותיו, ולאיזה רופא לפנות, תתייעץ עם הרופא המשפחתי שלהם, ותעשה כל האמור מתוך בטחון חזק, ובסגנון דוד המלך נעים זמירות ישראל בשם כל אחד ואחת מישראל, ה' רועי לא אחסר, ה' לי לא אירא, ומתוך בריאות וטוב לבב.</p>\n<p>בברכה למצב רוח טוב ולבשורות טובות בכל האמור ובפ\"ש הורי' שי'.</p>\n<p>נ.ב. ברצוני שיתקבל המכתב עוד בימי חדש ניסן עכ\"פ בראש חדש זיו - נשלח המכתב מהיר דחוף.</p>\n<h4><i><b>ח'תתד</b></i></h4>\n<p><b>כפירוש חכמנו:</b> ראה ר\"ה יא, א.</p>"],[1200970130,"ח'תתה\n\n<p>ב\"ה, כ\"ז ניסן תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>צו די אנטיילנעמער אין דעם עלפטן<br>\nיערלעכן לאנטשאן פון<br>\nאגודת נשי ובנות חב\"ד אין קליוולאנד,<br>\nאהייא<br>\nה' עלייהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>מיט פארגעניגען האב איך באקומען די ידיעה וועגן אייער פארשטייענדן לאנטשאן ביום א' א' דר\"ח אייר (ל' ניסן), הבע\"ל.</p>\n<p>השם יתברך זאל העלפן, אז די יערלעכע אונטערנעמונג זאל געקרוינט ווערן מיט גרויס הצלחה אין אלע הינזיכטן.</p>\n<p>אזוי ווי די אונטערנעמונג קומט פאר אין אפשלוס פון חודש ניסן, איז צו האפן אז בא דער געלעגנהייט וועט אונטערגעשטראכן ווערן די באדייטונג פון דעם חודש הגאולה און פון דעם יום-טוב פסח פאר אלע אידישע פרויען און בפרט פאר חב\"ד פרויען, און ספעציעל בנוגע חינוך על טהרת הקדש. ווארום דער גאנצער יסוד פון (דעם סדר און פון) דער הגדה מיט וועלכער דער יום-טוב פסח <b>הויבט זיך</b> אן איז די מצוה אין דער תורה <b>והגדת לבנך</b> - צו דערציילן און אויפקלערן צו די <b>קינדער</b> די באדייטונג פון יציאת מצרים, אויך אלס צוגרייטונג צו קבלת התורה, כדי צו דערגרייכן <b>הם הכירוהו</b> <b>תחילה</b> (\"די קינדער זיינען געווען די ערשטע וועלכע האבן דערקענט דעם אויבערשטן\") ווי דאס איז געווען בא קריעת ים-סוף, מיט וואס דער יום-טוב פון יציאת מצרים <b>לאזט</b> <b>זיך אויס.</b></p>\n<p>לערנען אונז דער סדר און די הגדה של פסח, אז מ'טאר זיך ניט מייאש זיין אפילו פון א בן רשע, און מ'מוז אויך אים ברענגען צום סדר טיש, און גלייכצייטיק - דארף מען ניט פארלאזן זיך אויף דעם בן חכם אז ער וועט פון זיך אליין אויסוואקסן א גוטער און פרומער איד. מען דארף זיך פארנעמען מיט <b>אלע</b> אידישע קינדער, אן אויסנאם.</p>\n<p>דאס איז אייגנטלעך פון די אויפגאבען פון די חב\"ד פרויען אומעטום, צו שטיצן די מוסדות און די טעטיקייטן וועלכע באצוועקן צו דערהויבן אלע אידישע קינדער צו דער מדרגה פון א בן חכם. אין צוגאב צו דער עיקר'דיקע אויפגאבע פון די נשי ובנות חב\"ד אריינצוברענגען וואס מער ליכטיקייט און קדושה פון נר מצוה ותורה אור אין זייערע היימען און אין דעם ארום.</p>\n<p>בברכה להצלחה ולבשורות טובות.</p>\n<h4><i><b>ח'תתה</b></i></h4>\n<p><b>הם הכירוהו תחלה:</b> סוטה יא, ב.</p>"],[1200970131,"ח'תתו\n\n<p>ב\"ה, כ\"ח ניסן תשכ\"ד</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א רב פעלים לתורה</p>\n<p>ומצוה, צנמ\"ס וכו'</p>\n<p>יושב על מדין מנהל עדתו במישרין הוא ניהו</p>\n<p>הר\"ש</p>\n<p>שליט\"א</p>\n<p>שלום רב וברכה!</p>\n<p>ע\"י הרה\"ח אי\"א נו\"נ רב פעלים מוהרי\"ל שי' ראסקין קבלתי בקשת ברכה פ\"נ עבור בנו מימון שליט\"א.</p>\n<p>ובעת רצון יזכירוהו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע מתאים לתוכן הבקשה, ויהי רצון אשר בעגלא דידן יבשר כת\"ר טוב בהנ\"ל, טוב הנראה והנגלה.</p>\n<p>והרי נמצאים אנו בחדש ניסן, הוא חדש הגאולה, כולל גם גאולה מכל ענינים המבלבלים לעבודת השם בשמחה וטוב לבב.</p>\n<p>ובימי הספירה, שאופן הספירה הוא לא מספר סדורי, (ראשון שני) כי אם אחד שנים, היינו שעולים מדרגא לדרגא נוסף על וגם כולל הדרגות שבעבר, הוספה בשערי קדושה, כמבואר בספרי חכמת האמת, ענין ימי הספירה לעלות למ\"ט שערי קדושה ועד לתכלית שער הנו\"ן וכמ\"ש תספרו חמשים יום.</p>\n<p>הנה כן גם תהי' עלי' והטבה גם בנוגע לבריאות הגוף דהנ\"ל בתוככי כלל ישראל, וכידוע גודל מעלת גוף הישראלי, ובלשון רבנו הזקן ובנו בחרת מכל עם ולשון הוא הגוף החומרי (עיין ספר תניא קדישא פרק מ\"ט).</p>\n<p>ופעולות כת\"ר בקדש לטובת מוסדות הק' אשר על שם כ\"ק מו\"ח אדמו\"ר אשר על הציון הק' יקרא הפ\"נ, תעמוד להנ\"ל בהאמור.</p>\n<p>בכבוד ובברכת שבתא טבא ולבשו\"ט.</p>\n<h4><i><b>ח'תתו</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ז ע' 284 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>הר\"ש שליט\"א:</b> מישאש, קסבלנקא.</p>\n<p><b>שאופן הספירה:</b> ראה תו\"א לד, ב. סהמ\"צ להצ\"צ כח, א.</p>\n<p><b>כמבואר:</b> ראה לקו\"ת במדבר יב, א ואילך.</p>"],[1200970132,"ח'תתז\n\n<p>ב\"ה, ערב ש\"ק פרשת ויהי ביום השמיני,</p><p>וש\"ק מברכים חדש זיו,<br>\nה'תשכ\"ד. ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>וע\"פ מאמר רז\"ל בספרא בראשית פרשת שבוע זה: ויאמר משה - אמר להם משה לישראל... <b>כשם</b> שהוא (הקב\"ה) יחיד בעולמו כך תהא עבודתכם מיוחדת לפניו... עשיתם כן וירא אליכם כבוד ה'.</p>\n<p>וידוע פירוש הבעש\"ט בזה: זה הכלל גדול שיהי' לאדם תמיד רק מחשבה אחת בעבודת הבורא ית'... ויחשוב שכל דבר שיש בעולם הכל מלא מהבורא ית'... וידבק עצמו בכבודו ית' מאהבה גמורה... ותמיד יהי' מחשבתו דבוקה... וזהו פירוש הפסוק ברמז, ומן המקדש לא יצא, וכשצריך לדבר מעניני עולם הזה יהי'... כמו האדם שהולך מביתו לחוץ ודעתו לחזור תיכף, ובעת ההליכה חושב מתי יחזור לביתו... ביתו העיקרי הבורא ית'.</p>\n<p>יהי רצון שיקיים כאו\"א את כל האמור לעיל מתוך שמחה אמיתית, כמו שהי' ביום השמיני אז.</p>\n<p>וירא כל העם וירונו, מילוי ההבטחה הנ\"ל, עשיתם כן וירא אליכם כבוד ה'.</p>\n<p>בברכת הצלחה בעבוה\"ק ולבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתז</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ז ע' 297 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>ס' צוואת הבעש\"ט:</b> בהוצאת קה\"ת סי' פד.</p>\n<p><b>בספרא: </b>שמיני ט, ו.</p>\n<p><b>פירוש הבעש\"ט: </b>ס' צוואת הבעש\"ט.</p>\n<p><b>הכלל גדול: </b>עיין שבת סח, א.</p>\n<p><b>הכל מלא: </b>ברכות י, א. וראה ש' היחוד והאמונה ספ\"ז.</p>\n<p><b>וידבק.. מאהבה: </b>ראה ספרי ואתחנן ו, ה.</p>\n<p><b>ומן המקדש: </b>ראה סנה' יט, א.</p>\n<p><b>חושב מתי: </b>להעיר מדברי הבעש\"ט: בכ\"מ שהרצון שם ה\"ה כאילו עומד שם (זאת חנוכה, תר\"ם פ\"ג - ולא סתם מח' - כפשטות הלשון בצוואת הריב\"ש לפני זה).</p>\n<p><b>וירונו: </b>ושבחו (ת\"א) ובספרא שם: פתחו פיהם ואמרו שירה.</p>"],[1200970133,"ח'תתח\n\n<p>ב\"ה, ל' ניסן אדר\"ח אייר ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו ביום בו מתאחדים ניסן חדש הגאולה, גאולת הגוף וגאולת הנפש (ממצרים ערות הארץ) גם יחד, ואייר הוא חדש זיו, זיו ניצניא אשר בארץ, ועל שם האבות שהם זיוותני עולם.</p>\n<p>יהי רצון שנזכה בקרוב ממש לשלום אמיתי ולאיחוד הרוחניות והגשמיות, מתחיל מהרוחניות וגשמיות שבעולם קטן, הוא האדם, הגוף והנפש, ועד לרוחניות וגשמיות בעולם כפשוטו.</p>\n<p>וכדברי חז\"ל: העוסק בתורה לשמה משים שלום בפמליא של מעלה ובפמליא של מטה, ומבואר באריכות ע\"י רבנו הזקן בעל התניא (פנימיות התורה, נשמתא דאורייתא) והשולחן ערוך (נגלה דתורה, גופי תורה).</p>\n<p>והרי זה גם מענין פרשתא דאזלינן מינה, וכפירוש רז\"ל בראש הפרשה:</p>\n<p>א\"ל משה לישראל... <b>כשם</b> שהוא (המקום) יחידי בעולם כך תהא עבודתכם מיוחדת לפניו, עיי\"ש.</p>\n<p>בברכת הצלחה בעבוה\"ק</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתח</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ז ע' 303 (בתאריך ג' אייר) והושלמה עפ\"י צילום האגרת.</p>\n<p><b>שבעולם קטן:</b> תנחומא פקודי ג.</p>\n<p><b>בו מתאחדים: </b>ראה שו\"ע אה\"ע סקכ\"ט ס\"ו ובנ\"כ.</p>\n<p><b>ניסן חדש הגאולה: </b>שמו\"ר פט\"ו, יא.</p>\n<p><b>ואייר.. זיו ניצניא: </b>מ\"א ו, א ובתרגום.</p>\n<p><b>ועל.. עולם: </b>ר\"ה יא, א.</p>\n<p><b>וכדברי חז\"ל: </b>סנה' צט, ב.</p>\n<p><b>ומבואר באריכות: </b>לקו\"ת מטות פו, ב ואילך.</p>\n<p><b>נשמתא דאורייתא.. גופי תורה: </b>זח\"ג קנב, א.</p>\n<p><b>וכפירוש רז\"ל: </b>ספרא שמיני ט, ו.</p>"],[1200970134,"ח'תתט\n\n<p>ב\"ה, ל' ניסן אדר\"ח אייר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ג וו\"ח אי\"א נו\"נ וכו' רב פעלים מו\"ה<br>\nשמואל שי'</p>\n<p>שלום וברכה!</p>\n<p>בהמשך לשיחתנו אכפול ברכתי אשר תהי' נסיעת כת\"ר עם זוגתו הרבנית תחי' לבקור באה\"ק ת\"ו ע\"י משיח צדקנו, בשעה טובה ומוצלחת.</p>\n<p>ואם בנוגע לעובר חנות של בשם נאמר שריחו קולט עאכו\"כ בביקור שלא בדרך מעבר ובארץ עלי' נאמר, עיני ה\"א בה מראשית השנה ועד אחרית שנה, שהאפשרית ניתנה לקליטת ריח וגם בפנימית, ענינים שהנשמה נהנית מהם וגם הגוף נהנה מהם, שהרי גם גוף איש הישראלי קדוש הוא ובקדושת הגוף,</p>\n<p>וכנאמר ג\"כ בדברי רבנו הזקן, ובנו בחרת מכל עם ולשון הוא הגוף וכו' (תניא פרק מ\"ט יעו\"ש היטב).</p>\n<p>ובעמדנו...</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתט</b></i></h4>\n<p><b>מו\"ה שמואל:</b> יאלאו, סירקיוז. אגרות נוספות אליו - לעיל ח\"כ ז'תשמח, ובהנסמן בהערות שם. לקמן ח'תתקא.</p>\n<p><b>שהנשמה נהנית:</b> ברכות מג, ב.</p>\n<p><b>ובעמדנו:</b> נוסח האגרת שלפנ\"ז.</p>"],[1200970135,"ח'תתי\n\n<p>ב\"ה (?) ניסן תשכ\"ד</p><p>הוו\"ח אי\"א נו\"נ וכו' מו\"ה נפתלי שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה להשאלה - בקשת ביאור בענין שכינה, המוזכר רבות פעמים בדברי חכמינו ז\"ל.</p>\n<p>ומבואר הדבר באר היטב במיוחד בספרי חסידות ומאמרי חסידות ובכמה</p>\n<p>מקומות - ימצאם ע\"י מפתח הענינים הנדפס בסוף ספר התניא, ספר תורה אור לקוטי תורה ועוד.</p>\n<p>ובכ\"ז - עכ\"פ בקצרה אבוא בהענין גם בזה, אף כי כמובן לא באופן ממצה כלל וכלל, כי קצרה היריעה וכו':</p>\n<p>כיון אשר השי\"ת הוא תכלית השלימות ומושלל כל הגבלות וגדרים מובן, אשר, כסגנון רבינו הזקן, לא זהו עיקר האלקות שהוא בורא עולמות, וביחד עם זה, בסגנון הרמב\"ם בהלכות יסודי התורה שלו, הוא ממציא כל נמצא, וכל הנמצאים לא נמצאו אלא מאמיתת המצאו וכל הנמצאים צריכים לו, מובן ג\"כ - שכשם שא\"א להנברא להשיג ענין התהוות יש מאין, כמו כן (וזהו הענין ממש - ד)אי אפשר לנברא להשיג את האלקות, אפילו כמו שהאלקות הוא בורא עולם וממציא כל נמצא.</p>\n<p>ובסגנון חוקרי גדולי ישראל, אילו ידעתיו הייתיו,</p>\n<p>ואף שמבחין ומבין שאין הדבר עושה א\"ע, ומוכרח לומר שהיש הנברא יש לו מקור המהווה אותו, הרי הבנה האמורה היא רק הכרח על מציאות הבורא, אבל לא הבנה באלקות אפילו מצד זה שהוא בורא.</p>\n<p>לשון הרמב\"ם הנ\"ל שכל הנמצאים צריכים לו, כולל שלא רק צריכים לו לעצם התהוותם ונקודת קיומם, אלא גם בכל צרכי הקיום שלהם והחיות שלהם ועד לפרטי פרטים צריכים לו (אלא שע\"פ תורת החסידות - ודלא כבמו\"נ - הפרטים גם מושגחים, שגם פרט הכי קטן הוא בהשגח\"פ מהשם, אשר רצה להשגיח גם בפרטי פרטים של הבריאה והנבראים). ועלה ברצון העליון אשר יהיו בהשגחת ובהמשכת אלקות למטה - גם ענינים שיהי' לשכל האדם השגה בהם.</p>\n<p>ובסגנון נעים זמירות ישראל, כי אראה - שמיך מעשה אצבעותיך וגו' ועד שנכללת בזה הוראה בעבודת האדם לקונו; שאו מרום עיניכם - וראו מי ברא אלה (וכמבואר בארוכה במאמר רביה\"ז על כתוב האמור, שהוא גם הקדמה ויסוד לספר החקירה של נכדו מ\"מ אדמו\"ר הצמח צדק).</p>\n<p>ואלו הענינים של המשכת אלקות שהם מתלבשים בעולם למטה ועד לאופן שנגלה גם לנברא, זהו הבחינה הקרוי' בשם שכינה, ע\"ש ששוכנת ומתלבשת.</p>\n<p>ובזה ענין עיקרי, אשר אין לחלק ח\"ו למעלה לפרט ופרט, (ורק מצד המתבונן והנברא - שיש ענין שמבינו, ויש ענין שאינו מבינו), אבל לאמיתתו של דבר, אין כאן ענינים, ל' רבים, כי אם מציאות אחת שהוא בתכלית הפשיטות.</p>\n<p>ומכש\"כ וק\"ו: ומה בנוגע לנשמת האדם, אין לחלקה לרמ\"ח חלקים או לשס\"ה חלקים או לתרי\"ג חלקים, ובכ\"ז עין הרואה מבדילה בין החיות אשר ברגל לגבי החיות אשר במוח שבראש, אף שבשניהם הוא הוא ענין אחד - הנשמה המחי' את הגוף, עאכו\"כ ועד להבדיל הבדלות אין קץ, שכן הוא בנוגע ללמעלה, ולכן בהאמור ששכינה שרוי' בביהמ\"ק, אין הפירוש ח\"ו דרק ענין השכינה, כ\"א להדגיש אשר שם האלקות באופן דשוכן ומתלבש ועד שנראה גם לעיני בשר, שמקום ארון אינו מן המדה, ועשר ניסים שהיו בביהמ\"ק וכו' וכו'.</p>\n<p>כאמור לעיל, הנ\"ל - רק פרט אחד בביאור ענין שכינה, ורבים הרבה ישנם יותר וגם בפרט זה ביאורים רבים יותר נמצאים בכמה ספרי חסידות ומאמרי חסידות.</p>\n<p>התקווה שיש לו קביעות עתים בלימוד תורת החסידות בכ\"י ובהוספה ביום השבת אשר קדש הוא לה'.</p>\n<p>בכבוד ובברכה לחג פסח כשר ושמח.</p>\n<h4><i><b>ח'תתי</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"א ע' 317 והושלמה עפ\"י העתקה.</p>\n<p><b>מו\"ה נפתלי:</b> יוספזון, תל אביב.</p>\n<p><b>בענין שכינה:</b> ראה גם לעיל חכ\"ב אגרת ח'תקנה.</p>\n<p><b>כסגנון רבינו הזקן:</b> ראה תו\"א מג\"א צט, ב. לקו\"ת שה\"ש ח, א. ובכ\"מ.</p>\n<p><b>ובסגנון:</b> ראה לקו\"ש חכ\"ז ע' 263 ובהנסמן בהערה 26.</p>\n<p><b>שע\"פ תורת החסידות:</b> ראה גם לעיל ח\"א אגרת צד.</p>\n<p><b>ועלה ברצון:</b> ראה גם לקו\"ש חכ\"ט ע' 30 ובהנסמן בהערה 35*.</p>\n<p><b>במאמר רביה\"ז:</b> נדפס בהוספות לס' החקירה ע' קא ואילך.</p>\n<p><b>ומה בנוגע:</b> ראה גם תניא פנ\"א.</p>"],[1200970136,"ח'תתיא\n\n<p>ב\"ה, ג' אייר תשכ\"ד</p><p>ברוקלין.</p><p>קהל המתפללים בבית הכנסת עדת ישראל,<br>\nנוסח האר\"י,<br>\nבמנשסתר<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת המכתב מיום הרביעי, כתוב ע\"י הפרנסים הוו\"ח אי\"א נו\"נ רב פעלים וכו' מר שמעון שי' פאטאש ומר ע. גרונסוואלד שי'.</p>\n<p>ובעת רצון יקרא על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע נשיא ישראל.</p>\n<p>להתעוררות רחמים רבים על כל אחד ואחד ומשפחותיהם שליט\"א.</p>\n<p>ויהי רצון שחפץ ה' בידם יצליח לגמור ההוספה בבנין דבית הכנסת שלהם, אודותו כותבים.</p>\n<p>ועוד ועיקר שיתוספו ספסלי הן הבאים לעבודת התפלה והן הבאים לשמוע בלימודי תורתנו הקדשה.</p>\n<p>אשר בודאי עי\"ז יתוסף ג\"כ בברכת השם, שהוא הזן ומפרנס לכל בטובו בחן בחסד וברחמים, פרנסה בכל המצטרך הן ברוחניות והן בגשמיות, והוא נותן התורה ומצותי' אשר תלמוד תורה כנגד כולם.</p>\n<p>ובפרט אשר נמצאים אנו בימי הספירה, אשר תיכף לברכה לספירה</p>\n<p>מבקשים - הרחמן הוא יחזיר לנו עבודת בית המקדש למקומה, במהרה בימינו, אשר אז יקוים גם היעוד, בתי כנסיות ובתי מדרשות שבגליות יקבעו בארץ ישראל, כיון שקוראים ומרביצים בהם תורה.</p>\n<p>בכבוד ובברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תתיא</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ד ע' 409 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>תלמוד תורה:</b> פאה פ\"א מ\"א.</p>\n<p><b>היעוד:</b> מגילה כט, א.</p>"],[1200970137,"ח'תתיב\n\n<p>ב\"ה, ז' אייר תשכ\"ד</p><p>ברוקלין.</p><p>כבוד המשתתפים בלימוד ספר תניא קדישא<br>\nאשר בבית<br>\nהכנסת שערי תפלה, בטאראנטא<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בנועם נודעתי ע\"ד עריכת סיום חלק השלישי של ספר התניא, הוא אגרת התשובה, ביום ראשון פרשת אמור וגו' ואמרת, פסח שני.</p>\n<p>ויהי רצון אשר כבכל ענין דגמרה של תורה, סיום איזה ענין בתורתנו, ובפרט כשנעשה ברבים, יתוסף עי\"ז בלימוד התורה, כולל - גם בהחיות ואור שבלימוד זה, והוספה האמורה ע\"י הלומדים, הרי הובטחנו בזה ובכגון זה, וכסיום וחותם אגרת התשובה הנ\"ל, אדם מקדש עצמו מעט מלמטה מקדשין אותו הרבה מלמעלה,</p>\n<p>ולא עוד אלא שמוסיף ביאור בזה: וכמ\"ש לעיל וכו' בחי' סוכ\"ע, ז.א. אשר הקידוש מלמעלה הוא לא רק הרבה בכמות, אלא גם באיכות, ולא עוד אלא - שבאין ערוך, אין ערוך דסובב כל עלמין לגבי ממלא כל עלמין.</p>\n<p>ומההמשך תיכף לאחר זה: וככה ממש הוא בענין שכר וכו', מובן שככל האמור הוא גם בהנוגע לשכר מצוה האמורה, שכר בעולם הבא ובעולם הזה, שהרי תלמוד תורה הוא מהדברים שאם אוכל פירותיהם בעולם הזה והקרן קיימת לעולם הבא.</p>\n<p>וכנהוג מאז ומקדם לקשר עניני השבוע בפרשת השבוע: ידועה דרשת חז\"ל עה\"כ אמור ואמרת, להזהיר גדולים על הקטנים, וע\"ד מציאות גדלות וקטנות בעולם בכלל, כן דוגמתם הוא גם בעולם קטן הוא האדם, שבכל אדם ישנו הגדלות שלו והקטנות שבו, הגדלות שבאדם הוא השכל שבמוח וההרגש שבלב, והקטנות שבאדם (ועד ל)ענין העשי' שבו, ונצטווה האדם, אשר הגדול שבו יזהיר את הקטן, וכאזהרת חז\"ל שהלימוד צ\"ל על מנת לעשות, ועוד יתרה בזה אשר גדול לימוד (עיקר הגדלות שבלימוד הוא מה) שמביא לידי מעשה.</p>\n<p>ובכל האמור ישנה גם הוראת פסח שני, וכביאור כ\"ק מו\"ח אדמו\"ר נשיא ישראל \"פסח שני ענינו איז, עס איז ניטא קיין פארפאלען, מען קען אלע מאל פאריכטען, אפילו מי שהי' טמא, מי שהי' בדרך רחוקה און אפילו \"לכם\" - אז דאס איז געווען ברצונו, פונדעסטוועגן קען מען מתקן זיין\" באם רוצים באמת, ולא עוד אלא שאין בזה הגבלה בזמן וכו' - ודלא כפסח ראשון שהוא שבעת ימים וכו' - שהרי ענין התשובה הוא בשעתא חדא וברגעא חדא, ואינו זז משם עד שמוחלין לו, ועד שיהי' לרצון לפני ה' ומרוצה וחביב לפניו ית' וכו'.</p>\n<p>בכבוד ובברכה</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתיב</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חל\"ב ע' 227 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>ידועה דרשת:</b> ראה גם לקמן אגרת ח'תתטז.</p>\n<p><b>בעולם קטן:</b> תנחומא פקודי ג.</p>\n<p><b>אדם מקדש: </b>יומא ספ\"ו.</p>\n<p><b>אין ערוך דסובב: </b>ראה תניא פמ\"ח ובכ\"מ.</p>\n<p><b>הוא מהדברים: </b>פאה רפ\"א.</p>\n<p><b>דרשת חז\"ל: </b>יבמות קיד, א.</p>\n<p><b>וכאזהרת חז\"ל: </b>ראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ג-ד.</p>\n<p><b>גדול לימוד: </b>ב\"ק יז, א.</p>\n<p><b>עיקר הגדלות: </b>עיין הל' ת\"ת לאדה\"ז פ\"ד ס\"ג.</p>\n<p><b>וכביאור כ\"ק כו': </b>\"היום יום\" יד אייר.</p>\n<p><b>ודלא כפסח ראשון: </b>דכל הז' ימים שייכים אליו (עיין פסחים צה, ב: הנאכל לששה.</p>\n<p>שם צו, רע\"ב: <b>וחימוצו</b>.. כל שבעה).</p>\n<p><b>בשעתא חדא: </b>זח\"א קכט, א. וראה קידושין (מט, ב) ובאגרת התשובה בתחלתה (צא, רע\"א) (דאפילו) <b>מצות</b> התשובה: מן התורה היא.. שיגמור בלבו כו'.</p>\n<p><b>שיהי' לרצון כו': </b>אגה\"ת רפ\"ב. וראה רמב\"ם הל' תשובה פ\"ז.</p>"],[1200970138,"ח'תתיג\n\n<p>ב\"ה, ח' אייר, תשכ\"ד</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>במענה למכתבה מיום השני, בו כותבת ראשי פרקים מדברי ימי חיי'.</p>\n<p>והתקוה אשר למותר להדגיש הכרח הנהגה בחיי היום יומים שתהא מתאימה להוראות תורתנו תורת חיים (הוראה בחיים) אשר אך זו הדרך להיות מאושר הן ברוחניות והן בגשמיות, הן בחיי עולם הבא והן בחיי עולם הזה, ועפי\"ז מובן גם המענה לשאלותי' אשר צריכה להשתדל שתמשיך בלימודי' בבית ספר ובסביבה ספוגה יראת שמים, ובהביא בחשבון השפעת הרחוב וכו' יראת שמים איתנה מבלי להתרשם מהפיתוים והסתות הבאים מהשמאל, ומבתי ספר שמזכירה הרי בודאי שהסמינר בית יעקב יש לו דין קדימה ובהרבה מבתי ספר האחרים.</p>\n<p>כן בשאלתה השני', בגילה שככתבה היא בת חמש עשרה אין כל ענין ואין רצוי' בהחלט, הידידות אודותה כותבת, ולא רק שאינה רצוי' ע\"פ הוראת תורתנו תורת חיים אלא שאפילו ע\"פ שכל הפשוט של אנשי העולם, מביאה לתוצאות בלתי רצויות בתכלית, ובטח גם החלישות בבריאותה ומתיחת הרוח, בחלקם עכ\"פ באו כתוצאה מהנ\"ל או מחשבה ע\"ד הנ\"ל.</p>\n<p>לשאלתה כיצד תסרב להמשיך בידידות האמורה - המענה ג\"כ ע\"פ האמור, שלא היא מסרבת למי שהוא, כי אם שממלאה הוראת תורתנו תורת חיים, ולא עוד אלא שגם עליו, באם באמת דתי הוא, לעשות כן, ומתוך הבנה מלאה להוראת התורה,</p>\n<p>ויהי רצון שתבשר טוב בכל האמור.</p>\n<p>בברכה.</p>"],[1200970139,"ח'תתיד\n\n<p>ב\"ה, ט' אייר, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>מר יעקב שי' כהן</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ג בניסן, שנתקבל באיחור קצת.</p>\n<p>ופותחין בברכה ותודה על הפ\"ש מביקורו בלונדון.</p>\n<p>ובהמשך לשיחתנו, וכן לתוכן מכתבו זה, הנה אחד מעסקני החינוך החב\"דים הוא מר שמואל שי' חפר, מנהל בי\"ס מקצועי וסמינר בכפר חב\"ד, ואנשי משפחתו הכירו (להבדיל מחל\"ח) את אחי ע\"ה עוד ברוסיא ולאחרי זה באה\"ק ת\"ו. זאת אומרת שמתאים מר חפר שי' מכל הנקודות להשתתף בחגיגת הנחת אבן הפינה.</p>\n<p>ויהי רצון - וזהו העיקר כמובן - שהנחת אבן הפינה לבנין התלמוד תורה תהי' בשעה טובה ומוצלחת, טובה ומוצלחת על פי תורה, רצוני לומר שבבנין זה יחונכו בני ישראל על פי הוראת תורתנו הנצחית, תורה הקדושה וביחד עם זה תורת חיים, כולל גם החיים בעולמנו הזה, תלמוד תורה המביא לידי מעשה קיום המצוות בחיי היום יום, מצוות התורה עליהן נאמר וחי בהם. שאם בכל התקופות והמקומות הדברים אמורים, על אחת כמה וכמה בתקופתנו זו ובדור זה אשר נבוכים הם בדרכם בחיים וזקוקים לאמת בלתי פשרית, אמת נצחית, ובפרט בארץ אשר בפי כל עמי תבל ארץ הקדש יקרא לה.</p>\n<p>בכבוד ובברכה בכל האמור ולבשורות טובות.</p>\n<h4><i><b>ח'תתיד</b></i></h4>\n<p><b>אחי ע\"ה:</b> מו\"ה ישראל ארי' ליב.</p>"],[1200970140,"ח'תתטו\n\n<p>ב\"ה, יו\"ד אייר, תשכ\"ד</p><p>ברוקלין.</p><p>הרה\"ג הוו\"ח אי\"א נו\"מ עוסק בצ\"צ וכו'<br>\nהר\"מ שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת ספרו חלקת מאיר ות\"ח ת\"ח.</p>\n<p>וביחד עם זה - מצטרף הנני עם קהל מברכיו ובפרט בועידה הערוכה לכ',</p>\n<p>ויה\"ר אשר רבות בשנים ינצל כל האפשריות שישנן, והאפשריות שאפשר לייצרן, לביסוס היהדות המסורתית, יהדות בלי פשרות, ובאופן דלא תגורו מפני וגו',</p>\n<p>אשר אם בכל התקופות ובכל המקומות זו אך זוהי דרך תורתנו תורת אמת, עאכו\"כ במדינה זו ובתקופה זו, רבת המבוכות וטשטוש הגבולות, ועד - לשינוי ערכין, ויתירה מזה - עד לאמירה לרע טוב ולטוב רע שמים חשך לאור ואור לחשך וגו'.</p>\n<p>והרי הובטחנו, הבא לטהר - וידוע דיוק רבנו הזקן (בעל התניא והשו\"ע) לטהר אחרים - מסייעין אותו.</p>\n<p>בכבוד ובברכה.</p>\n<p>כרגיל בכגון זה - מועתק כאן ממה שרשמתי (עכ\"פ בחפזה) בעניני הספר:</p>\n<p><b>בתחלתו.</b> הקדמת הרמב\"ם. <b>כל המצות כו' בפירושן ניתנו שנאמר ואתנה לך גו'</b> <b>תורה זו תושב\"כ והמצוה זו פירושה כו' תושבע\"פ.</b> לכאורה צ\"ע - דזה דהמצות בפירושן ניתנו ילפינן ממש\"נ בשמיטה וידבר גו' בהר סיני, וכדאיתא בתו\"כ שם. וביותר יקשה דהרי הרמב\"ם עצמו הביא לימוד זה בענין זה בהקדמתו לפיה\"מ.</p>\n<p>ואולי יל\"פ ע\"פ הידוע בכללי הרמב\"ם ש\"דרכו ליקח הדרשה היותר פשוטה כו' ולפעמים מביא פסוק שלא נזכר בגמרא כלל\" (יד מלאכי כללי הרמב\"ם. <b>וש\"נ</b>). ועפ\"ז מתיישב גם דיוק הצפנת פענח על הרמב\"ם (להרגוצבי) שהרי בש\"ס (ברכות ה, א) מפרש המצוה זו משנה כו' להורותם זה גמרא. וק\"ל.</p>\n<p>אלא שעדיין יקשה דלפי' הרמב\"ם למדין אנו רק דהמצות ופירושן ניתנו למשה מסיני ומנ\"ל דגם ד\"ס כו' וכל מה שתלמיד ותיק עתיד <b>לחדש</b> ניתן למשה מסיני. ואולי י\"ל דלשטתי' אזיל דכל הגזירות והתקנות והמנהגות וכו' מ\"ע לשמוע להן כו' (הל' ממרים בתחלתו) - וא\"כ פי' מ\"ע זו כולל ד\"ס וכו'.</p>\n<p><b>דרך אגב:</b> הקדמת הרמב\"ם \"לפיה\"מ סדר זרעים\" - אף שנדפס כן בשסי\"ן וכו' - מוכח מתוכנה שאינה מיוחדת כלל לסדר זרעים, כ\"א לכל הש\"ס.</p>\n<p><b>שם.</b> שקו\"ט <b>בענין דב\"נ אינו מצווה בקדה\"ש.</b> בסהמ\"צ להרמב\"ם (מ\"ע ט') כתב בפי' דכן הוא בגמרא בסנה'. עוד זאת: כתבו בסהמ\"צ שם לאחר זה ולקחו ראי' על מצוה זו מאמרו ונקדשתי בתוך בנ\"י - אף שכבר כתב כן בתחילת המצוה - משמע דכאן כוונתו לזה שמצוה זו חובה (אך) לישראל - כמש\"כ לפני זה - ומבאר שלמדו זה רז\"ל (שאמרו דרק ז' מצות נצטוו ב\"נ) ממש\"נ בתוך בנ\"י.</p>\n<p><b>בסופו.</b> בדברי המרחשת דכיון דנשים פטורות מהלל, הרי למ\"ד דקריאת המגילה היינו הלילא גם ממגילה פטורין. וזהו טעמי' דבה\"ג.</p>\n<p>וא\"כ צ\"ל דפליג הבה\"ג על תוד\"ה מי (סוכה לח, א). ולדידי' לא תהיינה נשים חייבות בהלל בלילי פסח ודלא כפשטות ל' השו\"ע שלא הביא חולק בזה - וראה שו\"ע רבנו הזקן סתע\"ב סעי' כה. ואין ס' המרחשת תח\"י.</p>\n<h4><i><b>ח'תתטו</b></i></h4>\n<p>חלקה נדפס בלקו\"ש חל\"ג ע' 235 חלקה בחכ\"ד ע' 412 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>הובטחנו.. דיוק:</b> יומא לח, ב. לקו\"ת דרושים לשמע\"צ פח, ב.</p>\n<p><b>מה שתלמיד:</b> ראה הנסמן בס' השיחות תשנ\"ב ח\"ב ע' 504 הערה 20.</p>\n<p><b>הקדמת הרמב\"ם:</b> ראה גם לקו\"ש חט\"ז ע' 193 הערה 9.</p>\n<p><b>ב\"נ.. בקדה\"ש:</b> ראה גם לקו\"ש ח\"כ ע' 75 ובהערה 33.</p>"],[1200970141,"ח'תתטז\n\n<p>ב\"ה, א' פ' אמור, פסח שני, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת המכתב.</p>\n<p>ומענין ימים אלה: אמחז\"ל אמור ואמרת, להזהיר גדולים על הקטנים, וע\"ד מציאות גדלות וקטנות בעולם בכלל, כן דוגמתם הוא גם בעולם קטן הוא האדם, שבכל אדם ישנו הגדול והקטן שבו, הגדול שבאדם הוא הראש והחכמה והשכל שבו והקטן שבאדם - איבריו וענין העשי' שבו, ונצטווה האדם, אשר הגדול שבו יזהיר את הקטן, וכאזהרת חז\"ל שהלימוד צ\"ל על מנת לעשות, יתרה בזה אשר גדול לימוד (עיקר הגדלות שבלימוד הוא מה) שמביא לידי מעשה.</p>\n<p>ובכל האמור ישנה גם הוראת פסח שני, וכביאור כ\"ק מו\"ח אדמו\"ר נשיא ישראל \"פסח שני ענינו איז - עס איז ניטא קיין פארפאלען. מען קען אלעמאל פאריכטען, אפילו מי שהי' טמא מי שהי' בדרך רחוקה און אפילו \"לכם\" - אז דאס איז געווען ברצונו, פונדעסטוועגן קען מען מתקן זיין\" באם רוצים באמת, ולא עוד אלא שאין בזה הגבלה ומדידה בזמן - ודלא כפסח ראשון שהוא שבעה ימים וכו' - שהרי ענין התשובה הוא בשעתא חדא וברגעא חדא, ולא הגבלה בענין - ודלא כפסח ראשון דחמץ לא ימצא ברשותו - שהרי תשובה שלימה הוא דזדונות (\"לכם\" הנ\"ל) נעשו לו כזכיות; ע\"י התשובה אינו זז משם עד שמוחלין לו, ועד שיהי' לרצון לפני ה' ומרוצה וחביב לפניו ית' וכו'.</p>\n<p>בברכה לבשו\"ט בכלל ובפרט</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתטז</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ז ע' 327. וראה גם לעיל אגרת ח'תתיב.</p>\n<p><b>אמחז\"ל: </b>יבמות (קיד, א) הובא גם בפרש\"י עה\"ת - היינו שזהו גם פשוטו של מקרא.</p>\n<p><b>עולם קטן הוא האדם: </b>תנחומא פקודי ג.</p>\n<p><b>הוא הראש: </b>כשמו. וראה שבת סא, א.</p>\n<p><b>והחכמה.. העשי': </b>להעיר משער היוה\"א פ\"ט.</p>\n<p><b>והקטן.. העשי': </b>להעיר מקדושין (ע, א) דפרנס אסור בעשיית מלאכה בפני ג' וברמב\"ם וכו' \"כדי שלא יתבזה בפניהם\".</p>\n<p><b>וכאזהרת חז\"ל: </b>ראה הלכות ת\"ת לאדה\"ז פ\"ד ס\"ג-ד.</p>\n<p><b>גדול לימוד: </b>ב\"ק יז, א.</p>\n<p><b>עיקר הגדלות: </b>עיין הל' ת\"ת לאדה\"ז פ\"ד ס\"ג.</p>\n<p><b>וכביאור כ\"ק כו': </b>\"היום יום\" יד אייר.</p>\n<p><b>ודלא כפסח ראשון: </b>דכל הז' ימים שייכים אליו (עיין פסחים צה, ב: הנאכל לששה.</p>\n<p>שם צו, ריש ע\"ב: <b>וחימוצו</b>.. כל שבעה).</p>\n<p><b>בשעתא חדא: </b>זח\"א קכ\"ט א. וראה קדושין (מט, ב). באגרת התשובה בתחלתה (צא, ריש ע\"א) (דאפילו) <b>מצות</b> התשובה: מן התורה היא.. שיגמור בלבו כו'.</p>\n<p><b>תשובה שלימה: </b>ראה אגה\"ת ספ\"ח (משא\"כ בח\"א ספ\"ז \"תשובה נכונה\"). יומא פו, ב.</p>\n<p><b>תשובה.. כזכיות: </b>משא\"כ פסח ראשון. ראה ד\"ה להבין ענן פ\"ש (אוה\"ת בהעלתך) דפ\"ר ופ\"ש הם - אתכפיא ואתהפכא.</p>\n<p><b>כזכיות: </b>עליהם הוא יחי' אף על העבירות (רש\"י יומא שם).</p>\n<p><b>אינו זז משם עד כו': </b>שיש קונה עולמו בשעה אחת וגם קורין אותו רבי (ע\"ז יז, א).</p>\n<p>ולהעיר ממאמר אדה\"ז דמיוהכ\"פ תקס\"ב [סה\"מ תקס\"ב ח\"א ע' יג].</p>\n<p><b>שיהי' לרצון כו': </b>אגה\"ת רפ\"ב. וראה רמב\"ם הל' תשובה פ\"ז.</p>"],[1200970142,"ח'תתיז\n\n<p>ב\"ה, פסח שני, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ג והרה\"ח וו\"ח אי\"א נו\"מ עוסק בצרכי<br>\nציבור בעל<br>\nמדות וכו' מוה\"ר מנחם בן ציון שי'</p>\n<p>שלום וברכה!</p>\n<p>פותחין בברכה ותודה שרואני ממכתבו שהוטב מצב בריאותו, ויהי רצון מהשי\"ת שתהי' רפואתו שלמה וגם קרובה. כבקשתו עוד הפעם אזכירו על ציון כ\"ק מו\"ח אדמו\"ר, וזכות פעולותיו להחזקת והרבצת התורה תעמוד לו למילוי משאלות לבבו לטובה.</p>\n<p>מובן שצער גדול הוא שתמיכת קרן הצלה נידלדלה כל כך, בה בשעה שהצורך והדרישה מתגדלים הלוך וגדול. ובודאי עסקן ציבורי כמוהו לא נצרך לעצה איך יוכל למלאות החסר ממקורות אחרים, והרי כלפי הנצרכים לא נוגע מאיזה קופות באה עזרתם.</p>\n<p>ובהזדמנות זו דפסח שני, ומענין לענין באותו ענין, ידוע פתגם כ\"ק מו\"ח אדמו\"ר שהמוסר השכל דפסח שני הוא שאצל יהודי \"איז קיינמאל ניט פארפאלן\", ואדרבה פעמים שהזדמנות השני' עדיפה מהראשונה בנוגע לפרטים, וכמרומז גם בענין דפסח שני שלא הי' נצרך לביעור חמץ תחילה וכו'.</p>\n<p>בכבוד ובברכה ובפרט לרפואה קרובה ושלמה.</p>\n<h4><i><b>ח'תתיז</b></i></h4>\n<p><b>מוה\"ר מנחם בן ציון:</b> זקס, שיקגו. אגרות נוספות אליו - לעיל חכ\"ב ח'תרלא, ובהנסמן בהערות שם.</p>\n<p><b>ידוע פתגם:</b> ראה גם ב' האגרות שלפנ\"ז, ובהנסמן בהערות שם.</p>"],[1200970143,"ח'תתיח\n\n<p>ב\"ה, ט\"ו אייר, תשכ\"ד</p><p>ברוקלין.</p><p>מר ירחמיאל שי'</p>\n<p>שלום וברכה!</p>\n<p>באשטעטיג די ערהאלטונג פון אייער בוך \"א קאץ אין געטא\" אין צוגאב צו די פריערדיקע, זיינער צייט ערהאלטענע, \"אויף קידוש השם\" א.ז.וו. אין אידיש, ות\"ח.</p>\n<p>און השם יתברך זאל אייך מצליח זיין, לויט'ן אויסדרוק שמחנו כימות עניתנו, און פון איצטער אן און ווייטער זאל אייער שרייבען זיין, ווי געשריבען פאר דעם, נרננה ונשמחה בכל ימינו, בא א גוטער איינארדנונג בכל הפרטים, און צו אויסניצען אייערע כשרונות מיט וועלכע איר זייט בעשאנקען געווארען, לתועלת הרבים, מיט גוטען געזונט ומתוך הרחבה,</p>\n<p>און לויט די ערקלערונג פון רבנו הזקן בעל התניא והשו\"ע זאל זיין דער ענין פון געטא, באופן - די ערפילונג פון דעם צוזאג, הן עם לבדד ישכון, און די זאך פון קידוש השם, דורך דעם אויפפירונג אין דעם טאג טעגליכן לעבען פון יעדער אידן בתוך כלל ישראל, אין א אופן אז, וראו כל עמי הארץ כי שם ה' נקרא עליך ויראו ממך.</p>\n<p>בכבוד ובברכה</p>\n<p><b>מ. שניאורסאהן</b></p><p>נ.ב. דאס בייגלייגטע איז צו דעקען הוצאות המשלוח.</p>\n<h4><i><b>ח'תתיח</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ח ע' 480 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מר ירחמיאל:</b> בריקס.</p>\n<p><b>לויט די ערקלערונג:</b> ראה תניא ספכ\"ה.</p>"],[1200970144,"ח'תתיט\n\n<p>ב\"ה, ח\"י אייר, תשכ\"ד</p><p>ברוקלין.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ צנמ\"ס וכו' הרש\"י<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו ממוצש\"ק, ועל ראשון ראשון וכו',</p>\n<p>א) שאלת הרבנים הקונסרבטיבים:</p>\n<p>לפע\"ד לפלא הספק בענין הפשוט, כוונתי שסברות (או כמו שקורין להן - הפשרות) שמזכיר, אין להן מקום כלל, כי אין זו פשרה אלא וויתור על כל הענין, שהרי ברור מדובר מצדם, שדורשים להכיר בהם כמו שמכירים בהשאר, ובא\"ל הרי זה הפלי' וכו'.</p>\n<p>ובמילא פשרה בשטח אחד <b>מוכרחת</b> להביא פשרה דומה בשאר השטחים, ([...] לשטח הגטין) ולכל לראש - בנוגע להבתי כנסיות, רבנים, נשואין, וכל זה דורשים כמובן ופשוט - בכל קצוי תבל כולל לכל לראש אה\"ק ת\"ו, אלא שמוסיפין שמובן שבכל ענין צ\"ל מומחה באותו ענין ולכן צ\"ל בקי בטיב גטין באם עוסק בגט ובטיב קדושין באם רוצה לסדר קדושין ועד\"ז בנוגע לבתי כנסיות וכו'.</p>\n<p>הפשרה שמי שהוא יקבע שעל פלוני <b>משלהם</b> יש לסמוך ותו לא, הרי <b>בודאי</b> שיתפרש הדבר <b>כהוכחה</b> ששיטת הקונסר' עצמה אינה פוסלת, אלא שצ\"ל יודע בטיב כו', שגם מן האורט' נדרש זה, נוסף עוד שבזה גם שפיכת שמן על המדורה. באם יאמרו להקונסרבטיבים שמי שהוא הראוי - יחליטו דוקא האורטודוקסים, הרי אין זה פשרה - אלא אדרבה להרבות הפירוד. כן בכלל אין בזה הצלה, שבאם היום סומך מי שהוא את פלוני שהוא ראוי, הרי שבאופן פרינצפיוני מוכרים הם לרבנים ובמילא יכולים לתת סמיכה וכו'. ופשוט הדבר והאריכות בזה אך למותר, ורק להוסיף שתי נקודות, שגם הן עיקריות:</p>\n<p>א) איך שלא יפרשו הדברים בהועידה של כת\"ר ובסביבתו, הקובע יהי' - איך שיתפרשו הדברים בדעת הקהל, במכ\"ע וכו', ובעיקר במקום המבצר שלהם, היינו בנויארק, ואשר פה - ידם השלטת על כל אופני הפרסום. וד\"ל.</p>\n<p>ב) בודאי ידועה המלחמה שבלונדון נגד הרב הראשי ברוידא שי' ועד\"ז - מכתב המברק הידועה של \"השבעה\" (בנוגע לכפי' דתית), ולאחרונה החלטות של הקאנווענשאן דהקונסרבטיבים, וספק גדול אם הזדמנות כל אלה ביחד הם במקרה בעלמא. וקרוב לודאי לומר - שזהו תכסיס מחושב, ובאם ח\"ו תתקבל אחת הפשרות עליהן כותב כת\"ר או כיו\"ב בהם, ינצלו את זה לא רק בהנוגע להירוס בשטח זה - אלא להגברת ההתקפה בכל האמצעים ובכל השטחים. וכפי שראו במוחש בעבר, הרי כל ענין בקל יותר להתגבר עליו בראשיתו, ואזי גם המחלוקת במיעוטה, משא\"כ כשמוותרים וכו' מתגבר התאבון כלפי זה שוויתר - עד שסו\"ס אין כל מקום לוויתור כ\"א לביטול בפניהם. ומלחמה אז נגד הביטול סופי, הרי קשורה במחלוקת גדולה הרבה יותר, פירוד הלבבות הרבה יותר וכו',</p>\n<p>לביסוס \"חשש\" האמור לעיל, יש מקום להוסיף עוד פרט: כפי המצב ואפילו לדבריהם הם, השאלה היא בנוגע <b>למתי מספר</b> מבין הרבנים הקונסרבטיבים, ז.א. שאין זה ענין של פרנסה או התמוטטות של קהלות, כ\"א <b>אך ורק</b> שאלה של פרעסטיזשע, כי גם בעתיד ספק גדול אם יתרבו בהם מספר אלו שיתרצו לעסוק בגיטין ומפני כמה טעמים ובמילא אין זה וויתור כלפי פלוני, כ\"א וויתור בענין הפרעסטיזשע, היינו כלפי השיטה.</p>\n<p>הטענה שכותבה שחלק חשוב מהמגביות נכנס על ידם, והטענה עד\"ז שהובאה כאן, שמייצגים הם מאות אלפים מאורגנים וכו' - הרי פשוט שמטעם זה עצמו מוכרחים להתיר כל הנ\"ל גם בנוגע להרפורמים, וכפי הסטטיסטיקה הרפורמים עשירים יותר בממון וגם במספר בני אדם מאורגנים.</p>\n<p>כיון שכבר מזכיר ע\"ד ענין המברק... הנה השמועה שנפוצה כאן (ולע\"ע לא הכחישו אותה, ובמילא ההיזק שבה בנוגע ו)שנשלח מברק לפני טכס ההכתרה, ותוכנו - שאל יעשו רעש, ולאחרי ההכתרה יתפשרו עמהם, ושמברק זה צ\"ל חשאי, ונוסף על החלישות בכללות העמדה כאן שגרמה השמועה אודות תוכן המברק - הרי בכמה חוגים מדגישים, הביטוח (באווארעניש) שיהי' ענין המברק בחשאי בהוספה שהרי זה גופא הוכחה שהענין הוא פוליטיקה ומעין מסחר בדת וכו' וכו'. ודי וכו'.</p>\n<p>כנ\"ל איני אומר בזה כלל בנוגע לעצם מציאות המברק אודות נוסח המברק ודיוק השמועה, אלא שבנוגע לדעת הקהל ותגובתו, לע\"ע ישנה רק שמועה זו מבלי כל הכחשה, לא בכללותה ולא בפרטי'.</p>\n<p>לאחרונה הוסיפו שמועה על שמועה האמורה, שבקשר עם חתונת נכד - הרי יהי' כאן ובמילא בנקל יהי' להתדבר יותר, כיון שלא יהי' לחץ (מהנטורי קרתא?) כו'. מובן שגם לשמועה זו - איני אחראי לאמיתתה, כ\"א בנוגע לההיזק שנגרם על ידה.</p>\n<p>בהתענינות קראתי הכתוב במכתבו בנוגע לענג ושמחה בשבת ויו\"ט, וכמדומה באחת ההתועדויות ג\"כ נדבר עד\"ז באו\"א קצת (ע\"פ ההערה בהליקוט לפ' דברים ה'תשכ\"ג - כמדומה נשלח בשעתו לכת\"ר).</p>\n<p>בנוגע למשלוח תשמישי קדושה וכיו\"ב למדינות אפריקה וכו' הרי באם תושלחנה הכתובות לכאן, אשתדל לעשות כפי היכולת.</p>\n<p>ת\"ח ת\"ח על הבשו\"ט בנוגע לפעולות זוגתו הרבנית תחי' בכרם חב\"ד. וכפי שאמרתי מאז ומקדם, ולאחרי בקשת סליחת כת\"ר, הרי לשון הכתוב הוא, שמוני נוטרה את הכרמים כרמי שלי לא נטרתי, ז.א. שגם הם כרמים הם <b>ע\"פ תורה,</b> ובכל זה יש חילוק בין כרמים לכרמי שלי, ועד כדי כך שמרעישים ע\"ז בהתאוננות וכו'. ואת\"ל הרי בנוגע לכת\"ר, לדעתי כרם שלו הוא ענין האנציקלופדי' וביחד ע\"ז - הפצת המעינות באופן המתאים, וחוששני לומר ע\"פ התחלת מכתב כת\"ר - ששמים אותו לנוטר כרמים עניני רבנות וכו' כרמים ע\"פ תורה אבל לא כרמו שלו, מצוה שאי אפשר לעשותה על ידי אחרים.</p>\n<p>הפ\"נ שבמכתבו יקרא בעת רצון על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ויהי רצון שיבש\"ט בזה.</p>\n<p>ימים אלו בקר אצלי הרה\"ג הר\"ש עלברג שי' ובשיחתנו הזכרתיו על הבטחתו להו\"ל חוברת \"פרדס\" מוקדשת לרבנו הזקן (בקשר עם שנת הק\"ן להסתלקות הילולא שלו בשנה העברה), וענני אשר בביקורו באה\"ק ת\"ו דבר עם כת\"ר שישתתף במאמרו בחוברת האמורה, ועד עתה לא בא הדבר לפועל, אבל מבטיח הוא שכשיקבל מכת\"ר כנ\"ל - הרי במשך זמן לא ארוך יו\"ל חוברת עם עוד מאמרים, אלא שצ\"ל מאמר מכת\"ר - שעדיין <b>לא</b> נתפרסם. ובודאי הוספה מצדי על הכתוב לעיל אין בה צורך, כ\"א על יסוד מאמר חז\"ל אין מזרזין אלא למזורזין ולהוסיף גם מצדי בקשה וזירוז בהאמור.</p>\n<p>ובעמדנו ביום ל\"ג בעומר, יום הילולא דרשב\"י, ובהקדים מאמר חז\"ל (ריש ב\"ר) שהתורה דיפתראות ופנקסאות שע\"פ נברא העולם, ומובן שכן הוא גם בנוגע לעולם קטן זה האדם, ועאכו\"כ בנוגע לאלו שתורתם אומנתם, שהדוגמא בתורה (שבת יא, א) לתורתם אומנתם - הרי הוא רשב\"י וחבריו.</p>\n<p>וענין רשב\"י בתורה, שמזה הבנה גם לענינו בעולם, להסיר המחיצה (ד\"ה חייב אדם תרל\"ח סכ\"ה) שבין פנימיות התורה ונגלה דתורה ובאופן להמשיך הפנימית בגלוי, שלכן גם הנהגתו בעולם היתה באופן זה, שפנימיות העולם - היינו התורה - עסקו בה המשיך בגלוי גשם כפשוטו וכמסופר בזהר הק' (והחרים תרל\"א ד\"ה ובי' ענין נחל איתן).</p>\n<p>שמזה הוראה לדרא דעקבתא דמשיחא, שהוא בכמה ענינים בדוגמת דרא דרשב\"י כמבואר בחז\"ל זח\"ג נח, א (ע\"פ זח\"א קיז, א) - שענינו ונקודתו העיקרית צ\"ל המשכת פנימיות התורה בגלוי, וכסגנון הידוע הפצת המעינות חוצה, ומזה גם הוראה לאדם בנוגע להנהגתו בעולם וכסגנון הרמב\"ם, שיהי' <b>ניכר</b> במעשיו (ומפרט - כולל - עשרה דברים: במאכלו ובמשקהו וכו' ובמשאו ובמתנו) שזהו ע\"פ תורה, הנגלה והפנימית מאוחדים לתורה אחת.</p>\n<p>וכלשון רבותינו נשיאינו, עקב אשר שמע, שגם העקב הוא חסידותי.</p>\n<p>בכבוד ובברכה לבשו\"ט בכל האמור</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתיט</b></i></h4>\n<p><b>הרש\"י:</b> זוין. אגרות נוספות אליו - לעיל ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>בהליקוט:</b> לקו\"ש ח\"ד ע' 1090 הערה 31.</p>\n<p><b>כרם שלו:</b> ראה גם לקמן אגרת ח'תתצט, ובהנסמן בהערות שם.</p>\n<p><b>על הבטחתו:</b> ראה גם לקמן אגרת ח'תתמז.</p>\n<p><b>מאמר חז\"ל:</b> מכות כג, א.</p>\n<p><b>ובעמדנו:</b> ראה גם אגרת שלאח\"ז.</p>\n<p><b>עולם קטן:</b> תנחומא פקודי ג.</p>\n<p><b>וכסגנון הרמב\"ם:</b> הל' דעות רפ\"ה.</p>\n<p><b>וכלשון רבותינו:</b> ראה גם לקו\"ש ח\"כ ע' 297 ובהנסמן בהערה 36.</p>"],[1200970145,"ח'תתכ\n\n<p>ב\"ה, ל\"ג בעומר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו ביום ל\"ג בעומר, יום הילולא דרשב\"י, ובהקדים מאמר חז\"ל שהתורה היא דיפתראות ופנקסאות שע\"פ נברא העולם, מובן שכן הוא גם בנוגע לעולם קטן הוא האדם, ועאכו\"כ בנוגע לאלו שתורתן אומנתן, שהדוגמא המובאת בתורה לתורתן אומנתן הרי הוא רשב\"י וחבריו.</p>\n<p>וענין רשב\"י בתורה (שמזה גם מובנת הכוונה בנוגע לענינו בעולם) הוא - להמשיך פנימיות התורה באופן שתבוא הפנימית בגלוי, שלכן גם הנהגתו בעולם היתה באופן זה, שפנימיות העולם היינו התורה - עסקו בה המשיך בגלוי ירידת גשם, וכמסופר בזהר - כללות ענינו: בירור המחיצה שבין עליונים לתחתונים.</p>\n<p>שמזה הוראה לדרא דעקבתא דמשיחא, שהוא - בכמה ענינים - בדוגמת דרא דרשב\"י כמבואר בזהר - שענינו ונקודתו העיקרית צ\"ל המשכת פנימיות התורה בגלוי וכסגנון הידוע הפצת המעינות חוצה, ומזה גם בנוגע להנהגות האדם בעולם ובלשון הרמב\"ם שיהי' <b>ניכר</b> במעשיו (שמעשיו כולל עשרת הענינים:) במאכלו ובמשקהו וכו' ובמשאו ובמתנו - שהם ע\"פ תורה, הנגלה והפנימית מאוחדים, תורה אחת.</p>\n<p>וע\"פ ביאור רבותינו נשיאינו דיוק הלשונות וכן השבח \"עקב אשר שמע\" ש(גם) העקב \"שמע\" - שאפילו העקב ועניניו יהי' חסידותי.</p>\n<p>בברכה להצלחה בעבוה\"ק</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתכ</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ז ע' 340 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>לעולם קטן:</b> תנחומא פקודי ג.</p>\n<p><b>שיחת.. תש\"ח:</b> סה\"מ תש\"ח ע' 253.</p>\n<p><b>מאמר חז\"ל: </b>ב\"ר בתחלתו.</p>\n<p><b>שהדוגמא המובאת בתורה: </b>שבת יא, א.</p>\n<p><b>הפנימית בגלוי: </b>ראה מאמר דל\"ג בעומר בהמשך והחרים תרל\"א.</p>\n<p><b>בזהר: </b>ח\"ג נט, ב.</p>\n<p><b>בירור המחיצה: </b>עיין המשך חייב אדם לברך תרל\"ח סכ\"ה.</p>\n<p><b>כמבואר בזהר: </b>ח\"ג נח, א (ראה זח\"א קיז, א. קיח, א).</p>\n<p><b>וכסגנון הידוע: </b>אגרת הבעש\"ט הידועה קרוב לסיומה (נדפסה בסוף ס' בן פורת יוסף.</p>\n<p>ועוד).</p>\n<p><b>ובלשון הרמב\"ם: </b>הל' דעות רפ\"ה.</p>\n<p><b>שמעשיו כולל: </b>שלכן כ' במאכלו - בלא וא\"ו המוסיף.</p>\n<p><b>וע\"פ ביאור רבותינו: </b>התמים ח\"ו ע' נב. שיחת י\"ב תמוז תש\"ח ([סעיף] ז, ח).</p>\n<p><b>עקב.. העקב: </b>ראה שהש\"ר רפ\"ו. אוה\"ת (להצ\"צ) עה\"פ והי' עקב תשמעון.</p>"],[1200970146,"ח'תתכא\n\n<p>ב\"ה, ל\"ג בעומר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>כבוד המשתתפים בחגיגת חנוכת הבית של<br>\nביה\"ס<br>\nוהסמנריון \"בית רבקה\" יערש, צרפת<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>לקראת חגיגת חנוכת הבית של בית הספר והסמנריון \"בית רבקה\", הנני בזה להביע ברכתי לכל המשתתפים בשמחה של מצוה גדולה זו, ובראשם הרבנים שליט\"א ועסקני הציבור שליט\"א וכל מי שעזר והשתדל במפעל הגדול הזה, בין בגופו בין בממונו, הקב\"ה ישלם שכרם וישלח ברכה והצלחה בכל מעשה ידיהם.</p>\n<p>ידוע כמה הפליגו חכמינו ז\"ל בכבוד נשי ובנות ישראל וכמה הדגישו גודל חשיבותן בחיי עמנו, עד שאמרו שכשבא הקב\"ה לתת התורה לעמו ישראל, תורת חיים הוראה בחיי היום-יום, פנה אל הנשים תחילה, כדרשת רבותינו ז\"ל: כה תאמר לבית יעקב - אלו הנשים, ותגיד לבני ישראל - אלו האנשים.</p>\n<p>ואם בכל הזמנים והתקופות הי' כן, על אחת כמה וכמה בתקופתנו, אשר הסביבה ו\"הרחוב\" הם לא כמו שהיו לפנים ספוגי יהדות וחיי תורה אלא אדרבה, ולפעמים גם מנגדים ונלחמים בזה, וכל חינוכם של בני ובנות ישראל ברוח התורה והמצוה הוא במוסדות החינוך שעל טהרת הקדש ובבית פנימה. ורואים במוחש, שמפני כמה סיבות (תנאי החיים, טרדת הבעל בעניני פרנסה וכו'), החינוך שבבית תלוי בעיקר - בעקרת הבית אם הבנים.</p>\n<p>ומכאן גודל ערך ביה\"ס והסמנריון \"בית רבקה\" שמתפקידיו העקריים הוא לא רק לחנך מורות ומדריכות, אלא גם לחנך בנות ישראל לעיקר תפקידן - להיות עקרת הבית ולבנות את בית ישראל.</p>\n<p>ועוד זאת בחינוך - שכל הטבה בילד או בילדה בקטנותם, ואפילו בפרט קטן, עלול לעשות שנוי עקרי בגדלותם, וכידוע המשל מגרעין הנטוע להיות אילן עושה פירות.</p>\n<p>ובפרט כאשר המחונכים והמושפעים דהיום - הם המחנכים ומשפיעים דמחר.</p>\n<p>והרי ביה\"ס והסמנריון \"בית רבקה\" מאחד כל הנקודות האמורות.</p>\n<p>ובודאי כל מי אשר לבו ער ליהדות ולטובתו האמתי של בית ישראל - ישתדל ככל האפשר לטובת המוסד והבנין על כל פרטיו, למען אשר גדול יהי' כבוד הבית הזה בבנינו וגם ועיקר - בהתלמידות אשר בו המחונכות והמושפעות, גדול באיכות וגם בכמות.</p>\n<p>בכבוד ובברכה להצלחה בכל האמור.</p>\n<h4><i><b>ח'תתכא</b></i></h4>\n<p><b>עד שאמרו:</b> מכילתא ופרש\"י יתרו יט, ג.</p>\n<p><b>ועוד זאת בחינוך:</b> ראה גם לקמן אגרת ח'תתקלא.</p>"],[1200970147,"ח'תתכב\n\n<p>ב\"ה, ל\"ג בעומר, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הנהלת בית הספר והסמנריון \"בית רבקה\"<br>\nיערש, צרפת<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי הידיעה על דבר תיקון ספר זכרון לתומכי מוסדות האמורים, והריני גם אני משתתפים בו בחפץ לב.</p>\n<p>ואני תפלה אשר ספר זכרון זה יתאים למה שנאמר: אז נדברו יראו ה' גו' ויכתב ספר זכרון לפניו גו' ולחושבי שמו. שבפסוק זה כלולים ג' הלבושים של הנשמה, הן שלש דרכי הפעולה של האדם: מחשבה דיבור ומעשה.</p>\n<p>ומעשה עיקר, שכל ענין הקשור במעשה בפועל - יש לו המשך וקיום, ועל אחת כמה וכמה בעניני טוב אמת וקדושה, שכללות ענינם היא - שהם נצחים.</p>\n<p>ובפרט ענין הקשור בחינוך על טהרת הקדש, ועל כולנה מוסד חינוך \"בית רבקה\", שמטרתו לא רק לחנך בנות ישראל שתהיינה ראויות לשמן, בנות שרה רבקה רחל ולאה אשר בנו את בית ישראל, אלא הוא גם מוסד המחנך מחנכות, מחנכות באופן של גידולי פירות ופירי פירות, מוסיף והולך מוסיף ואור.</p>\n<p>ויהי רצון שכל הנרשמים בספר זכרון זה, יעלה זכרונם ופקדונם לפני ה' לטובה לחן ולחסד ולרחמים ולחיים טובים ולשלום, בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה.</p>\n<h4><i><b>ח'תתכב</b></i></h4>\n<p>אגרת זו נדפסה בטעות לעיל ח\"ט אגרת ב'תרסב.</p>\n<p><b>ומעשה עיקר:</b> אבות פ\"א מי\"ז.</p>"],[1200970148,"ח'תתכג\n\n<p>ב\"ה, כ\"ג אייר, תשכ\"ד</p><p>ברוקלין.</p><p>הרה\"ג וו\"ח אי\"א רב פעלים ובעל מדות<br>\nהר\"ן שי'</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי ז\"ע ספרו טהרת מים מהדורא תליתאי.</p>\n<p>ויהי רצון שגם מהדורא זו תשיג המטרה לבסס ולהפיץ ענין דטהרת בנות ישראל, אחד היסודות דבית ישראל בכללותו, וביתו הפרטי של כל אחד ואחת.</p>\n<p>וכיון שיסוד כשמו עליו מיוסד קיום הבית הנבנה עליו, מובן שכל הוספה בחוזק ואיתנות היסוד, יש להגדיל אותה ככל האפשרי בכל כגון זה. והובטחנו מחז\"ל הבא לטהר, וידוע דיוק רבנו הזקן, לטהר גם אחרים, מסייעין אותו.</p>\n<p>וכנראה במוחש דוקא בתקופתנו זו אשר הבע\"ב והצעירים בראשם, מקבלים בחפץ לב כל הוראה להידור בענין אמור, ועאכו\"כ בפרטים שלהם יסוד בדין.</p>\n<p>ואת\"ל הרי בענין זה עצמו הודגש הדבר, הן בהטומאה - שהיא במשהו (ובחומרא דרבי זירא, דהלכה פסוקה היא להחמיר) וכן באופן הטהרה דאפילו שערה אחת מעכבת כל הענין.</p>\n<p>ובעמדנו בימי הספירה שכביאור חז\"ל ספירה זו, דוספרתם לכם, הוא ברוחניות הענין דוספרה לה שבעת ימים,</p>\n<p>יהי רצון שבקרוב ממש יקוים היעוד, דהספירה תביא לואחר תטהר לוזרקתי עליכם מים טהורים וטהרתם בגאולה האמיתית הושלימה על ידי משיח צדקנו.</p>\n<p>בכבוד ובברכה לארך ימים ושנים טובות ולראות פרי טוב בעמלו עמל תורה המביא לידי הלכה למעשה ומתוך בריאות הנכונה.</p>\n<p>ע\"פ הנ\"ל בסיום המכ' - יש לבאר שייכות בקשת יה\" כו' שיבנה ביהמ\"ק כו' לספירה ואפילו להאומרים דגם בזמה\"ז היא מה\"ת.</p>\n<h4><i><b>ח'תתכג</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ב ע' 238 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>הר\"ן:</b> טלושקין, ברוקלין. אגרות נוספות אליו - לעיל ח'תשמא, ובהנסמן בהערות שם.</p>\n<p><b>והובטחנו.. דיוק:</b> יומא לח, ב. לקו\"ת דרושים לשמע\"צ פח, ב.</p>\n<p><b>ובחומרא דרבי זירא:</b> ברכות לא, א. וש\"נ.</p>\n<p><b>שכביאור חז\"ל:</b> זח\"ג צז, סע\"א.</p>\n<p><b>ואפילו להאומרים:</b> רמב\"ם הל' תמידין ומוספין פ\"ז הכ\"ד.</p>"],[1200970149,"ח'תתכד\n\n<p>ב\"ה, כ\"ג אייר, תשכ\"ד</p><p>ברוקלין.</p><p>מר צבי שי' המכונה ד\"ר הרכבי</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו, בו כותב ג\"כ שלאחרונה לא פרסם דבר, ומובן שהפליאה בזה עוד יותר מאשר הפליאה הראשונה, שאמרתי שפרסם ולא שלח לכאן.</p>\n<p>בהתענינות קראתי ע\"ד קרוביו שי' אשר שם וכו' ומענין לענין באותו ענין, ארשה להעתיק כאן אחת הנקודות ממה שנדבר בענין זה, מיוסדת על הפס\"ד אשר כל ישראל הם קומה אחת שלימה, ובדוגמת הגוף, אשר חיזוק הבריאות באיזה אבר שיהי' מוסיפה בבריאות כל שאר האברים, כן הוא בנוגע לאברי פרטי קומה שלימה האמורה, ומזה מסקנא מידית אשר הוספה בתורה ומצותי' בהמעשה שהוא העיקר, קיום מצות מעשיות יום יום, שהם חיונים וקיום ויסוד כל בני ישראל [מתאים לשמם תורת חיים ומצותי' עליהן נאמר וחי בהם], הרי בודאי ובודאי שזהו מוסיף \"בבריאות\" כל אחד ואחת מבני ישראל, ואין המקום מפסיק ככל וכלל, וכנ\"ל זהו עזר וסיוע ודאי וממשי מצ\"ע וגם - להצלחת ההשתדלות באופנים אחרים, ודוקא ע\"ד עזר זה אין איש מתעסק בזה ואפילו לא מדבר וד\"ל.</p>\n<p>והרי בסיוע זה אין זקוקים לאסיפות ולהצבעות ולשאלת דעת הרוב, כיון שלכל אחד בחירה חפשית בזה ויכול להוסיף כהנה וכהנה כולל גם בהשפעה על הזולת לקרבו עוד יותר ויותר, לתורה ולמצותי', ועי\"ז לעזור לכל בנ\"י בכל מקום שהם הן באה\"ק ת\"ו והן בתפוצות, שהרי כולם זקוקים לעזר, אף כי לא באותו השטח ובאותה המדה, וק\"ל.</p>\n<p>והרי הימים ימי סגולה, ימי הספירה המקשרים ענין זמן חירותנו עם ימי קבלת התורה ובהקדמת נעשה לנשמע, קבלה ביחד עם הבטחה - חרות על הלוחות.</p>\n<p>בכבוד ובברכה.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתכד</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ג ע' 238 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מר צבי.. הרכבי:</b> אגרות נוספות אליו - לעיל ח'תשיט, ובהנסמן בהערות שם.</p>\n<p><b>שאמרתי:</b> לעיל אגרת ח'תשעט.</p>\n<p><b>שם:</b> ברוסיא.</p>\n<p><b>ממה שנדבר:</b> ראה גם לעיל חכ\"ב אגרת ח'תקיג, ובהנסמן בהערות שם.</p>\n<p><b>הפס\"ד:</b> ראה גם לקו\"ש ח\"ל ע' 19 - 218 ובהנסמן בהערה 43.</p>\n<p><b>בהמעשה שהוא העיקר:</b> אבות פ\"א מי\"ז.</p>\n<p><b>חרות:</b> אבות פ\"ו מ\"ב.</p>"],[1200970150,"ח'תתכה\n\n<p>ב\"ה, כ\"ד אייר, תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>...ע\"פ מה ששמענו כ\"פ מכ\"ק מו\"ח אדמו\"ר נשיא ישראל - פשוט שצ\"ל חינוך בני ובנות אנ\"ש במוסדות חינוך חב\"דיים - <b>בכל</b> שלבי הגיל שלהם.</p>\n<p>מובן ששמעתי ע\"ד כו\"כ מאנ\"ש שי' שנוהגים אחרת ולא עוד אלא ש\"מלבישים\" את זה באיצטלא של יר\"ש - ומצטער אני עליהם ועוד יותר על יו\"ח שי' - שהרי אלה הצאן מה חטאו. ויה\"ר שגם על אלה הנחשלים יערה רוח ממרום וכו'.</p>\n<h4><i><b>ח'תתכה</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ב ע' 417.</p>\n<p><b>ע\"פ מה ששמענו:</b> ראה גם לעיל ח\"כ אגרת ז'תשמב. חי\"ד אגרת ד'תתקלד. חי\"ג אגרת ד'שסה.</p>"],[1200970151,"ח'תתכו\n\n<p>ב\"ה, כ\"ד איר, תשכ\"ד</p><p>ברוקלין.</p><p>מר ציון שי'</p>\n<p>שלום וברכה!</p>\n<p>בנעימות קורא הנני מפעם לפעם במכתבי הרה\"ח רב פעלים אי\"א נו\"נ בעל מדות הרח\"ש שי' ברוק ע\"ד פעולות כ' בעניני יהדות אשר במחנם הט', כולל ובפרט אודות פעולותיו ועזרתו בעניני הישיבה הק' אחי תמימים אשר בהנהלת הרח\"ש שי' הנ\"ל.</p>\n<p>ואף ששכר מצוה מצוה, פירוש שהשכר הכי גדול הוא עצם פעולת המצוה, שלכאורה אין מקום לנתינת תודה מבשר ודם, עכ\"ז - מחובתי וענג הוא לי להביע תודה על גודל הקורת רוח נוסף על הענין, כנ\"ל, דשכר מצוה מצוה.</p>\n<p>וגדול זכות פעולות האמורות שתעמוד לו לזוגתו ולכב\"ב שי' בכל המצטרך להם מנפש ועד בשר.</p>\n<p>בכבוד ובברכה להמשיך בפעולות האמורות מתוך בריאות שמחה וטוב לבב, והרי זכות הרבים מסייעתו.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתכו</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 356 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מר ציון:</b> כהן, רחובות. אגרת נוספת אליו - לעיל חכ\"ב ח'תרסז.</p>\n<p><b>אחי תמימים:</b> בראשון לציון.</p>\n<p><b>ששכר מצוה:</b> אבות פ\"ד מ\"ב. וראה גם לעיל ח\"ט אגרת ב'תרלד. ס' השיחות תשמ\"ט ח\"ב ע' 642 ואילך.</p>"],[1200970152,"ח'תתכז\n\n<p>ב\"ה, כ\"ה אייר, תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>ברכה ושלום!</p>\n<p>מיט גרויס פארוואונדערונג און נאך גרעסערן צער האב. איך געלייענט אייער בריוו, וועלכן איר הויבט אן מיט א לויב צום אויבערשטן וואס איר רעכנט (ח\"ו) פארן אין ארץ ישראל מיט א שיף וואס אירע בעלי-בתים זיינען אידן, און דער קאפיטאן און מאטראסן און גאנצע מאנשאפט און באדינונג זיינען אלע אידן אדער</p>\n<p>99 פון זיי זיינען אידן; און איר זעצט פאר אייער שרייבן, אז דער זכות פון די הייליקע אבות אבותינו זאל מצליח זיין די נסיעה!</p>\n<p>איך וואלט גערעכנט, אז ס'איז איבעריק צו דערקלערן די סיבה פון מיין גרויסן צער, אבער דער אינהאלט פון אייער בריוו ברענגט מיט צום שרייבן וועגן דעם ווייניקסטנס געציילטע שורות, כאטש וויפל מ'וואלט וועגן דעם ניט געשריבן וואט געווען ווייניק אין פארגלייך מיט דער הארבקייט פון דער זאך. אין קורצן:</p>\n<p>א נסיעה אויף אזא מין סארט שיף - איז יעדער פארער, שוין אפגערעדט פון דער מאנשאפט וואס איז באשעפטיקט אויף דער שיף, א) מחלל שבת, ב) בפרהסיא, ג) נעמט אן אנטייל אין חילול השם בפרהסיא (אויך פאר אלע גויים) וואס ווייסן פון דאס אויב[נ] דערמאנטע, ד) דאס ווערט געטאן אין נאמען פון גאנצן אידישן פאלק, וועמענס ביי-שטייערונגען בא פארשידענע געלעגנהייטן האט בייגעטראגן צו דער אפערירונג און פונקציאנירן פון דער שיף אום שבת.</p>\n<p>ס'איז נאך צוצוגעגעבן, אז ס'איז א זעלטענע מעגלעכקייט צו מחלל שבת זיין בפרהסיא <b>יעדן רגע</b> פון דעם מעת-לעת פון שבת-קודש, אפילו ווען מען שלאפט! ווארום די שיף פארט דאך אויך ווען מען שלאפט. [דאקעגן, זייענדיק אויף דער יבשה, וואס פארא סארט לעבן איינער פירט, איז ער אבער ווייניקסטענס שלאפנדיק ניט עובר אויף חילול שבת בפרהסיא].</p>\n<p>דאס אויבנגעשריבענע איז אין פולער קראפט וואוהין די שיף זאל ניט פארן און ווען זי זאל ארויספארן, אויב נאר זי פארט אין מעת-לעת פון שבת. אין דעם פאל קומט נאך צו דאס וואס מ'וויל פארן אין א לאנד וואס אפילו גויים רופן אן \"דאס <b>הייליקע</b> לאנד\", ניט דערפאר וואס די יונייטעד ניישאנס האלט אזוי, נאר דערפאר וואס אזוי איז געשריבן אין אונזער הייליקער תורה, וועלכע האט פארבונדן דעם קיום פון ארץ ישראל ספעציעל מיט אפהיטן שבת, ווי אנגעוויזן אין פיל סדרות, צווישן זיי - בהשגחה פרטית - אויך אין דער סדרה וואס מ'גייט לייענען <b>דעם שבת-קודש</b>.</p>\n<p>דאס אויבנגעשריבענע איז שוין אויך א מאקסימום אומגליק ר\"ל, אבער די נסיעה וועגן וועלכע איר שרייבט קומט דא נאך צו אן אומגליק אויף אן אומגליק, וואס אין צוגאב צו די צוויי אדער דריי שבתים וואס ווי אויב[נ]געשריבן זיינען פארבונדן מיט חילול שבת בפרהסיא ח\"ו, <b>קומט</b> אין דעם פאל נאך צו דער חילול פון ביידע טעג שבועות בפרהסיא, דער יום-טוב ווען עס איז געגעבן געווארן די עשרות הדברות, געגעבן געווארן מיטן גאנצן שטורם, ווי עס ווערט דערציילט אין מדרשים, וואס איינער פון די עשרת הדברות איז <b>שמור את יום השבת לקדשו</b>. מערניט וואס מ'לעבט אין א צייט ווען מגעוואוינט זיך צו צו אלערליי אומגלויבלעכע זאכן קען אויך פארקומען א געשעניש ווי אויבענגעשריבן, באין פוצה פה ומצפצף.</p>\n<p>זעלבסטפארשטענדלעך ווייס איך, אז עס זיינען דא אזוינע וואס האבן גענומען אויף זיך די אחריות - <b>ניט</b> וויסנדיק ווי אזוי א שיף ווערט אנגעפירט, און צו דער זעלבער צייט האלטנדיק זיך פאר גרויסע עקספערטן אין דעם - און האבן מתיר געווען דעם חילול שבת בפרהסיא וואס ווערט אנגעפירט אין נאמען פון כלל ישראל. און וועדליג ווי מ'דערציילט איז צו גלויבן אז שבת זאל אויף דער שיף שטיין א איד אין א טלית און דאוונען צום אויבערשטן <b>מקדש השבת</b>, וויסנדיק אז בשעת מעשה ווערט די מאשינעריי אנגעצונדן און אנגעפירט דורך אידן, טעלעגראמעס ווערן געשריבן און קאמוניקאציעס געמאכט, געקאכט און געוואשן אא\"וו, אלץ דורך אידן, ספעציעל פאר אידן, און יעדערער פון די פאסאזשירן באנוצט זיך דערמיט, ווי אויך מיט עלעקטריציטעט, וואסער, <b>און</b> אלע באדינונגען וואס ווערן אפגעטאן מיט חילול שבת.</p>\n<p>אבער ס'איז אויך זעלבסטפארשטענדלעך, אז תורתנו הקדושה ווערט דערמיט ניט געענדערט, ווארום אונזער הייליקע תורה איז אן אייביקע תורה וואס דער אויבערשטער האט געגעבן צום אידישן פאלק, און מענטשן קענען זי ניט ענדערן.</p>\n<p>אזוי ווי חכמינו זכרונם לברכה האבן אנגעזאגט, אז א איד טאר קיינמאל זיך ניט מייאש זיין, וויל איך נאך איצט ניט אויפגעבן די האפנונג אז איר און צוזאמען מיט אייך נאך פיל פיל אידן וועלן ניט טאן דעם חילול שבת בפרהסיא און דעם חילול יום-טוב בפרהסיא, און איר וועט מבטל זיין אייער דערמאנטע נסיעה. און גרויס איז דער זכות פון שבת צו ברענגען אייך אריכות ימים ושנים טובות, און זעלבסט-פארשטענדלעך די עיקר'דיקע זאך - צו האבן אמתע אידישע תורה-נחת פון אייערע קינדער און קינדסקינדער שיחיו.</p>\n<p>בברכה צו גוטע בשורות אין דאס געשריבענע אויבן.</p>\n<p>אויב מצד דעם וואס מען איז מבטל די נסיעה אזוי קורץ פארן אפפארן איז דאס פארבונדן מיט א געלט-פארלוסט, איז <b>פארשטייט זיך</b> אז נעמענדיק אין אכט דעם גרויסן איסור בפרהסיא, וועל איך <b>גערן</b> אומקערן אייך די פולע סומע, מיט א הערצלעכן דאנק פאר דער געלעגנהייט מציל צו זיין א אידישע נשמה פון אזא אומגליק ר\"ל, אין צוגאב וואס עס איז דאך מעגלעך אז עס וועלן זיך געפינען נאך עטלעכע, וועלכע וועלן ניט האבן דעם אויסרייד אז אויב מרת... פארט איז א זיכערע זאך אז מ'מעג, און אויך אפהאלטן זיך דערפון. און ס'איז דאך באוואוסט, אז מציל זיין אפילו איין אידן איז גלייך צו מציל זיין א גאנצע וועלט.</p>\n<p>צו אייער בריוו האט איר צוגעלעגט א טשעק אויף צדקה אין צוזאמענהאנג מיט דער נסיעה. דאס איז דאס ערשטע מאל אין מיין לעבן - און איך האף אז איך וועל עס מער ניט דארפן טאן - וואס איך מוז אומקערן אזא טשעק. אבער עס איז <b>זעלבסטפארשטענדלעך</b>, אז איך טאר ניט האבן קיין שייכות צו אן ענין וואס איז פארבונדן מיט חילול שבת בפרהסיא, און בפרט אז מ'וויל אז די צדקה זאל צוהעלפן אין דעם חילול שבת ר\"ל. דערפאר ווערט דער טשעק דא אומגעקערט. איך וויל האפן אז אייר וועט אננעמען מיינע ווערטער, אין איינקלאנג מיט היינטיגער סדרה - <b>את</b> <b>שבתותי תשמורו</b> גו' אני ה'.</p>\n<h4><i><b>ח'תתכז</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ב ע' 257.</p>\n<p><b>פארן.. שיף:</b> ראה גם לעיל אגרת ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>באוואוסט:</b> ראה סנהדרין לז, א. וש\"נ.</p>"],[1200970153,"ח'תתכח\n\n<p>[אייר תשכ\"ד]</p>\n<p>אז צע\"ג אם יהי' ההפסק בר קיימא. 2) אם י\"ל ע\"ז אפילו בדוחק אמצע ביהכ\"נ משא\"כ כשיש עכ\"פ שורה א' מתפללים. דלפעמים עכ\"פ אמצע הוא לאפוקי קצוות - (וכידוע הראי' מתרומות ג, ה. עיין בציון ירושלים שם).</p>\n<h4><i><b>ח'תתכח</b></i></h4>\n<p>נדפסה בלקו\"ש חט\"ז ע' 615. והוא מענה למו\"ה שמואל פסח שי' בוגומילסקי במענה לשאלתו [בהמשך לאגרת ח'תתב דלעיל] אם מספיק מקום פנוי <b>שיעור</b> שורה א' יושבים בין מקום קרה\"ת וארון הקודש. אגרות נוספות אליו לעיל ח'תשצה, ובהנסמן בהערות שם.</p>"],[1200970154,"ח'תתכט\n\n<p>ב\"ה, ר\"ח סיון, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ חו\"ב פלפלן וחריף וכו' הרב<br>\nיצחק שי'</p>\n<p>שלום וברכה!</p>\n<p>זה מזמן רב אשר ראיתי והתבוננתי בשקידתו והתמדתו בלימוד התורה, שם לילות כימים ומוסיף מזמן לזמן,</p>\n<p>ולאחר זה גרמה לי קורת רוח מיוחדת הידיעה אשר, כפי שדברנו, הכין וסידר חדו\"ת בדפוס ובקרוב יופיעו ויו\"ל בעז\"ה.</p>\n<p>ותקותי חזקה אשר כהנ\"ל יעוררו להוסיף עוד בהתמדה ושקידה בנגלה ובפנימיות התורה (שבדורנו נתגלתה בתורת החסידות) ויראת ה' תהא אוצרו, וכציווי חז\"ל: ואפ\"ה יראת ה' היא אוצרו (עיי\"ש שבת לא, סע\"א), והרי ציווי תורתנו - גם נתינת כח הוא,</p>\n<p>וביחד עם זה - גם התעסקות בהפצת המעינות חוצה, צדקה ברוחניות וגם צדקה כפשוטה, למאן דלית לי' מגרמי' כלום ולהחיות רוח שפלים וכו',</p>\n<p>והרי צדקה תרומם גו', ועד שנעשים מוחו ולבו זכים אלף פעמים ככה,</p>\n<p>וכדברי רבנו הזקן בזה באר היטב בתחלת ספרו תורה אור,</p>\n<p>ויהי רצון אשר יהי' כל זה מתוך הרחבה בגשמיות וברוחניות.</p>\n<p><b>מנחם שניאורסאהו</b></p>\n<p>בברכה - בנוסח המקובל - לקבלת התורה בשמחה ובפנימיות ולהצלחה בכל האמור</p>\n<p>נ.ב. לחביבותא דמילתא באות בזה איזו הערות בספרו האמור.</p>\n<p><b>פתיחה. בתחלתה.</b> דביהמ\"ק <b>יסוד</b> העולם, שהרי הוא מז' דברים שקדמו לעולם.</p>\n<p>וכוונתו שמשם תתפשט השכינה (דנק' כן ע\"ש ושכנתי בתוכם - הנאמר בעשיית המשכן דאיקרי מקדש) בכל העולם.</p>\n<p>ויש לייסד זה במחז\"ל כי השתות - אילו ביהמ\"ק (סנה' כו, ב). ואפילו למאן דפליג שם בפי' הכתוב, לא פליג בגוף הדבר שביהמ\"ק הוא שתי' ויסוד העולם, שהם דברי חכמים (יומא נד, ב. וכהרמב\"ם בפיה\"מ שם).</p>\n<p>מהברייתא דז' דברים נבראו קודם שנברא העולם כו' ביהמ\"ק - ראיה על הקדימה, אבל לא שהוא יסודו של עולם ויסוד גם כפשוטו. ותורה ותשובה וכו' יוכיחו.</p>\n<p><b>שם.</b> ביהמ\"ק ענינו קרבנות וארון כו' מחלוקת הרמב\"ם והרמב\"ן כו'. עיי\"ש.</p>\n<p>יש להעיר כמה במש\"כ בספרו ומובן מהבא לקמן מה שנלפענ\"ד בביאור שיטת הרמב\"ם והרמב\"ן: א) בתכלית בנין ביהב\"ח. ב) בענין הארון - (והארכתי בכ\"ז במק\"א):</p>\n<p>א) כתב הרמב\"ם בסהמ\"צ (מ\"ע מצוה כ) ציוונו לבנות ביהב\"ח לעבודה בו יהי' ההקרבה כו' ואליו תהי' ההליכה ועלי' לרגל כו' והוא אמרו ית' ועשו לי מקדש. ועד\"ז הוא ברמב\"ם ריש הל' ביהב\"ח ובסהמ\"צ שורש יב. לא כן דעת הרמב\"ן שכתב: עיקר החפץ במשכן הוא מקום מנוחת השכינה שהוא הארון (ר\"פ תרומה. וראה ג\"כ רמב\"ן עקב י, ה).</p>\n<p>ולכאורה יוקשה בדעת הרמב\"ם, שהרי כתוב זה עצמו שמביאו \"ועשו לי</p>\n<p>מקדש\" - מבאר כוונת העשי' \"ושכנתי בתוכם\", ומקום \"ושכנתי\" זה - ג\"כ מפורש בכ\"מ בקרא שהוא הארון (עיי\"ש ברמב\"ן). וראי' (ועכ\"פ - זכר) לדבר גם מדברי הרמב\"ם עצמו (מו\"נ ח\"ג פמ\"ה) וז\"ל: וצוונו אנחנו שנבנה היכל לשמו יתעלה ונשים בו הארון שיש בו כו'.</p>\n<p>ועכצ\"ל שגם לדעת הרמב\"ם החפץ במקדש הוא מנוחת השכינה, ובעיקרה הוא על הארון, ובמילא מובן שבו תלוי' גם שלימות קדושת המשכן.</p>\n<p>- ולכן המשכן בזמן שלא הי' בו הארון, הי' לו דין במה גדולה (תוספתא זבחים ספי\"ג.</p>\n<p>וראה ג\"כ מאירי מגילה ט, ב). ואין להקשות מהא דביהמ\"ק בקדושתו גם לאחר שנגנז (ואפילו לאחר שניטל) הארון - כי הוא לפי ש\"שכינה אינה בטילה\" (רמב\"ם הל' ביהב\"ח ספ\"ו); משא\"כ המשכן שהי' מלכתחילה רק \"לפי שעה\", דירת עראי ולא מנוחה ונחלה. -</p>\n<p>אלא שהרמב\"ם מדבר בענין המצות שנצטוו בנ\"י <b>לעשות</b> בביהב\"ח, והרמב\"ן מדבר בענין <b>וחפץ</b> אשר במשכן <b>עצמו</b>, שהוא \"ושכנתי\" וזה הי' בעיקר - ע\"י הארון.</p>\n<p>ב) ידועה הקושיא על שלא מנה הרמב\"ם עשיית הארון במנין המצות (ובפרט - שמנה מצות משאו בכתף. ושקו\"ט בכ\"ז בארוכה בפי' רי\"פ פערלא לסהמ\"צ לרס\"ג בסופו פרשה נב). ולא עוד אלא שבסהמ\"צ שם כשמבאר הטעם שאינו מונה את עשיית \"המנורה והשלחן והמזבח וזולתם\" כי \"כלם מחלקי המקדש והכל יקרא מקדש\", אינו מזכיר כלל את הארון. - ולכאורה יש לתרץ - כי הארון ענינו <b>רק</b> כלי שיהי' \"ושכנתי בתוכם\", וזהו כללות ענין <b>כל</b> התומ\"צ, \"ואין ראוי למנות הציווים הכוללים התורה כולה\" (סהמ\"צ שרש ד'.</p>\n<p>וראה נ\"כ שם). והציווי לעשות הארון אף שהוא \"מעשה מיוחד\", הרי ענינו - כולל עניני \"התורה כולה\" ו\"המצות כולם\" ולכן נחשב כציווי כולל, וע\"ד וערפכם לא תקשו עוד - שמביא בסהמ\"צ שם. - ובכ\"ז נמנה בנין ביהב\"ח אף שענינו \"ושכנתי בתוכם\", כי בענין ביהב\"ח ישנם עוד ענינים: ההקרבה וכו', <b>והם</b> הם שנמנו בתרי\"ג המצות - משא\"כ בארון. (נתינת הלוחות בארון - לפי' זה - אינה אלא פרט מעניני (קדושת) הארון או - שאינה לדורות). - ובכ\"ז מונה הרמב\"ם מ\"ע דמשא בכתף ומל\"ת דלא יסורו, כי - לדיעה זו - אין תלוי' בזה <b>קדושת</b> הארון וענינו ד\"ושכנתי בתוכם\", כ\"א ציווי מיוחד הוא <b>לכהנים</b> שישאוהו בכתף וכו'.</p>\n<p>אבל פי' זה בשיטת הרמב\"ם דוחק הוא, דסו\"ס כיון שיש ציווי על <b>מעשה</b> מיוחד\", עשיית הארון - למה לא יכנס במנין המצות? ומה בכך <b>שענינו</b> כולל, כיון שנוסף ציווי \"מעשה מיוחד\". ולא עוד אלא שכש\"כ הוא ממ\"ע דאמונת ה' דמונה הרמב\"ם אף שענינה כולל עוד יותר (ולהעיר מסהמ\"צ להצ\"צ ריש מצות האמנת אלקות).</p>\n<p>ולכן צ\"ל פי' שיטת הרמב\"ם באופן אחר, ובהקדם התמי' <b>גדולות</b>: א) למה השמיט הרמב\"ם כל דיני עשיית הארון? ב) איך זה נטל יאשיהו הארון ממקומו <b>שנצטוו</b> בנ\"י לשומו שם וגנזו? ובש\"ס (יומא נב, ב) מוכח שלא הי' זה ע\"פ הציווי וכיו\"ב, כ\"א <b>שדאג</b> <b>שמא</b> יגלה לבבל <b>לאחרי זמן?</b></p>\n<p>ולתרץ כל הנ\"ל י\"ל - דמעשה יאשיהו <b>מוכיח</b> דקראי <b>כפשוטם</b>, דעשיית הארון והבאתו לקדה\"ק הוא אך ורק כדי שיהי' \"ונועדתי לך שם\". ולאחרי שנעשה זה ובאופן ד\"אינה בטילה\" לעולם - שוב <b>לא מצינו מצוה</b> בעשיית הארון. אלא שכל זמן שישנו (ולאחרי שיתגלה לעת\"ל) - נצטוו לשאתו בכתף ושלא יסירו הבדים. - ולכן לא נמנית עשיית הארון במצות (לדורות) ולא הובאו דיני עשייתו, כי מאי דהוי הוי, ומזמן בנין ביהמ\"ק הא' - אין כל ציווי בזה. ובזה מתורץ ג\"כ הא דבמלחמות פלשתים וכיו\"ב לא גנזו את הארון עד עבור המלחמה (וע\"ד שעשה יאשיהו) - וע\"פ הנ\"ל מובן, כי במשכן שילה וכו' - נטילת הארון ממקומו היתה מבטלת ה\"ונועדתי לך שם\", שהרי בנטילתו הי' למשכן רק קדושת במה גדולה וכנ\"ל, (והטעם - מפני שהיתה רק דירת עראי)</p>\n<p>- ורק שבמקום פקו\"נ (מיתת אנשי בית שמש - ש\"א ו, יט - ומיתת עוזה - ש\"ב ו, ז) הותר שלא להחזיר הארון למשכן -</p>\n<p>וע\"פ הנ\"ל, מעשה יאשיהו - ראי' חזקה לשיטת הרמב\"ם דאין מ\"ע כלל (משנבנה ביהמ\"ק) לעשות ארון. - ולפע\"ד כ\"ז ברור וגם פשוט.</p>\n<p>אלא שמ\"מ גנז יאשיהו את הארון בביהמ\"ק דוקא ולא במקום אחר, כי אף ש\"שכינה אינה בטילה\", מ\"מ <b>כמה</b> דרגות בהשראת השכינה שבבית המקדש, כמפורש ביומא כא, ב.</p>\n<p>ונצטוו במ\"ע <b>נצחית</b> - שבביהמ\"ק תהי' אותה דרגת ההשראה שבאה ע\"י שהכניסו לשם הארון באופן דדירת קבע. ובעת שישראל זוכין יש דרגא נעלית מזו: כשהארון נמצא (עכ\"פ גנוז) שביהמ\"ק, יותר מזה - כשנמצא במקומו (בקדה\"ק וכו').</p>\n<p>אלא שעדיין יש להבין: לדעת המ\"ד (ירוש' יומא פ\"ה ה\"ד) דהזי' על הכפורת צריך שיגע - איך זה גנז יאשיהו את הארון, שהרי (עכ\"פ לכתחילה) צריך שיגע. - וי\"ל: א) דהדאגה שיגלה לבבל מספיק כוחה לגנוז הארון <b>בזמן שאין כל חיוב</b> (אפילו לכתחילה) שיהי' בקה\"ק, אף <b>שלאח\"ז</b> בדרך <b>ממילא</b> לא תוכל להיות הנגיעה ביוהכ\"פ (וכמה דוגמאות לזה, ואפילו בחיוב ואיסור ברור. וראה בזה שדי חמד אס\"ד מע' יוהכ\"פ ס\"א סק\"י. <b>וש\"נ</b> לש\"ס, ראשונים וכו'). ב) מ\"ד דצריך שיגע - יסבור כמ\"ד דלא גנזו יאשיהו (אלא שניטל הארון לבבל). [ודלא כפסק הרמב\"ם - דנגנז].</p>\n<p>* * *</p>\n<p>עפ\"י הנ\"ל לא הי' בארון שום עבודה (כמו בשאר כלי המשכן); וענינו הוא כלי להגילוי שלמעלה.</p>\n<p>וצע\"ק מענין ההזי' על בין הבדים וכו'. וי\"ל בהקדם התמי' איך הי' בזה כל אותן השנים שהי' המשכן בנוב וגבעון והארון בקרית יערים ועיר ציון. וע\"כ צ\"ל שהעיקר בזה <b>מקום</b> (בדי) הארון שבקדה\"ק. אבל קשה למ\"ד דהזי' על הכפורת צריך שיגע בכפורת (ירושלמי שם). ועכצ\"ל דגם לדידי' אינו מעכב כלל ונוב וגבעון יוכיחו. ועצ\"ע.</p>\n<p>* * *</p>\n<p><b>בתחלתו. ע' כג.</b> גגי ירושלים וחומתה וקדושתן וכו'. עיין צפנת פענח - להגאון הרגצובי - למכות (יח, א) ודף יט שמשווה דברי הרמב\"ם וכו' - ע\"פ ההנחה דיש דבר הצריך פנים ויש דבר שפסול בחוץ והנ\"ל וכו' לא הוי חוץ וגם פנים לא הוי. - שוב ראיתי שנגע בזה בספרו (ע' כו).</p>\n<p><b>שם ע' נא.</b> דחיובי שבת הוא שלא יפעול הפעולה ולא שלא תיעשה הפעולה, ולדוגמא בכתיבה וכו'. - אין לומר כן בכל חיובי שבת, כדמוכח בכ\"מ ובפרט בנוגע לכתיבה - מחיוב נטלו לגגו דחי\"ת ועשאו ב' זייני\"ן (שבת קד, סע\"ב). ואף דפרש\"י שם והספר לכך צריך - אין הטעם משום משלים וכו' (כי זהו פי' רבא שם), אלא דחשיב כותב ב' אותיות (ואף שלכאורה ראי' להיפך מהא דכתיבה בשמאל פטור - י\"ל הטעם שא\"א שתהי' כתיבה ביד כהה (ועיין צ\"צ לשבת פי\"ב מ\"ה (נ, ג)) - כזו שביד ימין <b>שלו</b>). ולהעיר גם מהוציא חצי גרוגרת ואח\"כ עוד חצי גרוגרת שאם קדם והגבי' ראשונה פטור (שבת פ, א).</p>\n<p>וצע\"ק ממה שצ\"ל כדרך המוציאין דוקא (שבת צב, א) וי\"ל שא\"ל לא מקרי הוצאה.</p>\n<p>ולהעיר מתוד\"ה בהעלם (ב\"ב נה, סע\"ב). ואכ\"מ.</p>\n<h4><i><b>ח'תתכט</b></i></h4>\n<p>נדפסה בס' בדבר מלך על הרמב\"ם ח\"א בתחלתו. חלקה ובשינויים - בלקו\"ש ח\"ד ע' 1346 הערה 6 - 24. הל' בית הבחירה להרמב\"ם עם חידושים וביאורים (קה\"ת תש\"נ) ע' נג ואילך. לקו\"ש חי\"א ע' 248. ונעתקו כאן הערות המו\"ל שבנספחים שם ע' רכו.</p>\n<p><b>הרב יצחק שי':</b> רייטפארט, ברוקלין.</p>\n<p><b>והארכתי בכ\"ז במק\"א:</b> ראה גם לקו\"ש חי\"א ע' 116. וראה לקו\"ש ח\"ז ע' 200 הערה 20.</p>\n<p>חט\"ז ע' 438 ואילך. חכ\"ו ע' 177. ועוד (אבל בפשטות אין הכוונה בה\"מק\"א\" לזה).</p>\n<p><b>מדברי הרמב\"ם עצמו:</b> וראה לקו\"ש חי\"א ע' 137 הערה 17 שמביא דעת הרמב\"ם (הל' כלי המקדש פ\"י הי\"א) בפירוש \"(כלפי) שכינה\" שביומא עג, א - שהכוונה להארון, ע\"ש.</p>\n<p>וראה לקו\"ש חכ\"ח ע' 64 הערה 31 שמביא שבמגילה כא, ב: ונר מערבי כלפי שכינה, וברמב\"ם הל' ביהב\"ח פ\"ג ה\"ה: וזה הנר האמצעי (\"והוא הנקרא נר מערבי\" - רמב\"ם שם) פניו כנגד קדש הקדשים.</p>\n<p><b>דביהמ\"ק בקדושתו:</b> הכוונה לזה שביהמ\"ק נשאר בקדושתו - בתור בית בנוי; משא\"כ זה ש\"מקריבין כו' אע\"פ שאין שם בית בנוי כו'\" (רמב\"ם שבפנים) שונה לגמרי מדין ביהמ\"ק בנוי, כמבואר באחרונים. וראה הגש\"פ עך לקוטי טעמים מנהגים וביאורים - הוצאת תשנ\"א ח\"ב ע' תרפא הערה ד\"ה חיוב (ואכ\"מ).</p>\n<p><b>שנגנז.. שניטל:</b> שנגנז ע\"י יאשיהו בזמן בית ראשון - למ\"ד הכי; ויש מ\"ד שניטל - (בעת חורבן בית ראשון לבבל ושוב לא חזר) היינו בבית שני. - ראה לקו\"ש חכ\"א ע' 156 ואילך.</p>\n<p>וש\"נ.</p>\n<p><b>לאחר שנגנז (ואפילו לאחר שניטל):</b> ראה לקמן בפנים שכשהארון גנוז בביהמ\"ק זה מוסיף בקדושת ביהמ\"ק.</p>\n<p><b>כי הוא לפי ש\"שכינה אינה בטילה\":</b> לכאורה הכוונה (ראה לעיל \"דביהמ\"ק בקדושתו\"): כשם שמטעם ששכינה אינה בטילה מקריבין אע\"פ שאין בית, כך גם בנוגע להשראת השכינה המיוחדת המתוספת ע\"י שהארון במקומו, ושלימות קדושת המקדש שעי\"ז - שאי\"ז בטל ע\"י גניזת הארון ואפילו ע\"י נטילתו (וראה פי' הרי\"פ פערלא דלקמן בפנים (קצט, ג-ד)).</p>\n<p><b>דביהמ\"ק.. המשכן.. \"לפי שעה\".. דירת עראי.. מנוחה ונחלה:</b> שהמשכן גם קדושתו היא עראית, וביהמ\"ק קדושתו נצחית, זאת מנוחתי עדי עד, ושוב לא שרתה שכינה במק\"א. ראה מו\"ק (ט, א): משכן שאין קדושתו קדושת עולם.. מקדש שקדושתו קדושת עולם. ועוד. וראה בזה לקו\"ש חי\"א ע' 177. 182. חט\"ז ע' 305 הערה 52. חכ\"ט ע' 73. חט\"ז ע' 466 ואילך. חכ\"ד ע' 79 ואילך. וש\"נ. ושם ציין ג\"כ לפירוש הרי\"פ פערלא לסהמ\"צ לרס\"ג מ\"ע פד-פה. ועוד. - ולכן גם הקדושה שנפעלת ע\"י הארון, בביהמ\"ק היא נצחית; משא\"כ במשכן, שאין בו קדושה זו אלא כשהארון נמצא בו.</p>\n<p><b>שמנה משאו בכתף:</b> סהמ\"צ מ\"ע לד. הל' כלי המקדש פ\"ב הי\"ב.</p>\n<p><b>הארון ענינו רק כלי שיהי' ל\"ושכנתי בתוכם\":</b> ראה לקמן ע' ר.</p>\n<p><b>ענינים.. ההקרבה וכו':</b> לכאורה הכוונה ב\"ענינים\" לשון רבים וב\"וכו'\" ל\"וחוגגין כו'\" שבריש הל' בית הבחירה ועד\"ז בסהמ\"צ שורש יב ומ\"ע כ' (וראה ג\"כ לקו\"ש חי\"ב ע' 59 הערה 16. ועוד).</p>\n<p><b>והם הם שנמנו:</b> כנ\"ל בפנים, שהרמב\"ם מדבר בענין המצות שנצטוו בנ\"י לעשות בביה\"ב, ואת זה מנה במנין המצות (וראה לקו\"ש חי\"א ע' 124 שאין הקרבת הקרבנות ושאר העבודות שבביהמ\"ק שייכים לענין השראת שכינה כו'. ע\"ש).</p>\n<p><b>נתינת הלוחות.. לפי' זה:</b> משא\"כ לפי' המנ\"ח מצוה צה, וז\"ל: עיקר עשיית הארון כדי שיהיו הלוחות מוחים בתוכו, כמבואר בפ' תרומה (כה, טז) ונתת אל הארון כו' את העדות, ובפסוק מלכים (א' ח, ט) אין בארון רק שני לוחות העדות.. ובבית ראשון שנגנז ארון עם העדות בימי יאשי' המלך ע\"ה לא עשו עוד ארון ובבית שני לא הי' הארון, כי למה צריך הארון, כיון שנגנזו הלוחות גם כן אין מצוה לעשות ארון, והארון אינו מעכב אף שהוא מדיני המצוה להר\"מ מכל מקום יש הרבה דיני המצות שאין מעכבין בדיעבד. ובקנאת סופרים לסהמ\"צ (בשורש יוד ובמ\"ע לג) כתב עד\"ז לדעת הרמב\"ם. וראה לקו\"ש חכ\"ו ע' 177. רי\"פ פערלא שם (קצט, ב-ג). אנציקלופדי' תלמודית ערך ארון בסופו.</p>\n<p><b>נתינת הלוחות.. פרט מעניני.. הארון:</b> שלדעת המנ\"ח והקנאת סופרים ועוד (כנ\"ל בציון הקודם) תכלית עשיית הארון הוא לשם הלוחות - נתינת הלוחות בתוכו (אלא שמקומו של הארון הוא בקודש הקדשים), משא\"כ לפירוש המבואר כאן, הוא להיפך, שהלוחות ניתנו בארון לא לצורך הלוחות, אלא לשם קדושת הארון, והענין בעשיית הארון הוא אך ורק להיות כלי להשראת השכינה, ונתינת הלוחות בו אינו אפילו ענין נוסף בעשיית הארון. - וההכרח בזה הוא, שאם נאמר שבנוסף לזה שהארון הוא כלי להשראת השכינה יש בו גם הענין של נתינת הלוחות (בתור ענין בפני עצמו) - הי' צריך למנותו במנין המצות מחמת ה\"מעשה המיוחד\" הזה, בדוגמת בנין ביהב\"ח שנמנה במנין המצות מחמת הענינים דהקרבה וכו', כנ\"ל, ובדוגמת המ\"ע דמשא בכתף ומל\"ת דלא יסורו דלקמן בפנים.</p>\n<p><b>ומל\"ת דלא יסורו:</b> סהמ\"צ מל\"ת פו. הל' כלי המקדש פ\"ב הי\"ג.</p>\n<p><b>ציווי.. לכהנים:</b> כ\"ה דעת הרמב\"ם (ולהרמב\"ן הציווי הוא על הלויים) - ראה לקו\"ש חכ\"א ע' 160 הערה 35. חי\"ח ע' 194 הערה 71. חי\"ט ע' 316. חכ\"ח ע' 49 ואילך. וש\"נ.</p>\n<p><b>אבל פי' זה.. דוחק הוא:</b> לפי' הא' הנ\"ל, אפילו אם יש ציווי על \"מעשה מיוחד\", שאין אנו יודעים עליו משאר המצות, אלא שענין הציווי כולל את התורה והמצות כולן - אינה נמנה במנין המצות. וע\"ז כתב כאן שהוא דוחק. כי מה בכך שענינו כולל, אבל המעשה שעליו נצטוינו אין אנו יודעים אותו משאר המצות. והרי הטעם שאין ציווי כולל נמנה הוא מפני \"כי לא צוה לעשות זולת מה שידענו\" כבר משאר המצות. וא\"כ כשהמעשה הוא מיוחד, כבנדו\"ד, אף שענינו כולל, יש למנותו במנין המצות (ולפי' הא' שג\"ז כולל בשורש הד' - יש לתרץ זה אבל בדוחק. ואכ\"מ). - וראה לקו\"ש ח\"ד ע' 1131. ע' 45 - 1144 הערה 5.</p>\n<p>ע\"ש.</p>\n<p><b>ממ\"ע דאמונת ה' דמונה הרמב\"ם:</b> סהמ\"צ מ\"ע א. ריש הל' יסוה\"ת.</p>\n<p><b>א) למה השמיט.. דיני עשיית הארון?:</b> ראה לקו\"ש חי\"א ע' 118 הערה 24.</p>\n<p><b>ממקומו שנצטוו כו':</b> תרומה כו, לג.</p>\n<p><b>מוכיח דקראי כפשוטם:</b> היינו, שאי\"ז שלומדים דין חדש ממעשה יאשיהו, אלא גילוי מילתא בעלמא הוא (ראה ב\"ק ב, ב) שהפירוש בהכתובים שבהם הציווי על עשיית הארון, הוא כפשוטם.</p>\n<p><b>דקראי:</b> בתרומה כה, י ואילך: ועשו ארון עצי שטים וגו' ונתת אל הארון את הלוחות אשר אתן אליך.. ואל הארון תתן את העדות אשר אתן אליך, ונועדתי לך שם גו'.</p>\n<p><b>ולאחרי שיתגלה לעת\"ל:</b> ראה רמב\"ן בהשגותיו לסהמ\"צ שורש ג, מ\"ע לג, ועוד.</p>\n<p><b>ולכן לא נמנית.. במצוה (לדורות):</b> כמבואר בסהמ\"צ שורש ג, שמצוה שאינה נוהגת לדורות אינה נמנית במנין המצות.</p>\n<p><b>לא הובאו.. מאי דהוי הוי:</b> ראה יומא ה, ב (והתירוץ שם \"למיסבר קראי\" - אינו שייך לס' היד שענינו רק \"הלכות הלכות\", כידוע וכמבואר כמ\"פ בספר זה ובכ\"מ).</p>\n<p><b>דבמלחמות פלשתים כו':</b> והרי גם בזה הי' מקום לדאגה שמא ישבוהו פלשתים, וכמו שהי' בפועל - ראה שמואל א ד (ואילך).</p>\n<p><b>נטילת הארון ממקומו כו':</b> וראה לקו\"ש ח\"ט ע' 198 הערה 17, וז\"ל: וביהושע (כד, כו) שהביאו הארון לשכם (וכ\"פ ברד\"ק שם כד, א). אבל לכאורה פי' שבאותו מאורע הובא (ע\"פ הוראת שעה) הארון לשכם ולא דמלכתילה הובא לשכם (וצע\"ג פי' התפא\"י שם סקל\"ח דמלכתחילה הובא - דאיך יפרנס העבודה ביוהכ\"פ וכו'. ועוד ועיקר התמי' לומר דבמשך עשיריות בשנים הי' כל המשכן וכליו במקום אחד והארון במק\"א! - שוב ראיתי בתפארת יעקב שם העיר בדברי התפא\"י) ואכ\"מ.</p>\n<p><b>ש\"א ו, יט:</b> (ואילך) ויך באנשי בית שמש כי ראו בארון ה' ויך בעם שבעים איש חמשים אלף איש.. ויאמרו אנשי בית שמש מי יוכל לעמוד לפני ה' האלקים הקדוש הזה.. וישלחו מלאכים אל יושבי קרית יערים לאמר השיבו פלשתים את ארון ה' רדו העלו אותו אליכם.</p>\n<p>ויבאו אנשי קרית יערים ויעלו את ארון ה'.. ויהי מיום שבת הארון בקרית יערים וירבו הימים ויהיו עשרים שנה גו'. - וראה סוטה לה, סע\"א ואילך. ועוד.</p>\n<p><b>וכמה דוגמאות לזה:</b> ראה לקו\"ש ח\"ח ע' 63 הערה 12*, וז\"ל: ידועה השו\"ט בגדרי החיוב להכין מכשירי מצוה וכיו\"ב, לפני זמן חיוב קיום המצוה - ראה שו\"ע אדה\"ז או\"ח סרמ\"ח סי\"ג, שלפי דעה א' מותר לצאת בשיירא קודם ג' ימים לפני השבת, גם כשיודע בבירור גמור שבודאי יצטרך לחלל שבת אח\"כ (והטעם: כי ג' ימים הראשונים שבשבוע אינם מתייחסים לשבת הבא - שם סעיף ה'); וגם לפי דעה השני' שם שיש איסור בזה (וכן האיסור בג' ימים שלפני השבת - לד\"ה), האיסור הוא רק מד\"ס. וראה שד\"ח אס\"ד מע' יו\"כ סי' א' סק\"י - שקו\"ט אם מותר (וצריך) להתענות בצום גדלי', באם א\"א יהי' לו עי\"ז להתענות ביו\"כ שלאחריו. ושם (ד\"ה אמנם נראה), שגם לדעה השני' הנ\"ל מותר להתענות.</p>\n<p>וראה לקו\"ש ח\"ג ע' 1000 הערה 22. עיי\"ש.</p>\n<p><b>עפ\"י הנ\"ל.. ועצ\"ע:</b> ב' קטעים אלו נתוספו בהלכות בית הבחירה שם מלקו\"ש ח\"ד ע' 1346 הערה 25. ולהשלמת הענין נעתקו כאן.</p>\n<p><b>ההזי' על בין הבדים וכו':</b> לכאורה הכוונה ב\"וכו'\" הוא לההזיות שעל הפרוכת (משנה זבחים מז, א) - ולהעיר שההזיות על בין הבדים ועל הפרוכת ועל מזבח הזהב מעכבות זו את זו (מנחות כז, א. רמב\"ם הל' פסוהמ\"ק פ\"ב ה\"ג).</p>\n<p><b>בנוב וגבעון.. ונוב וגבעון יוכיחו:</b> הא דלא נקט ג\"כ גלגל, שגם שם לא הי' הארון קבוע, י\"ל: א) שיגרא דלישנא נקט, שכ\"ה בכ\"מ בגמרא וראשונים. ב) אין להקשות איך הי' בגלגל, כי אז עשה יהושע עפ\"י הדיבור (תוס' עירובין סג, ב ד\"ה ע\"ש). ג) ועיקר: אם כי בגלגל לא הי' הארון קבוע (כלשון המאירי הנ\"ל) מפני שהי' יוצא אתם למלחמה אבל יתכן (ומסתבר לכאו') שבין מלחמה למלחמה החזירוהו לאהל מועד (חוץ מבהוראת שעה - ראה המובא לעיל בפיענוח \"נטילת הארון ממקומו כו'\"). וא\"כ - ביוה\"כ הי' הארון במקומו.</p>\n<p><b>שהעיקר בזה מקום (בדי) הארון:</b> היינו שאין הארון סיבה להזאות שבין הבדין שלו, אלא רק סימן בלבד על המקום שבו צריך להזות. ונמצא שאין שום עבודה בהארון כלל.</p>\n<p><b>ועצ\"ע:</b> אולי - מפני שזה שבנוב וגבעון לא הוחזר הארון למשכן - הי' מטעם פיקו\"נ, כנ\"ל.</p>\n<p>וראה הנסמן בנספחים להלכות בית הבחירה סימן א הערה 50.</p>"],[1200970155,"ח'תתל\n\n<p>ב\"ה, ראש חודש סיון, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>צו אלע אנטיילנעמער אין דעם יערלעכן<br>\nדינער פון ישיבת<br>\n\"אחי תמימים\" ליובאוויטש, אין נוארק,<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>נעמענדיק אין אכט, אז דער יערלעכער דינער קומט פאר אין דעם חודש פון מתן-תורה, געציילטע טעג נאך דעם יום-טוב פון קבלת התורה, וועט יעדער איינער און איינע זיכער ברענגען צום אויסדרוק די גייסטיקע דערהויבונג פון דעם יום-טוב און די פראקטישע אנווייזונגען וואס דארפן דורכגעפירט ווערן, ספעציעל אין צוזאמענהאנג מיט דער דערמאנטער יערלעכער אונטערנעמונג.</p>\n<p>עס איז כדאי צו באמערקן, אז דער יום-טוב שבועות האט ניט קיין אייגענעם \"דאטום\" (ניט קיין חודש און ניט קיין טאג) אין דער תורה, ווי אנדערע ימים-טובים, נאר ווערט פארצייכנט אלס דער \"50'טער טאג\" פון ספירה, וואס מיר הויבן אן צו ציילן דעם צווייטן טאג פסח, אויף מארגן נאך \"יציאת מצרים\".</p>\n<p>דערמיט אונטערשטרייכט די תורה הק', אז שבועות איז דער ענד-ציל פון דעם יום-טוב פסח; אז <b>זמן מתן תורתנו</b> איז די פארפולקאמונג פון <b>זמן חרותנו</b> - אז די אמת'ע און פולשטענדיקע באפרייאונג, סיי פון דעם יחיד און סיי פון דעם כלל, סיי מאטעריעל און סיי גייסטיק, קען דערגרייכט ווערן בלויז דורך <b>קבלת התורה.</b></p>\n<p>מיר לעבן אין א צייט, און אין א לאנד, וואס ניט קוקנדיק אויף דער אויסערלעכער \"פרייהייט\" איז די וועלט בכלל, און דער יונגער דור בפרט, נאך גאנץ שטארק פארשקלאפט, און ווייס ניט ווי צו באפרייען זיך פון די קייטן פון גייסטיקער צערודערונג. די איינציקע האפנונג אז אידישע קינדער זאלן ניט מיטגעשלעפט ווערן מיטן שטראם ליגט אין א תורה-טרייען ישיבה-חינוך, וואו די גאלדענע קייט פון תורה מסיני ווערט אנגעהאלטן; די תורה הק', <b>תורת אמת,</b> וואס דער אמת מוז שטענדיק בלייבן גאנץ, אן פשרות און אן פארוואסערונג.</p>\n<p>די ליובאוויטשער ישיבה \"אחי תמימים\" אין נוארק איז א וויכטיקע תורה-פעסטונג, וואס פארדינט די פולסטע שטיצע. ס'איז א גרויסע פליכט און זעלטענער זכות פאר יעדן איינעם און איינער צו שטיצן די דאזיקע ישיבה. איך באגריס אלע אנטיילנעמער אין דעם יערלעכן דינער און שיק יעדער איינעם און איינער פון די שטיצער און פריינט פון דער ישיבה א הארציקע ברכה, אז השם יתברך זאל זיי באגליקן אין דער ישיבה אונטערנעמנוג, און אין זייערע פערזענלעכע אונטערנעמונגען, און אין אלעס וואס מען נויטיקט זיך, מאטעריעל און גייסטיק.</p>\n<p>בברכה להצלחה ולקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ח'תתל</b></i></h4>\n<p>חלקה נדפס בלקו\"ש ח\"ח ע' 262 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>שבועות.. ספירה:</b> ראה גם לעיל ח\"א אגרת עד.</p>"],[1200970156,"ח'תתלא\n\n<p>ב\"ה, ראש חודש סיון, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>מר יוסף שי' דקל</p>\n<p>שלום וברכה!</p>\n<p>מאשר אני קבלת מכתב כ', וכן הספר \"מלחמה גרעינית ושלום גרעיני\" ליהושפט הרכבי. תודה על העבר וגם על להבא, שבטח ימשיך בכגון דא.</p>\n<p>כמנהג בני ישראל למצוא רמזים בתורה על כל ענין ופרט, ובעמדנו ימים ספורים לפני זמן מתן תורתנו, הרי ענין התורה הוא לזכך את החומר והגשם עד שיתגלו הכחות הצפונים בהם, ועד למקור הראשון הוא כח הפועל בנפעל, אשר בדברו שמים נעשו וברוח פיו כל צבאם. שמזה מובן מה גדלו כחות-עד שיש בכל דבר וענין, אלא שצריך לחדור לפנימיות החומר לגלות, כאמור, את הצפון בתוך תוכו ופנימיותו.</p>\n<p>והנה המדע מתחיל לגלות את זה בחומר כפשוטו, שזהו מנקודות החקירה בשטח המדע הגרעיני, ומשלב לשלב וממדרגה למדרגה מתעמקת החקירה גם בנוגע לבני אדם ועניניהם, אשר בסגנון חכמינו ז\"ל כל אחד עולם מלא הוא, ובפרט שישליט הפנימיות על החיצוניות, הצורה על החומר, והרוחניות האמתית על הלבושים והקליפות המכסים עלי', עד שכל פרט שבבריאה, ועל אחת כמה וכמה כללות הבריאה, יכריזו אנכי ה' אלקיך, ה' הוא האלקים אין עוד מלבדו.</p>\n<p>בכבוד ובברכת מועדים לשמחה ולקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ח'תתלא</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ג ע' 231 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מר יוסף דקל:</b> אגרות נוספות אליו - לעיל ח'תרצט, ובהנסמן בהערות שם.</p>\n<p><b>בסגנון חכמינו:</b> סנהדרין לז, א.</p>"],[1200970157,"ח'תתלב\n\n<p>ב\"ה, ר\"ח סיון, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>בעמדנו בריש ירחא תליתאי בו יהב אוריאן תליתאי לעם תליתאי ע\"י תליתאי ביום תליתאי.</p>\n<p>אשר מעניני מתן תורה ונקודתו העיקרית הוא ביטול הגזירה וההבדלה שבין עליונים ותחתונים, ולא עוד אלא שאני (הקב\"ה) המתחיל, היינו שביטול זה התחלתו מצד העליון, שאז אין כל הגבלה בזה ועד שאפשר להיות התאחדות גמורה.</p>\n<p>יהי רצון שיעשה כאו\"א כל התלוי בו בזה בנוגע לעליון ותחתון אשר בכל הענינים - הן הרוחנים והן הגשמים, הן הפרטים והן הכללים.</p>\n<p>מתחיל מדרגות אלו כמו שהן בתורה (סתים וגליא דאורייתא) ועד לתחתון הגשמי והחומרי ממש שאין תחתון למטה ממנו ונפש וחיות רוחנית אשר בו מדבר ה'.</p>\n<p>ועשי' ועבודה זו מביאים קיום היעוד: ונגלה כבוד ה' וראו כל בשר יחדיו כי פי ה' דבר.</p>\n<p>בברכה - בלשון הרב הוא כ\"ק מו\"ח אדמו\"ר - לקבלת התורה בשמחה ובפנימיות,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתלב</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש חי\"ג ע' 156 (בתאריך ג' סיון) והושלמה עפ\"י צילום האגרת.</p>\n<p><b>ר\"ח סיון: </b>ראה שבת (פו, ב). תו\"א ר\"פ יתרו.</p>\n<p><b>ירחא.. ביום תליתאי: </b>כרבנן (שבת פח, א) וכן הלכה (שו\"ע אדה\"ז ר\"ס תצד).</p>\n<p><b>תליתאי: </b>ראה פי' ר\"נ גאון (שבת שם).</p>\n<p><b>ביטול הגזירה.. המתחיל: </b>שמו\"ר פי\"ב, ג.</p>\n<p><b>סתים וגליא דאורייתא: </b>שהם דרגא ע\"ג דרגא (זח\"ג עג, א).</p>\n<p><b>הגשמי.. למטה ממנו: </b>ראה תניא פל\"ו.</p>\n<p><b>ונפש.. מדבר ה': </b>שער היחוה\"א פ\"א.</p>\n<p><b>ונגלה.. דבר: </b>גילוי בלי שום לבוש, יראו בראי' חושיית, פי ה' דבר ומהווה כל הנבראים (ראה תניא ושהיחוה\"א שם).</p>"],[1200970158,"ח'תתלג\n\n<p>ב\"ה, ריש ירחא תליתאי, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד הוו\"ח אי\"א נו\"מ בחור מעם ומורם<br>\nמעם ודורש טוב<br>\nלעמו בעל מדות תרומיות ענף עץ אבות<br>\nמו\"ה שניאור זלמן<br>\nשליט\"א</p>\n<p>שלום וברכה!</p>\n<p>לקראת חג השבועות, זמן מתן תורתנו, הבא עלינו ועל כל ישראל לטובה ולברכה, הנני להביע ברכתי לכ', בסגנון הרב הוא כ\"ק מו\"ח אדמו\"ר - לקבלת התורה בשמחה ובפנימיות.</p>\n<p>כבר מובא בכמה ספרים, אשר עשרת הדברות חובקות כל סדר ההשתלשלות, וגם מה שלמעלה מההשתלשלות, ועד למטה מטה - ובסגנון רבנו הזקן בתניא קדישא - שאין תחתון הימנו. שלכן <b>התחלת</b> עשרת הדברות היא: אנכי הוי' אלקיך אשר הוצאתיך מארץ מצרים, בסדר מלמעלה למטה, שארץ מצרים הרי היא למטה באין ערוך אל \"אלקיך\", להבדיל, אלקות כמו שהוא מלובש בטבע (אלקים בגימ' הטבע), ועל דרך זה האין ערוך בין \"אלקיך\" ו\"הוי\" שם העצם, ועד\"ז האין ערוך בין הוי' ל\"אנכי\", כלשון הזהר, אנכי - מי שאנכי, דלא איתרמיז לא בשום אות ואפי' לא בשום קוץ.</p>\n<p><b>וסופן</b> של עשרת הדברות עמקי שאול ששם זקוקים לאזהרה לא תרצח וגו', אזהרה לבעל בחירה שניתנה לו היכולת דבחירה חפשית, ולמטה מטה עד - בסגנון חכמינו ז\"ל - אפילו יתוש קדמך (עיין תניא פ' כ\"ד).</p>\n<p>וכל האמור ניתן בבת אחת, וכמו שהדגישו חכמינו ז\"ל האחדות דעשרת הדברות דכולם ניתנו בדיבור אחד ובבת אחת. וזאת התורה - הוראה - שהצורה והחומר, הרוחניות והגשמיות, רק למראה עיני בשר נפרדים הם, ועד שאפשר שיהיו מנגדים זה לזה, ועד למלחמה זה בזה. ותפקיד האדם - אתם קרויים אדם - להתחיל מהגברת הצורה על החומר, הרוח על הגשם וכולי, ועד להתאחדות ואחדות ויחוד עד תכליתו, - שכל הפרט שבבריאה, ועל אחת כמה וכמה כללות הבריאה, תכריז אנכי הוי' אלקיך גו' לא יהי' לך, כמו שהי' בעת מתן תורה, ועד להכרה שאין עוד מלבדו.</p>\n<p>בהוקרה ובכבוד ובברכת מועדים לשמחה ולהמשיך משמחת ופנימיות קבלת התורה בכל ימי השנה.</p>\n<h4><i><b>ח'תתלג</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ג ע' 159 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מו\"ה שניאור זלמן:</b> שזר. אגרות נוספות אליו - לעיל ח'תרפב, ובהנסמן בהערות שם.</p>\n<p><b>בסגנון.. קדישא:</b> פל\"ו.</p>\n<p><b>אלקים.. הטבע:</b> פרד\"ס שי\"ב פ\"ב. וראה סה\"מ מלוקט ח\"ב ע' צג הערה 76. וש\"נ.</p>\n<p><b>כלשון הזהר:</b> ח\"ג רנז, ב. וראה לקו\"ת פנחס פ, ב.</p>\n<p><b>בסגנון חכמינו:</b> סנהדרין לח, א.</p>\n<p><b>שהדגישו חכמינו:</b> מכילתא ופרש\"י יתרו כ, א.</p>\n<p><b>אתם קרויים אדם:</b> יבמות סא, א.</p>"],[1200970159,"ח'תתלד\n\n<p><i>[נוסח המברק לקראת חג השבועות תשכ\"ד]</i></p>\n<p>שבתא ויומא טבא וקבלת התורה בשמחה ובפנימיות.</p>\n<p><b>/מקום החתימה/</b></p>\n<h4><i><b>ח'תתלד</b></i></h4>\n<p>נדפס בלקו\"ש חכ\"ג ע' 346.</p>"],[1200970160,"ח'תתלה\n\n<p>ב\"ה, י' סיון, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>[שלום וברכה!]</p>\n<p>בצער נודעתי מאבדתם, ונוסף על השתתפותי בצערו, נא למסור לבתו והמשפחה שי' אף כי בלתי מכירם ברכת תנחומים - המקום ינחם אותם בתוך שאר אבלי ציון וירושלים.</p>\n<p>אופייני הוא הנוסח האמור המקובל והמסורתי, שיש לדייק בו שתי נקודות: א) בנוגע לעצם הצער, שמקשר את צער היחיד עם צער הכלל, זאת אומרת שכמו שחורבן ציון וירושלים הוא אבל כל העם כולו, כן הוא אבל היחיד, באשר כל עם ישראל הוא קומה אחת, שלכן נקל יותר לשאת את הצער והיגון. ב) ובנוגע הנחמה, הרי כמו שודאית נחמת ציון וירושלים והיא מיסודי אמונתנו, עד שאמרו שכל המתאבל על ירושלים זוכה לראות בנחמתה שמחתה, כן הוא ענין האבלות שמטרתה ותכליתה ענין התשובה (רמב\"ם הל' אבל סוף פ' י\"ג) שהנחמה ודאי שתבוא ממנחם ציון ובונה ירושלים.</p>\n<p>בכבוד.</p>\n<h4><i><b>ח'תתלה</b></i></h4>\n<p><b>הנוסח:</b> ראה גם לעיל חכ\"ב אגרת ח'תעה. לקו\"ש ח\"י ע' 210.</p>\n<p><b>כל.. אחת:</b> ראה גם לעיל אגרת ח'תתכד, ובהנסמן בהערות שם.</p>\n<p><b>שכל המתאבל:</b> תענית ל, ב. וש\"נ.</p>"],[1200970161,"ח'תתלו\n\n<p>ב\"ה, ערב שבת-קדש לסדר על פי ה' יחנו</p><p>ברוקלין, נ.י.</p><p>ועל פי ה' יסעו גו', תשכ\"ד<br>\nצו דער יערלעכער קאנווענשאן פון נשי<br>\nובנות חב\"ד<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>צווישן די הויכפונקטן פון דער היינטיקער סדרה, פ' בהעלותך, איז די באשרייבונג פון דעם סדר ווי די אידן האבן געוואנדערט אין מדבר. \"אויף דעם באפעל פון השי\"ת האבן זיי גערוט, און אויף דעם באפעל פון השי\"ת האבן זיי גערייזט; די ג-טלעכע אפהיטונג האבן זיי געהיט, אויף דעם באפעל פון השי\"ת דורך משה\" (בהעלותך ט, כג).</p>\n<p>אויף אלע וואנדערונגען איז דער ארון ברית ה' געגאנגען פארויס אויסצוזוכן פאר זיי א מקום מנוחה (י, לג).</p>\n<p>די תורה הק' - וואס די תורה איז אן אייביקע און אירע אנווייזונגען זיינען אייביקע און גילטיק אומעטום און אין אלע צייטן - שטרייכט אונטער, אז בלויז נאכפאלגנדיק דעם ארון הקדש, די תורה הק', האבן אידן געקענט געניסן מנוחה און זיין געשיצט אין דעם שרעקלעכן מדבר פול מיט גיפטיקע מזיקים. און אזוי איז עס שטענדיק געווען אין דער לאנגער גלות-געשיכטע פון אונזער פאלק און אין די אלע וואנדערונגען וואס מיר אידן האבן דורכגעמאכט און מאכן דורך, ביז עס וועט קומען די אמת'ע מנוחה און גאולה שלימה על ידי משיח צדקנו.</p>\n<p>און ווי אין אלע וויכטיקע מאמענטן פון אידישן לעבן, אזוי אויך, און ספעציעל, אין א צייט פון וואנדערונג, פארנעמט די אידישע פרוי א צענטראלן ארט. דאס ווערט אנגעדייטעט ביים אפשלוס פון דער זעלבער סדרה, וואו די תורה דערציילט, אז דאס פאלק האט געווארט אויף מרים'ען און האט זיך ניט גערירט פון ארט אן איר. בשעת דאס פאלק געפינט זיך אין וועג, איז ניט גענוג אז משה און אהרן זאלן מיטגיין; מרים דארף אויך מיטגיין. אן מרים'ען פארט מען ניט! אונזערע חכמים זכרונם לברכה דערקלערן, אז מרים האט פארדינט דעם כבוד אז דאס גאנצע פאלק, מיט דעם ארון הקדש און מיט ענני הכבוד וכו' זאלן ווארטן אויף איר, דערפאר וואס זי האט געווארט און געראטעוועט משה רבינו בשעת ער האט זיך געפונען אין א קעסטעלע אויפן טייך.</p>\n<p>מיר געפינען זיך אין א צייט ווען אן דער אקטיווער מיטהילף און מיטארבעט פון דער אידישער פרוי צו פארשטארקן און פארשפרייטן תורה ומצוות אין טאג-טעגלעכן לעבן, קען אונזער פאלק ניט גיין פאראויס אל המנוחה ואל הנחלה וואס דער אויבערשטער האט אונז צוגעזאגט. אין אלע געביטן פון אידישן לעבן, ספעציעל אין דעם געביט פון חינוך על טהרת הקדש, מוזן די אידישע פרויען און טעכטער דערפילן די אויפגאבע וואס די השגחה עליונה האט אויף זיי ארויפגעלעגט. דאס איז די פליכט פון <b>אלע</b> אידישע פרויען און טעכטער, ספעציעל פון די <b>נשי ובנות חב\"ד</b> וואס האבן זוכה געווען צו שטיין אונטער דער באלייכטונג און אויפלעבונג פון תורת חב\"ד און נשיאי חב\"ד.</p>\n<p>ואני תפילתי, אז די קאנווענשאן זאל דערפילן אלע דערווארטונגען און זאל מצליח זיין צו פארווירקלעכן בפועל ממש דאס וואס עס דארף אפגעטאן ווערן פון דער קאנווענשאן בכלל, און פון יעדער מיטגלידערין פון נשי ובנות חב\"ד בפרט.</p>\n<p>בברכה להצלחה מופלגה בעניני הפרט והכלל,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתלו</b></i></h4>\n<p>נדפסה בלקו\"ש ח\"ח ע' 287 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>אונזערע חכמים:</b> סוטה ט, ב.</p>"],[1200970162,"ח'תתלז\n\n<p>ב\"ה, מוצש\"ק פרשת בהעלותך, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו במוצש\"ק פרשת בהעלותך את הנרות, י\"ל ברמזי פרשה זו: ביאר רבנו הזקן אשר הנרות הללו - הן נשמות כל בני ישראל, נר ה' נשמת אדם, אתם קרוים אדם, ובכל אחד ואחד ההדלקה היא באופן של \"בהעלותך\" - היינו שסוף סוף השלהבת עולה מאלי'.</p>\n<p>וכיון שהדרישה מופנית לכל אחד ואחד, בודאי שבכחו הוא, שהרי אין הקב\"ה בא בטרוניא עם בריותיו.</p>\n<p>והתכלית בזה - אל מול פני המנורה יאירו שבעת הנרות, שכל אחד ואחד איך שלא תהי' תחלת קיומו את התורה ואת המצות באחת הדרגות דשלא לשמה - מתוכה בא לשמה.</p>\n<p>ואפילו זה הנקרא נדח, שהוא עוד למטה יותר מזה הנקרא רחוק כמובן, הרי הובטח כי לא ידח ממנו נדח, כפסק הדין בפנימיות התורה ועד לפסק דין גלוי בנגלה דתורה.</p>\n<p>ויהי רצון שיעשה כל אחד ואחד ככל האמור בנוגע לכל עניניו, אשר יאירו אל מול פני המנורה ואפילו אלה שלעת עתה הם בבחי' נדח, ויעשה זה ברעותא דלבא, אופן עבודת אהרן, ובחי' אהרן שבכל אחד, שהרי אהרן הוא משבעה הרועים, ועד לאופן שעד ירכה עד פרחה מקשה היא,</p>\n<p>שירכה - הכי תחתון שבו ופרחה - הכי עליון שבו, יהי' מקשה אחת זהב טהור.</p>\n<p>בברכה לבשו\"ט</p>\n<p><b>מ. שניאורסאהן</b></p><p>* * *</p>\n<p>בברכה לבשו\"ט וגם בענין האנציקלופדיא תל' <b>גם</b> לא להיותו טפל ח\"ו, כ\"א - להיותו <b>אדרבא</b> רבותא וגדלות יותר (כי במחכ\"ת בכבדות הכי גדולה יו\"ל) - ועפ\"ז מתורץ \" <b>גם</b> עלה\" [והדרש <b>דגם</b> זה פי' גלות בבל - כנראה לא ס\"ל לאדה\"ז (תו\"א ר\"פ שמות) וראה רש\"י שבת (פט, ב)] משא\"כ <b>את</b> - אשר לעולם טפל הוא.</p>\n<h4><i><b>ח'תתלז</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ח ע' 285 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>אתם.. אדם:</b> יבמות סא, א.</p>\n<p><b>אין הקב\"ה:</b> ע\"ז ג, א.</p>\n<p><b>בברכה.. הוא:</b> קטע זה למוהש\"י זוין. אגרות נוספות אליו - לעיל ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>והדרש:</b> הובא בתורה שלמה עה\"פ ויגש מו, ד (סל\"ד).</p>\n<p><b>ביאר רבנו הזקן: </b>לקו\"ת בהעלותך.</p>\n<p><b>בהעלותך.. מאלי': </b>פירש\"י כאן. וראה שבת כא, א.</p>\n<p><b>פני המנורה: </b>פנימיות ורצון כללות נש\"י הנקרא מנורה (ראה לקו\"ת שם אות א', ו' (בסופו)).</p>\n<p><b>באחת הדרגות: </b>ראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ג.</p>\n<p><b>בא לשמה: </b>ראה תניא ספמ\"א: יחוד נפשו כו' חפץ כל אדם מישראל כו' (ולפני זה) לשם יחוד קוב\"ה ושכינתי' כו' מעט מזעיר חפץ לבו בזה <b>באמת.</b> <b>נדח.. רחוק: </b>להעיר מב' עניני התשובה: על עבירות שבידו, להשיב נפשו מירידתה למקורה (לקו\"ת דברים סו, ג. ובכ\"מ).</p>\n<p><b>כפסק דין: </b>תניא ספל\"ט. הל' ת\"ת שם.</p>\n<p><b>אופן עבודת אהרן: </b>ראה לקו\"ת ואתחנן ח, ב. זח\"ג לט, א.</p>\n<p><b>משבעה הרועים: </b>תו\"א לב, ב. וראה ז\"ח תקונים (קד, א).</p>\n<p><b>ירכה עד פרחה: </b>ראה לקו\"ת כאן.</p>"],[1200970163,"ח'תתלח\n\n<p>ב\"ה, כ\"ג סיון תשכ\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' הרב יצחק צבי שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו ובהמשך למה שנדבר עם הוריו שי' בשיחתנו, בו שואל.</p>\n<p>א) מאנ\"ש וחסידים המתעסקים באתרוגי קאלאברי הוא הרה\"ח רב פעלים הרר\"י שי' דזייקאבסאן (אשר כמדומה היו בקשרים זע\"ז מכבר) אשר הנ\"ל בעצמו ביקר בהפרדסים של אתרוגים אשר באיטליא ובחן בהם.</p>\n<p>ב) כן להנ\"ל ידוע בנוגע להסימנים והאופן איך להכיר שהאילן אינו מורכב.</p>\n<p>ג) במ\"ש אודות אופן גידול העוקץ וכן בנוגע להבליטות - יש לברר האם גדלים באותו אילן <b>עצמו</b> בבליטות וגם בלי בליטות, כן בהנוגע להשינוים בהעוקץ, כי כמדומה שבספרים לא נמצא ע\"ד פרטים כהנ\"ל שכותבם בתוככי סימנים באם נמצאו <b>באותו</b> האילן וצריך לברר אצל מי שהי' על אתר וראה בעצמו.</p>\n<p>ד) התקוה שלע\"ע כבר קבל פ\"ש מכאן מהוריו שי' וכן מהאורחים ממנשסתר שביקרו כאן בזמן מתן תורתנו, השבועות שלפניו ושלאחריו וכן מהמדובר בזמני רצון האמורים, ויהי רצון שיפעלו הדברים פעולתם מתאים לתוכנם שהמעשה הוא העיקר.</p>\n<p>בכבוד ובברכה לבשו\"ט ופ\"ש הוריו שי'.</p>\n<p>נ.ב. כבר מובא מס' בכורי יעקב סו\"ס תרמ\"ח דאין לסמוך על הסימנים גם לא להחמיר. ואף שהוא היפך דעת כו\"כ מהאחרונים - י\"ל שעכ\"פ גם לדעתם כשיש מסורת על המדינה ובאותו אילן עצמו גדלים אתרוגים בסימנים - גם שאר האתרוגים שבאילן כשרים (שהרי לכל הדעות סימנים <b>אלו</b> - לבד קליפתו עבה להחת\"ס - אינם מובהקים וכו').</p>\n<h4><i><b>ח'תתלח</b></i></h4>\n<p><b>הרב יצחק צבי:</b> ליברמן, מנשסטר. אגרת נוספת אליו - לעיל ח\"ג תקצ.</p>\n<p><b>שהמעשה:</b> אבות פ\"א מי\"ז.</p>\n<p><b>דאין.. הסימנים:</b> ראה גם לעיל ח\"י אגרת ב'תתקצח. ח\"ד אגרת תשפה.</p>"],[1200970164,"ח'תתלט\n\n<p>ב\"ה, כ\"ז סיון, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>צי די באטייליגטע אין דעם יערלעכן<br>\nלאנטשאן פון דעם נ.י.<br>\nקאמיטע פאר דעם סעמינאר למורות ובתי<br>\nספר מקצועיים<br>\nלנערות אין כפר חב\"ד בארצנו הקדושה ת\"ו<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>עס האט מיר געפרייט צו באקומען די ידיעה וועגן דעם פארקומענדן יערלעכן לאנטשאן א' דראש חודש תמוז הבע\"ל.</p>\n<p>דער חודש תמוז האט א ספעציעלע באדייטונג פאר יעדן איינעם און איינער פון אונז בתוך כלל ישראל. אין דעם חודש (י\"ב-י\"ג תמוז) איז, ווי באקאנט, באפרייט געווארן כ\"ק מו\"ח אדמו\"ר, דער נשיא פון אונזער דור, פון סאוויעטישער טורמע און פארשיקונג.</p>\n<p>די מסירות-נפש'דיקע-בפועל-ממש ארבעט פון כ\"ק מו\"ח אדמו\"ר צו אויפהאלטן און פארשפרייטן תורה און מצוות, בפרט אין דעם געביט פון <b>חינוך על טהרת הקדש,</b> איז אייך זיכער באקאנט. דאס איז איינע פון די אייביקע גייסטיקע ירושות וואס דער רבי דער שווער האט איבערגעלאזן פארן כלל ישראל און ספעציעל פאר יעדן מאן און פרוי וואס האבן א שייכות צו חב\"ד. פון דער ירושה שעפן מיר אלע פרישע כוחות פארצוזעצן זיין הייליקע ארבעט. די דאזיקע ארבעט איז אויך אן אונערשעפלעכער קוואל פון ג-טלעכע ברכות וואס דער רבי דער שווער האט געבענטשט יעדן איינעם און איינע וועלכע נעמען א חלק אין שטיצן זיינע מוסדות, בפרט די מוסדות חינוך על טהרת הקדש. אייער ארבעט האט נאך דערצו די מעלה וואס די מוסדות וועלכע איר שטיצט געפינען זיך בארצנו הקדושה אין כפר חב\"ד וואס כ\"ק מו\"ח האט געגרינדעט און געהאלטן אזוי טייער.</p>\n<p>השם יתברך זאל העלפן, אז אייער ארבעט זאל אנגיין מיט גרויס הצלחה, און זאל האלטן אין פארגרעסערן זיך, ווי אלע לעבעדיקע זאכן וואס לעבן און <b>וואקסן.</b> צוגלייך זאלן אויך מקויים ווערן אין א וואקסנדער מאס די ג-טלעכע ברכות וועלכע זיינען פארבונדן מיט דער ארבעט, בא אייך און אייערע בני בית שיחיו, אין אלץ וואס מען נויטיגט זיך, בגשמיות וברוחניות.</p>\n<p>בברכה להצלחה ולבשורות טובות.</p>\n<h4><i><b>ח'תתלט</b></i></h4>\n<p>נדפסה בלקו\"ש חל\"ג ע' 283 והושלמה עפ\"י העתק המזכירות.</p>"],[1200970165,"ח'תתמ\n\n<p>ב\"ה, כ\"ח סיון תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מכ\"ו סיון, בו שואל ע\"ד בן אחיו שי' הרוצה ללמוד שנים אחדות בישיבה, והשאלה אם יכנס אחרי כן בקבוץ דתי וכו'.</p>\n<p>ולדעתי כיון שהענין נוגע לאחרי שילמוד משך זמן בישיבה, לימוד תורתנו הק' תורת חיים, אשר כדברי רבנו הזקן בספר תניא קדישא שלו, שהתורה נקראת בשם לחם ומזון הנפש, וע\"י הלימוד כדבעי, מתאחדת עם נפש הלומד והיו לאחדים, ונעשה מזון לנפש וחיים בקרבה מחיי החיים אין סוף ברוך הוא וכו' (תניא פרק ה'),</p>\n<p>הרי עפי\"ז אין כדאי להחליט עתה מה שיעשה לאחרי לימוד האמור, שהרי התקוה ע\"פ האמור שיתעלה ע\"י לימוד זה, ויחליט בהתאם למצבו אז.</p>\n<p>התקוה חזקה אשר ידוע לכ' פרשת ימי י\"ב וי\"ג תמוז גאולת כ\"ק מו\"ח אדמו\"ר נשיא דורנו.</p>\n<p>ויהי רצון שיתעורר ויוסיף כאו\"א בעניני תורה ומצות ובהפצת היהדות ועניני' לקרוב ולרחוק ומתוך שמחה וטוב לבב.</p>\n<p>בברכה לבשו\"ט.</p>"],[1200970166,"ח'תתמא\n\n<p><i>[שלהי סיון]</i></p>\n<p>שאלת חלום וכיו\"ב - שייך ליחידי סגולה וכו', ובמקרים מיוחדים. וילמוד בהתמדה ושקידה ויתנהג כמצווה בשו\"ע וה' יצליחו.</p>\n<p>- לדבר עמי פא\"פ - שייך למזכ'.</p>\n<h4><i><b>ח'תתמא</b></i></h4>\n<p>נכתבה על גליון המכתב מיום ו' עש\"ק פ' שלח.</p>"],[1200970167,"ח'תתמב\n\n<p>ב\"ה, ערב ראש חודש תמוז, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>[מר שלום שי' לוין]</p>\n<p>שלום וברכה!</p>\n<p>זה עתה נתקבל מכתבו מיום ד' בסיון, שכנראה נתעכב מפני השביתה. נצטערתי לראות ממכתבו שלא קבל מענה שלי שנכתב לפני כמה וכמה חדשים.</p>\n<p>ובעמדנו ערב חודש הגאולה של כ\"ק מו\"ח אדמו\"ר, רצוני להדגיש בזה דבר בעתו בקישור עם מאסרו ושחרורו של כ\"ק מו\"ח אדמו\"ר, והוא עסקנותו בשטח החינוך, שעסק בזה משך נ\"ה שנה מימי חייו. בן שמונה עשר שנה הי' כשאביו מינהו למנהל פועל של ישיבת תומכי תמימים ליובאוויטש, אבל כבר מקודם לכן עסק בחינוך. ובכל ארצות נדודיו מיד בבואו התמסר לעבודת החינוך בראש וראשונה לכל שאר מפעליו. וכן הי' בארצות הברית שגם פה היתה ראשית עבודתו להקים רשת של מוסדות חינוך, התחל מפעולות בעד ילדים שאפילו א\"ב לא ידעו ועד שלב לימוד תורה לעומקה של הלכה, הן בתורת הנגלה והן בתורת הנסתר, תורת החסידות פנימיות התורה. וזו היתה עבודתו כל ימיו ועלי' מסר נפשו בפועל ממש בימי היבסקצי', אבל זכות פעולות אלו היא שעמדה לו לצאת לחירות וביד רמה.</p>\n<p>בודאי שאין כוונתי לספר פרשת יום הגאולה לשם כל המרבה לספר, אלא כמו שפירש בעל השמחה בעצמו ענין פרשת היום, הנה מאורעות הימים ההם צריכים להיות נר לרגלי כל אחד ואחד מאתנו להאיר לנו הדרך בניצול כל האפשריות ובכל השלבים בחינוך בני ובנות ישראל ברוח התורה והמסורה וערכי עמנו הנצחיים. ואם יש ענינים המונעים ומעכבים, מוכרח להתגבר עליהם אפילו אם נזקקים למדת מסירות נפש, ובפרט שאצלנו ב\"ה אין זקוקים למסירות נפש אלא מסירות הרצון, וסוף סוף האמת מנצחת.</p>\n<p>כדרך כל בני ישראל שחיבה יתרה נודעת להם בתור עם קשה עורף, הנני חוזר עוה\"פ לנקודה שדברנו בהפגשנו ואשר חזרתי עלי' במכתבי, ועכשו עוד הפעם. יסלח לי כ' אם מוכרחני להביא הסתייגותי מעמדתו שטקס הפרוטוקול מגדיר את מסגרת פעילותו וכל השאר לא שייך אליו וכו'. ולא כך קבלנו מבית רבינו ככתוב לעיל בענין הלימוד מפרשת הגאולה די\"ב-י\"ג תמוז. ואם תמצא לומר עמדתו של כ' לא הולמת את המושג המקיף של חכמינו ז\"ל שכדרכם בקדש הביעו בסגנון קצר - \"חייב אדם לומר בשבילי נברא העולם\", שיסודו של חיוב זה הוא בתפקידו של כל אחד מישראל להוציא לפועל את האחדות שבכל העולם והנקודה המשותפת שבשטחים הכי שונים בעולם - זאת אומרת שכל עניני העולם יש להם שייכות לכל יהודי ויכול הוא להיות שם מושל ושליט כאדם העושה בתוך שלו.</p>\n<p>ואם בכל השטחים כך, על אחת כמה וכמה בשטח החינוך, ובפרט בתקופתנו זו, שאפילו במקום ספק וס\"ס וכו\"כ ספקות, חייב יהודי לעשות כל האפשר לו ובכל מקום שידו מגעת, וה' יגמור בעדו.</p>\n<p>תקותי שכ' יציין את ימי הגאולה י\"ב-י\"ג תמוז באופן המתאים.</p>\n<p>בברכת חודש טוב ובשורות טובות.</p>\n<p>בוודאי למותר לכפול שינעם לי לקבל תגובתו על כל האמור ובלבד שיהי' בגלוי לב.</p>\n<h4><i><b>ח'תתמב</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ג ע' 239 והושלמה עפ\"י העתק המזכירות.</p>\n<p><b>מר שלום שי' לוין:</b> אגרות נוספות אליו - לעיל ח'תרפא, ובהנסמן בהערות שם.</p>\n<p><b>משך נ\"ה שנה:</b> ראה ס' השיחות תש\"ה ע' 78. תורת מנחם - התוועדויות תשי\"א ח\"א ע' 211. וש\"נ.</p>\n<p><b>בן שמונה עשר.. מנהל פועל:</b> ראה שלשלת היחס ור\"פ מתולדות בית רבינו ב\"היום יום\" בתחלתו. כרם חב\"ד גליון 3 ע' 14.</p>\n<p><b>מסירות.. הרצון:</b> ראה תורה אור מקץ לו, ב.</p>\n<p><b>בסגנון קצר:</b> סנהדרין לז, א.</p>"],[1200970168,"ח'תתמג\n\n<p>ב\"ה, א' תמוז תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מכ\"ד סיון, בו מונה אחדים מהבעיות המעסיקים אותו.</p>\n<p>ומתאים לגילו וע\"פ פתגם חכמנו ז\"ל, אם לא עכשיו אימתי, הרי עליו להשתדל ביותר שיוכל ללמוד בהתמדה ושקידה תורתנו הקדושה תורת חיים (שהתואר כולל גם הפירוש הוראה בחיים בעולמנו זה) ויהי' הלימוד מביא לידי מעשה כציווי חז\"ל בהאמור, והובטחנו, יגעת ומצאת.</p>\n<p>ולאחרי שירכוש ידיעות התורה במדה מסוימת ישוב לבעיות אודותם כותב ויתבונן בהם וימצא פתרונם.</p>\n<p>והרי נתינת התורה לכל עמנו בני ישראל היתה גם כן דוקא ע\"י הקדמת נעשה לנשמע.</p>\n<p>התקוה, שיש לו מכירים ומה שנוגע עוד יותר ידידים חרדים לדבר ה' ותורתו, שמכמה טעמים טוב הדבר וגם מוכרח, והרי כו\"כ נמצאים בתל אביב.</p>\n<p>ומהנכון אשר יבדקו את התפילין שלו - באם לא נעשה כזה במשך שנים עשר חדש האחרונים - ובכל יום חול קודם הנחת התפילין להפריש פרוטות אחדות לצדקה.</p>\n<p>בברכה לבשו\"ט בכל האמור.</p>\n<h4><i><b>ח'תתמג</b></i></h4>\n<p><b>פתגם חכמנו:</b> אבות פ\"א מי\"ד.</p>\n<p><b>כציווי חז\"ל:</b> קידושין מ, ב.</p>\n<p><b>והובטחנו:</b> מגילה ו, ב.</p>"],[1200970169,"ח'תתמד\n\n<p>ב\"ה, א' תמוז תשכ\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו מיום השני, בו כותב ראשי פרקים מאשר עבר עליהם ומסיים בסברות שונות ע\"ד הסתדרותם בעתיד הקרוב.</p>\n<p>וע\"פ שמתאר המצב ונמצאים הם כבר בארצוה\"ב אין כדאי לנסוע מכאן, כי אם לנצל ההיכירות שלו הקשרים ועבודתו כאן בשנים שעברו בחינוך על טהרת הקדש למען למצוא עבודה מתאימה בשבילו.</p>\n<p>והשי\"ת הזן ומפרנס את העולם כולו בטובו בחן ובחסד וברחמים ימציא להם פרנסתם במקום המתאים ובאופן המתאים.</p>\n<p>לכתבו אודות אמוץ ילד - בודאי ידועים לו הקישוים והתסבוכת הבאים בעקבות אמוץ; וקודם לכל איסור הקירוב חבוק ונשוק וכו' שכמעט אי אפשר להזהר מזה, אשר לכן קודם שיחליטו בזה יברר כל האמור ביחד עם רב מורה הוראה (שהרי הם הנוגעים בדבר).</p>\n<p>ומהנכון אשר יבדקו את התפילין שלו וכן את המזוזות בדירתם שתהיינה כולן כשרות כדין - באם לא נעשה כזה במשך שנים עשר חדש האחרונים -</p>\n<p>בעת רצון יזכירו אותו ואת זוגתו תחי' על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>בברכה לבשו\"ט בכל האמור,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א.</p>\n<h4><i><b>ח'תתמד</b></i></h4>\n<p><b>אודות אמוץ הילד:</b> ראה גם לעיל אגרת ח'תש, ובהנסמן בהערות שם.</p>"],[1200970170,"ח'תתמה\n\n<p>ב\"ה, בדר\"ח תמוז, ה'תשכ\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ כו'<br>\nמו\"ה אפרים שי'</p>\n<p>שלום וברכה!</p>\n<p>בזה הננו להודיעו את ההוראה שהואיל כ\"ק אדמו\"ר שליט\"א לתת לא' האברכים שי' בענין נסיעה לכאן, ואשר ההוראה הזאת שייכת גם לכל אנ\"ש והתלמידים שיחיו אשר חשקם לנסוע מזמן לזמן לכ\"ק אדמו\"ר שליט\"א.</p>\n<p>וזוהי ההוראה:</p>\n<p>... <b>ופשוט,</b> שאין כל מקום לנסיעה לכאן עוה\"פ - עד שישלם <b>כל</b> החובות שיש להם בכלל, שתהא פרנסת ב\"ב שיחיו מובטחת <b>במילואה</b> משך כל נסיעתו, שיהי' בידו <b>מזומן</b> כל ההוצאות רצו\"ש ודשהותו כאן.</p>\n<p>בטח יפרסם זה באופן המתאים, ות\"ח מראש.</p>\n<p>בברכת כט\"ס.</p>\n<p>הרב ח. מ. א. חדקוב</p>\n<h4><i><b>ח'תתמה</b></i></h4>\n<p><b>מו\"ה אפרים שי':</b> וולף. אגרות נוספות אליו - לעיל חי\"ח ו'תתקמג, ובהנסמן בהערות שם.</p>"],[1200970171,"ח'תתמו\n\n<p>ב\"ה, עש\"ק ג' תמוז ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו.</p>\n<p>ובעמדנו ערב ש\"ק פרשת אני חלקך ונחלתך, וידוע פס\"ד הרמב\"ם אשר לא בשבט לוי בלבד הדברים אמורים, \"אלא כל איש ואיש מכל באי העולם אשר נדבה רוחו אותו והבינו מדעו להבדל לעמוד לפני ה' לשרתו ולעבדו לדעה את ה' והלך ישר כמו שעשהו האלקים ופרק מעל צוארו עול החשבונות הרבים אשר בקשו בני האדם ה\"ז נתקדש קדש קדשים ויהי' הוי' חלקו ונחלתו לעולם ולעולמי עולמים ויזכה לו בעוה\"ז דבר המספיק לו כמו שזכה לכהנים וללוויים הרי דוד ע\"ה אומר ה' מנת חלקי וכוסי אתה תומיך גורלי\".</p>\n<p>יהי רצון שיוסיף כאו\"א בתכ\"י בהתמדה ושקידה בלימוד נגלה וחסידות ויהי' זה מתוך בריאות הנפש והגוף.</p>\n<p>והרי שבת זה גם התחלת גאולת כ\"ק מו\"ח אדמו\"ר נשיא ישראל, שהוא גם גאולתנו ופדות נפשנו.</p>\n<p>בברכה לבשו\"ט בעניני הפרט והכלל,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתמו</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש ח\"ח ע' 325 והושלמה עפ\"י צילום האגרת. וראה גם לקמן אגרת ח'תתנז. ט'כ. שיחת י\"ב תמוז תשכ\"ד.</p>\n<p><b>פס\"ד הרמב\"ם: </b>הל' שמיטה ויובל בסופן.</p>\n<p><b>כל איש ואיש: </b>ולא \"כל איש\" - כי כל אחד נשאר בסוגו הקודם גם לאחר שנדבה רוחו כו' (ראה מג\"א א, ח ובתרגום ומחז\"ל שם. תו\"א לז, ג עה\"פ תהלים פז, ה). ובנדו\"ד י\"ל שבכלל ב' סוגים הם אלה שתורתם אומנתם והשאר (ראה ברכות לה, ב. תו\"א ר\"פ תרומה).</p>\n<p><b>מכל באי העולם: </b>כולל גם או\"ה - ראה ר\"ה פ\"א מ\"ב (ומכאן ראי' לגירסת הרמב\"ם במשנה שם) - כי חסידי או\"ה יש להם חלק לעוה\"ב (רמב\"ם הל' מלכים ספ\"ח).</p>\n<p><b>נדבה רוחו אותו: </b>שמות (לה, כא). ונדיבות ה\"ה מדת הלב (ראה רמב\"ן שם).</p>\n<p><b>והבינו מדעו: </b>שכל שבמוח.</p>\n<p><b>להבדל.. נתקדש קדש קדשים: </b>וע\"ד דה\"א (כג, יג) האמור בכהנים [וכה\"ג, דמתאים לשם קדה\"ק, כי רק הוא נכנס לשם. וראה חדא\"ג סוף הוריות. זח\"ג קעו, ב. ב\"ק לח, א].</p>\n<p><b>לעמוד.. לשרתו: </b>דברים י, ח.</p>\n<p><b>לשרתו ולעבדו: </b>ראה מנחות קט, ב.</p>\n<p><b>ישר.. בקשו: </b>ראה קהלת ז, כט.</p>\n<p><b>לעולם ולעולמי עולמים: </b>ל' הספרי דברים כג, ז.</p>\n<p><b>לכהנים וללוויים: </b>כן הוא ברמב\"ם דפוס רומי.</p>\n<p><b>הרי דוד: </b>אף שלא הי' משבט לוי.</p>\n<p><b>אומר: </b>תהלים טז, ה.</p>\n<p><b>תומיך גורלי: </b>רק תומיך, כי צ\"ל מלאכה מעט (רמב\"ם הל' ת\"ת פ\"ג ה\"ט. וראה הל' ת\"ת לאדה\"ז פ\"ג ס\"ג) וכדיוק הרדב\"ז כאן. אבל קשה דא\"כ אינו \"כמו שזכה לכהנים\". ואולי מכאן ראי' להכס\"מ (בהל' ת\"ת שם) די\"ל דהרמב\"ם שולל רק את המשים על לבו כו'.</p>\n<p>ולכן יש ב' אופנים: ה' מנת חלקי, או תומיך גורלי. ואכ\"מ.</p>"],[1200970172,"ח'תתמז\n\n<p>ב\"ה, עש\"ק ג' תמוז, ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>הרה\"ג הרה\"ח אי\"א נו\"נ עוסק בצ\"צ צנמ\"ס<br>\nכו'<br>\nמו\"ה שלמה יוסף שי'</p>\n<p>שלום וברכה!</p>\n<p>... מסיבה נתעכב משלוח מכתב זה, ובינתים ביקרני הרה\"ג וכו' וכו' הרא\"י שי' ושוחחנו ארוכות ע\"ד כמה ענינים, ואעתיק בזה נקודות מהם, כיון שתקותי שלעת מצוא יוכל כת\"ר לעשות בזה להביא הדברים לידי פועל.</p>\n<p>א) בענין האניות - אמר לי הנ\"ל בפירוש, שמעולם לא הוא ולא רבנות הראשית נתנה היתר בדבר [אלא שלדעתו, להנוסעים באני' (משא\"כ - להצוות) הרי זה איסור דרבנן. ולא רציתי להתעכב על נקודה זו, שהרי גם איסור דרבנן ובמשך כ\"ד שעות המעל\"ע ובפרהסיא \"תופס מקום\", ורק רמזתי שלדעת כמה פוסקים (הרמב\"ן, שו\"ת חת\"ס הידוע, ועוד) גם דאורייתא הוא, ואכמ\"ל, אלא ש]נצלתי ההזדמנות לדבר עוה\"פ ע\"ד האפשריות לעגן האניות לשעות הש\"ק, וכנראה מרושמי הפנים - יש מקום שימשיך הנ\"ל להתענין באפשריות האמורה, אף שמענתו היתה, שלפי ידיעתו אין סיכו[יי]ם שיסכימו על זה, וגם ע\"ז עניתיו, שמכמה סיבות טכניות מוכרח העגון בלאה\"כ אחת לימים אחדים, ותלוי ברצון הטוב שיכוונו העגון ליום הש\"ק.</p>\n<p>ב) הדגשתי וכ\"פ - <b>שמוכרח</b> לעשות מה בנוגע להיתר נשואין [באחב\"י הספרדים] בגיל מוקדם להמותר ע\"פ החוק דכנסת, ומכמה טעמים: לכל לראש - כיון שגם עתה ישנם <b>כו\"כ</b> מקרים דאירוסין וקדושין וגם נשואין, ושמפני החוק נעשים בצנעא, ומובן הקלקול שבדבר. ועוד -</p>\n<p>וגם זה עיקר - שבדורנו, הלואי שגם האשכנזים היו משיאים בניהם ובנותיהם קרוב לפרקם ולא כהמצב בהווה, ועאכו\"כ בנוגע הספרדים שמאז ומקדם הורגלו בכהנ\"ל.</p>\n<p>וגודל התקון - אין די באר. והבטיח שבהזדמנות יתענין בהאפשריות עכ\"פ להוריד גיל הנשואין לשנה וכיו\"ב.</p>\n<p>ג) בשאלת \"מרבק\" המפורסם במכ\"ע, שלדעתי מכשול וגדול בדבר שהשחיטה תכנס לידי ארגון כללי - שע\"פ דרך הטבע, סו\"ס יהי' [...] בעה\"ב היחיד או עכ\"פ המכריע בזה.</p>\n<p>וכיון שלע\"ע, בכל ארגונים הכללים דעה המכרעת היא להחילונים, מובנת הפרצה שיכולה לצאת ולצמוח מזה ר\"ל, ואף שטעם וחשש האמור - צע\"ג אם ישכנע דעת הצבור, הנה יש לנצל בכגון זה התנגדות הסוחרים בבשר כשר היראים לפרנסתם, והתנגדות שבודאי תהי' מכמה עיירות שאחד מקורי הכנסתם הוא ענין בשר כשר, ועוד.</p>\n<p>ולדעתי הדרך היחידה לביטול תכנית האמורה הוא אך ורק ע\"י הלחץ המפלגתי על הקבוצים הדתיים השותפים בהאמור - שיצאו מהנ\"ל, שאז אפילו אם השותפים הנשארים ימשיכו, עכ\"פ לא תהי' בידם הרשות היחידה, וק\"ל.</p>\n<p>מוסג\"פ העתק המברק ליציאתו של הנ\"ל מארצוה\"ב.</p>\n<p>עוד להוסיף בהאמור - שכנראה מדברי הנ\"ל אודות כת\"ר מתחשב <b>הרבה</b> בדבריו ובדעתו.</p>\n<p>יבקר עתה באה\"ק ת\"ו הרב הר\"ש שי' עלברג, ואחזור בזה על מה שכתבתי מאז - ע\"ד טענתו של הר\"ש שי' (במענה לבקשתי להנ\"ל ע\"ד חוברת \"הפרדס\" מוקדשת לאדה\"ז) שמחכה בזה למאמרו של כת\"ר בעל משקל בנוגע לאדה\"ז ספריו ושיטתו (או אחת משלש אלה).</p>\n<h4><i><b>ח'תתמז</b></i></h4>\n<p><b>מו\"ה שלמה יוסף:</b> זוין. אגרות נוספות אליו - לעיל ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>הרא\"י:</b> אונטרמן.</p>\n<p><b>בענין האניות:</b> ראה גם לעיל אגרת ח'תשלא, ובהנסמן בהערות שם.</p>\n<p><b>אמר לי:</b> ראה גם לקמן אגרת ח'תתסז.</p>\n<p><b>הדגשתי וכ\"פ:</b> ראה גם לעיל ח\"כ אגרת ז'תקצז.</p>\n<p><b>מוסג\"פ העתק המברק:</b> נדפס לקמן אגרת ח'תתסה.</p>\n<p><b>מה שכתבתי:</b> לעיל אגרת ח'תתיט.</p>"],[1200970173,"ח'תתמח\n\n<p>ב\"ה, מוצש\"ק פ' אני חלקך ונחלתך בתוך בנ\"י</p><p>ה'תשכ\"ד. ברוקלין, נ.י.<br>\nכבוד משתתפי שיעור-לימוד ספר התניא בבית הכנסת<br>\nשונה הלכות, בעיר נתניא בארצנו הק' ת\"ו ב\"ב ע\"י משיח צדקנו<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי הידיעה אשר סיימו חלק הראשון מספר תניא קדישא,</p>\n<p>ובודאי ע\"פ סגנון הידוע \"מתכיפין התחלה להשלמה\", התחילו תיכף חלק שני, הוא שער היחוד והאמונה (והקדמתו).</p>\n<p>וכתוכן סיום חלק הראשון: כי ה' אלקיך אש אוכלה הוא וכמ\"ש במ\"א.</p>\n<p>- ואולי י\"ל שהכוונה בזה לד\"ה כי ביום הזה יכפר (לקוטי תורה ר\"פ אחרי) -</p>\n<p>אשר המשל דאש אוכלה הוא, שכמו שהאש אינו נתפס להקרא בשם אור ואש כלל ואינו מאיר למטה כי אם ע\"י שנאחז בדבר גשמי וגם \"אוכל\" ומכלה אותו - כן הוא ג\"כ בנוגע לה' (שנעשה) אלקיך (כחך וחיותך), אשר מאיר ומתגלה למטה ע\"י תרי\"ג מצות דוקא, כמבואר בקצרה גם בסיום פרק ג\"ן, הוא סיום חלק הראשון.</p>\n<p>אשר קיומם באמת הוא ע\"י האהבה, שהיא שורש ויסוד לקיום כל מ\"ע (שכולל גם מצות היראה שהיא שורש ויסוד לקיום) כל מל\"ת, עבודת אהרן שהוא אוהב (וממשיך אהבה אפילו) את הבריות, בריות בעלמא.</p>\n<p>ויהי רצון אשר יהי' גדול הלימוד האמור כי יביא לידי מעשה קיום המצות, אשר כדברי בעל התניא רבנו הזקן כאו\"א ילך בדרך ישרה אשר הורנו מדרכיו ונלכה באורחותיו נס\"ו.</p>\n<p>זאת בעבודת ה' במילי דשמיא, ובמילי דעלמא ישתכח יתיר בברכת ה', וכל הקרוב קרוב - קודם לברכה.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתמח</b></i></h4>\n<p><b>ובודאי:</b> בהבא לקמן ראה גם לעיל חכ\"ב אגרת ח'תרכו.</p>\n<p><b>אני חלקך ונחלתך: </b>ראה רמב\"ם סוף הל' שמיטה ויובל.</p>\n<p><b>בתוך בנ\"י: </b>ראה אגה\"ק סכ\"ג.</p>\n<p><b>תניא קדישא: </b>לשון הסכמות דהוצאת התניא זאלקווי תקנ\"ט.</p>\n<p><b>סגנון הידוע: </b>ב\"רשות לחתן בראשית\".</p>\n<p><b>אינו נתפס כו': </b>ראה לקו\"ת שם.</p>\n<p><b>אור ואש.. נאחז.. ומכלה: </b>להעיר משו\"ע רבנו הזקן או\"ח סתצ\"ה קו\"א סק\"ב.</p>\n<p><b>קיומם באמת: </b>ראה תניא פ\"ד.</p>\n<p><b>שהיא שורש כו': </b>ראה הקדמת ח\"ב דתניא.</p>\n<p><b>עבודת אהרן: </b>לקו\"ת ר\"פ בהעלותך ובפי' עד ירכה שם.</p>\n<p><b>בריות בעלמא: </b>תניא פ' לב.</p>\n<p><b>גדול הלימוד: </b>ראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ג.</p>\n<p><b>כדברי בעל.. קודם לברכה: </b>אגה\"ק סי' ז\"ך.</p>"],[1200970174,"ח'תתמט\n\n<p>ב\"ה, ז' תמוז, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>תלמידות המסיימות ביה\"ס היסודי בית<br>\nרבקה בכפר חב\"ד<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>בנועם קבלתי הודעתן שעומדות לסיים בית הספר היסודי בית רבקה ולהמשיך בלימודים בסמינר למורות בית רבקה.</p>\n<p>יתן השי\"ת שכשם שמסיימות את בית הספר היסודי כן תכנסנה להסמינר למורות בית רבקה ותזכינה לסיימו בהצלחה מופלגה, חדורות יראת ה' ומדות טובות וספוגות אור וחיות חסידותיים, ומעשה הוא העיקר בהנהגה טובה בחיי היום-יום ובהשפעה טובה, כיאות לבנות ישראל שכל אחת היא בת שרה רבקה רחל ולאה. ואין הדבר תלוי אלא ברצונן, והשי\"ת יצליחן בגשמיות וברוחניות גם יחד, לשמחת הוריהן ומוריהן וכל רואיהן.</p>\n<p>בברכה לבשורות טובות.</p>\n<h4><i><b>ח'תתמט</b></i></h4>\n<p><b>ומעשה הוא העיקר:</b> אבות פ\"א מי\"ז.</p>"],[1200970175,"ח'תתנ\n\n<p>ב\"ה, שביעי בחודש תמוז, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד הוו\"ח אי\"א נו\"מ בחור מעם ומורם<br>\nמעם ודורש טוב<br>\nלעמו בעל מדות תרומיות ענף עץ אבות<br>\nמו\"ה שניאור זלמן<br>\nשליט\"א</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי הבשורה שבית הכנסת ומרכז תורני וחינוכי לנוער שיוקם בכפר חב\"ד, הנה על פי הצעת המנדב שי' ייקרא על שמו של כ'. וכמובן ששמחתי לידיעה זו, אף שאין ענין סמלי זה לחוד מעריך ומדגים את מפעליו הכבירים בעניני כפר חב\"ד.</p>\n<p>ומסופקני אם המנדב הנכבד מכיר בחלקו הכי פעיל של כ' בהתיסדות הכפר.</p>\n<p>ומשנה שמחה הי' להוודע שהנחת אבן הפינה של בנין הנ\"ל תהי' קשורה עם חגיגת ימי הגאולה י\"ב-י\"ג תמוז ושנת הט\"ו ליסוד כפר חב\"ד, שיתיחדו בזה כל ג' הבחינות עולם שנה נפש, וכמו שרמזתי במברק למר יצחק אייזיק וואולפסאן שי', שהעתקתו מצ\"ב.</p>\n<p>ובודאי שכ' ישתתף אישית בטקס החגיגות הנ\"ל, נוסף שבטח בין כך הי' נוכח בכפר חב\"ד בימי הגאולה וסגולה אלו.</p>\n<p>בהוקרה בכבוד ובברכת חג הגאולה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>בהזדמנות זו מוסג\"ב גם העתק מכתבי למר שלום שי' לוין, שתקותי שיענין את כ'.</p>\n<h4><i><b>ח'תתנ</b></i></h4>\n<p>נדפסה בלקו\"ש חכ\"ג ע' 371 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מו\"ה שניאור זלמן:</b> שזר. אגרות נוספות אליו - לעיל ח'תרפב, ובהנסמן בהערות שם.</p>\n<p><b>בית הכנסת.. שמו:</b> ראה גם אגרת ח'תתנא. ח'תתנג.</p>\n<p><b>העתק מכתבי:</b> דלעיל ח'תתמב.</p>"],[1200970176,"ח'תתנא\n\n<p>ב\"ה, ח' תמוז, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכל המתועדים בהתועדות ימי הגאולה<br>\nי\"ב-י\"ג תמוז אשר<br>\nבכפר חב\"ד - מיסודו של כ\"ק מו\"ח אדמו\"ר<br>\nבעל השמחה<br>\n- באה\"ק ת\"ו ע\"י מ\"צ במהרה בימינו<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בימי סגולה אלו הבאים עלינו ועל כל ישראל לטובה, אשר כמה שמחות נצטרפו ביחד -</p>\n<p>ימי גאולת כ\"ק מו\"ח אדמו\"ר, אשר היא גם גאולתנו ופדות נפשנו,</p>\n<p>חמש עשרה שנה ליסוד כפר חב\"ד - יהי רצון אשר יתפשט ויתרחב בכל המובנים, ובנקודה התיכונה והפנימית - להיות מרכז ממנו יפוצו המעיינות, מעיינות תורת החסידות בכל ארצנו הק' ת\"ו,</p>\n<p>הנחת אבן פינה לבית הכנסת החדש וגם מרכז לנוער אחב\"י ה' עליהם יחיו -</p>\n<p>יתן השם יתברך אשר, עפ\"י הידוע ששמחה פורצת גדר, תצטרפנה כל שמחות אלו לפרוץ הגדרים וההגבלות המונעים התפשטות הטוב והקדושה - ואין טוב אלא תורה ומצוותי', תורתנו תורת חיים ומצוותי' עליהן נאמר וחי בהם - עד אשר גם בחיי היום-יום תתראה האחדות של ישראל אורייתא וקוב\"ה, מתוך הרחבה בגשם וברוח,</p>\n<p>ומגאולה האמורה - לגאולת כל אחינו בני ישראל בגאולה האמתית והשלמה על ידי משיח צדקנו ולקיום היעוד ופרצת ימה וקדמה וצפונה ונגבה.</p>\n<p>בכבוד ובברכת לחיים לחיים ולברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתנא</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ח ע' 473 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>עפ\"י הידוע:</b> ראה ד\"ה שמח תשמח תרנ\"ז ע' 49 (סה\"מ תרנ\"ז ע' רכג).</p>\n<p><b>ואין טוב:</b> אבות פ\"ו מ\"ג.</p>"],[1200970177,"ח'תתנב\n\n<p>ב\"ה, ח' תמוז, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>אגודת נשים דבראנזוויל ואיסט-ניו-יארק<br>\nה' עליהן תחיינה</p>\n<p>ברכה ושלום!</p>\n<p>עס האט מיר געפרייט צו באקומען די ידיעה, אז אייער לאנטשאן און</p>\n<p>\"שלוס-מיטינג\" וועט פארקומען אין דעם ליכטיגען טאג פון י\"ב תמוז, יום הגאולה פון כ\"ק מו\"ח אדמו\"ר.</p>\n<p>אייער ארבעט איז פארבונדן מיט די מוסדות און טעטיקייטן פאר וועלכע דער בעל-הגאולה האט זיך מוסר נפש געווען, ווי עס איז אייך אלעמען זיכער באקאנט די געשיכטע פון זיין ארעסט און באפרייאונג.</p>\n<p>די ימי הגאולה י\"ב-י\"ג תמוז לערנען אונז, אז ווען מען טוט מיט אן אמת פאר תורה און אידישקייט און פאר מוסדות חינוך על טהרת הקדש, העלפט דער אויבערשטער ניט נאר איבערצוקומען די שווערסטע שטערונגען נאר אויך מצליח צו זיין אין אן איבערנאטירלעכע מאס.</p>\n<p>איך וויל האפן, אז אלע באטייליגטע אין דער אונטערנעמונג וועלן דערמוטיקט און באגייסטערט ווערן פון די אפלערנונגען פון די ימי-הגאולה, און אז דער \"שלוס-מיטינג\" וועט זיין א גוטע צוגרייטונג צום \"אנפאנג-מיטינג\" פון דעם נייען סעזאן הבע\"ל, מיט דערפרישטע כוחות און מיט נאך מער לעבעדיקייט און ווארעמקייט ווי פריער.</p>\n<p>השם יתברך זאל מצליח זיין אייער ארבעט אין אלע געביטן, סיי אין פארנעם סיי אין אינהאלט, אין א שטייגענדער מאס; און דאס זאל ברענגען אייך און אייערע בני בית שיחיו דעם אויבערשטנ'ס ברכות אין אלץ וואס מען נויטיגט זיך, בגשמיות וברוחניות.</p>\n<p>בברכה להצלחה ולבשורות טובות,</p>\n<p><b>מ. שניאורסאהן</b></p>"],[1200970178,"ח'תתנג\n\n<p>ב\"ה, ערב ימי הגאולה י\"ב-י\"ג תמוז, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>לכבוד מר משה שי' יפה</p>\n<p>שלום וברכה!</p>\n<p>בטח קבל העתק המברק ששלחתי להנחת אבן הפינה.</p>\n<p>ובזה רצוני להביע לכ' בפרט עוד הפעם תשואות חן חן בעד השתדלותו ועזרתו עד עתה, אשר להבא בודאי יוסיף כציווי חכמינו ז\"ל להעלות בקדש. ברם בהכירי משפחתו ובידעי את כ' לכאורה אין מקום לנתינת תודה בענין כזה, אף על פי כן לגודל הענין וגודל הנחת-רוח הגדתי לו רחשי לבי במפורש.</p>\n<p>ויהי רצון אשר ימי סגולה אלו יעוררו בכל אחד ואחד מאתנו התעוררות אמתית ללכת בעקבותיו של בעל הגאולה ולהמשיך עבודתו ומפעליו ומוסדותיו הק' להחזקת והפצת התורה ומצוותי' בחיי היום-יום, באופן דמוסיף והולך, וזכותו יעמוד לכ' ולכל אחד מאתנו להצליח בהצלחה מופלגה, בגשמיות וברוחניות גם יחד.</p>\n<p>בכבוד ובברכה.</p>\n<h4><i><b>ח'תתנג</b></i></h4>\n<p><b>מר משה יפה:</b> אגרות נוספות אליו - לעיל ח'תשד, ובהנסמן בהערות שם.</p>\n<p><b>להנחת אבן הפינה:</b> לבית שזר בכפר חב\"ד. ראה גם לעיל אגרת ח'תתנ-א.</p>\n<p><b>כציווי חכמינו:</b> ברכות כח, א. וש\"נ.</p>"],[1200970179,"ח'תתנד\n\n<p>ב\"ה, ערב ימי הגאולה י\"ב-י\"ג תמוז, תשכ\"ד</p><p>ברוקלין, נ.י.</p><p>תלמידי ישיבת תומכי תמימים ליובאוויטש<br>\nלחג הסיום,<br>\nמאנטרעאל<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>דעם חג הסיום - וואס קומט פאר באלד אויף מארגען נאך די ימי הגאולה פון כ\"ק מו\"ח אדמו\"ר, נשיא ישראל, דער מייסד פון ישיבת תומכי-תמימים ליובאוויטש אין מאנטרעאל - וועט זיכער שטיין אונטער דעם איינדרוק פון די דאזיגע באדייטונגספולע טעג.</p>\n<p>די מסירות נפש פון כ\"ק מו\"ח אדמו\"ר פאר מוסדות התורה און פאר תלמידי הישיבות און פאר אלע ענינים פון תורה און מצוות, וואס האט געבראכט צו זיין לעבנס-געפערלעכן ארעסט, האט אויך געבראכט זיין נסים'דיגע באפרייאונג. און דאס דארף אונז שטענדיג דינען אלס דערמאנונג - וואס דארף אראפקומען אין מעשים בפועל - אז מסירת נפש פאר תורה און מצוות, ניט נאר פאר זיך נאר אויך פאר א צווייטן אידן, מוז זיגן אפילו קעגן די שטארקסטע שטערונגען; קל-וחומר ווען די שטערונגען זיינען גאר קליינע, אדער ניט מער ווי איינגעבילדעטע.</p>\n<p>און כאטש קיינער קען זיך ניט פארגלייכן, אין כוחות און מסירות נפש, צום בעל הגאולה, דארף מען אבער אויך ניט פארגעסן, אז אלס רועה נאמן און נשיא פון אונזער דור האט דער בעל הגאולה אנגעצונדן אין יעדן איינעם פון אונז א גליענדן פונק פון מסירת נפש און צוגאב-כוחות צו קענען נאכגיין אין דעם וועג וואס ער האט פאר אונז אויסגעטראטן.</p>\n<p>איך האף אז יעדער איינער פון די תלמידים מסיימים - וואס דער \"סיום\" איז ניט מער ווי א צוגרייטונג צו דער התחלה פון א העכערע מדרגה - וועט פארזעצן דעם לימוד התורה, נגלה און חסידות, און קיום המצוות, מיט א פארגרעסערטע מאס מסירת נפש - מסירת הרצון - און מיט א שטייגענדער התמדה ושקידה והידור, און וועט אויך אויסניצן די פולסטע השפעה אויף אנדערע אין דער זעלבער ריכטונג.</p>\n<p>והשם יתברך יצליחם בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה להצלחה מופלגה ולבשורות טובות,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתנד</b></i></h4>\n<p>נדפסה בלקו\"ש חי\"ג ע' 241 והושלמה עפ\"י צילום האגרת.</p>\n<p><b>מסירת.. הרצון:</b> ראה תורה אור מקץ לו, ב. ועוד.</p>"],[1200970180,"ח'תתנה\n\n<p><i>[נוסח המברק לקראת י\"ב-י\"ג תמוז תשכ\"ד]</i></p>\n<p>התוועדויות פעילות ולהמשיכה בכל השנה.</p>\n<p><b>/מקום החתימה/</b></p>\n<h4><i><b>ח'תתנה</b></i></h4>\n<p>נדפס בלקו\"ש חכ\"ג ע' 390.</p>"],[1200970181,"ח'תתנו\n\n<p>ב\"ה, י\"ב תמוז ה'תשכ\"ד</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו</p>\n<p>ובעמדנו ביום גאולה זה, אשר כביאור בעל הגאולה במכתבו לחגיגת י\"ב תמוז הראשונה, הוא \"יום חג גאולת ישראל העוסקים בהרבצת תורה\", הרבצה</p>\n<p>דוקא - בתלמידים רבים (וכההמשך במכתבו \"תורה דרבים\"), ובל' הרמב\"ם \"להורות דרכיו הישרים ומשפטיו הצדיקים לרבים\".</p>\n<p>עסק בהרבצת תורה ע\"י שבעצמם מלמדים ולומדים תורה ברבים או ע\"י שתומכים בממונם ובטרחתם במוסדות ושיעורי תורה דרבים או מייסדים חדשים או בכל אופנים האמורים גם יחד.</p>\n<p>יהי רצון שיעשה בזה כאו\"א ככל הדרוש ותקוים במילואה ברכת בעל הגאולה (במכתבו האמור) כי ישפיע ה' להם, בתוך כלל אחב\"י יחיו, שפעת חיים וברכה מרובה עד בלי די.</p>\n<p>בברכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'תתנו</b></i></h4>\n<p>כללי פרטי. נדפסה בלקו\"ש חי\"ג ע' 242 (בתאריך כ\"ג תמוז) והושלמה עפ\"י צילום האגרת.</p>\n<p><b>במכתבו:</b> נדפס ג\"כ באג\"ק שלו ח\"ב אגרת שפו.</p>\n<p><b>הרבצה דוקא:</b> ראה גם שיחת י\"ב תמוז תשכ\"ד.</p>\n<p><b>במכתבו לחגיגת: </b>נדפס בס' המאמרים תש\"ח ע' רסג.</p>\n<p><b>הרבצת.. רבים: </b>ראה מגילה כט, א. תשבי מע' רבץ.</p>\n<p><b>ובל' הרמב\"ם: </b>סוף הל' שמיטה ויובל עיי\"ש. ומבואר בארוכה יותר במ\"א.</p>\n<p><b>מלמדים.. שתומכים בממונים ובטרחתם.. גם יחד: </b>להעיר מכתובות (קג, ב): דאייתינא כיתנא כו' וכתיבנא חמשא חומשי כו' ומתנינא כו' והיינו דא\"ר כמה גדולים. ובאורחות צדיקים שי\"ז: נדיב בממון בגוף בחכמה (נתבאר בד\"ה אשר ברא (ואילך) תרפ\"ט).</p>\n<p><b>עד בלי די: </b>ראה שבת לב, סע\"ב. זח\"ג קי, ב.</p>"]]});
